// Saneamento de mojibake em runtime (rede de seguranca para texto vindo
// de API/banco). Os arquivos-fonte ja estao limpos; este normalizador
// reverte CP1252 double-encoding de forma exata por codepoint, sem
// depender de tabela literal de mojibake (que era fragil).
const MOJIBAKE_TEXT_PATTERN = /[ÃÂ�]|â[€-™]/;
const MOJIBAKE_REPLACEMENTS = new Map();

// CP1252: codepoint Unicode -> byte original (slots 0x80-0x9F especiais).
const CP1252_REVERSE = {
  0x20AC: 0x80, 0x201A: 0x82, 0x0192: 0x83, 0x201E: 0x84, 0x2026: 0x85,
  0x2020: 0x86, 0x2021: 0x87, 0x02C6: 0x88, 0x2030: 0x89, 0x0160: 0x8A,
  0x2039: 0x8B, 0x0152: 0x8C, 0x017D: 0x8E, 0x2018: 0x91, 0x2019: 0x92,
  0x201C: 0x93, 0x201D: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02DC: 0x98, 0x2122: 0x99, 0x0161: 0x9A, 0x203A: 0x9B, 0x0153: 0x9C,
  0x017E: 0x9E, 0x0178: 0x9F
};

function decodeLatin1Utf8(text = "") {
  const source = String(text || "");
  const bytes = [];
  for (const char of source) {
    const cp = char.codePointAt(0);
    if (CP1252_REVERSE[cp] !== undefined) {
      bytes.push(CP1252_REVERSE[cp]);
    } else if (cp <= 0xff) {
      bytes.push(cp);
    } else {
      // Caractere fora de CP1252: nao e mojibake reversivel.
      throw new Error("nao reversivel");
    }
  }
  return new TextDecoder("utf-8", { fatal: true }).decode(Uint8Array.from(bytes));
}

function normalizeVisibleText(text = "") {
  let normalized = String(text ?? "");
  if (!normalized || !MOJIBAKE_TEXT_PATTERN.test(normalized)) {
    return normalized;
  }
  for (let iteration = 0; iteration < 4; iteration += 1) {
    if (!MOJIBAKE_TEXT_PATTERN.test(normalized)) {
      break;
    }
    try {
      const decoded = decodeLatin1Utf8(normalized);
      if (decoded && decoded !== normalized) {
        normalized = decoded;
      } else {
        break;
      }
    } catch (error) {
      break;
    }
  }
  return normalized;
}

function normalizeVisibleMojibake(root = document.body) {
  if (!root) {
    return;
  }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let currentNode = walker.nextNode();
  while (currentNode) {
    const parentTag = currentNode.parentElement?.tagName || "";
    if (!["SCRIPT", "STYLE", "TEXTAREA"].includes(parentTag)) {
      const nextValue = normalizeVisibleText(currentNode.nodeValue || "");
      if (nextValue !== currentNode.nodeValue) {
        currentNode.nodeValue = nextValue;
      }
    }
    currentNode = walker.nextNode();
  }

  root.querySelectorAll("[placeholder],[title],[aria-label],[alt]").forEach((element) => {
    ["placeholder", "title", "aria-label", "alt"].forEach((attributeName) => {
      if (!element.hasAttribute(attributeName)) {
        return;
      }
      const currentValue = element.getAttribute(attributeName) || "";
      const nextValue = normalizeVisibleText(currentValue);
      if (nextValue !== currentValue) {
        element.setAttribute(attributeName, nextValue);
      }
    });
  });
}

function scheduleVisibleMojibakeNormalization(root = null) {
  if (root && root.nodeType === Node.ELEMENT_NODE) {
    mojibakePendingRoots.add(root);
  } else if (root && root.nodeType === Node.TEXT_NODE && root.parentElement) {
    mojibakePendingRoots.add(root.parentElement);
  } else if (!root) {
    mojibakePendingRoots.add(document.body);
  }
  if (mojibakeNormalizationScheduled) {
    return;
  }
  mojibakeNormalizationScheduled = true;
  requestAnimationFrame(() => {
    mojibakeNormalizationScheduled = false;
    const roots = Array.from(mojibakePendingRoots);
    mojibakePendingRoots.clear();
    roots.forEach((item) => normalizeVisibleMojibake(item));
  });
}

function ensureMojibakeObserver() {
  if (mojibakeObserver || typeof MutationObserver === "undefined") {
    return;
  }
  mojibakeObserver = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.TEXT_NODE || node.nodeType === Node.ELEMENT_NODE) {
          scheduleVisibleMojibakeNormalization(node);
        }
      });
    });
  });
  mojibakeObserver.observe(document.body, {
    childList: true,
    subtree: true
  });
}

function getAuthToken() {
  return localStorage.getItem("aerostore_auth_token") || "";
}

function getRoleLabel(role) {
  const normalizedRole = String(role || "").trim().toLowerCase();
  if (normalizedRole === "admin" || normalizedRole === "administrator" || normalizedRole === "administrador") return "Administrador";
  if (normalizedRole === "manager" || normalizedRole === "gerente" || normalizedRole === "gestor") return "Gestor";
  if (normalizedRole === "seller" || normalizedRole === "vendedor") return "Vendedor";
  if (normalizedRole === "cashier" || normalizedRole === "caixa") return "Caixa";
  if (normalizedRole === "consult" || normalizedRole === "consulta" || normalizedRole === "readonly") return "Consulta";
  return "-";
}

function getCurrentUserStoreLabel() {
  const currentStoreId = getCurrentPdvStoreId();
  if (currentStoreId) {
    return getPdvStoreDisplayName(currentStoreId, formatStoreIdLabel(currentStoreId));
  }
  const fallbackStoreId = normalizePdvStoreIdentifier(state.currentUser?.store_label || state.currentUser?.store || state.currentUser?.store_id || "");
  return fallbackStoreId ? formatStoreIdLabel(fallbackStoreId) : "-";
}

function getOfficialStoreOptions() {
  return [
    { value: "vila", label: "Vila" },
    { value: "botanico", label: "Botânico" },
    { value: "sul", label: "Sul" }
  ];
}

function normalizeAuthUserStoreContext(user = null) {
  if (!user || typeof user !== "object") {
    return user;
  }
  const allowedStores = toArray(user.allowed_stores || user.allowedStores)
    .map((item) => normalizePdvStoreIdentifier(item))
    .filter(Boolean);
  const activeStoreId = normalizePdvStoreIdentifier(
    user.active_store_id
    || user.activeStoreId
    || user.active_store
    || user.store_id
    || user.store
    || user.loja
    || user.store_label
    || allowedStores[0]
    || ""
  );
  const primaryStoreId = normalizePdvStoreIdentifier(user.primary_store_id || user.primaryStoreId || user.store_id || user.store || activeStoreId || "");
  const roleKey = normalizeText(user.role || user.role_key || user.profile || "").toLowerCase();
  const hasAllStores = Boolean(user.permissions?.can_view_all_stores) || roleKey === "admin";
  const hasFixedOperationalStore = ["seller", "vendedor", "cashier", "caixa"].includes(roleKey);
  const normalizedAllowedStores = hasAllStores
    ? Array.from(new Set([...allowedStores, "vila", "botanico", "sul"]))
    : hasFixedOperationalStore
      ? (primaryStoreId ? [primaryStoreId] : [])
    : Array.from(new Set([activeStoreId, ...allowedStores].filter(Boolean)));
  const effectiveActiveStoreId = hasFixedOperationalStore && primaryStoreId ? primaryStoreId : activeStoreId;
  return {
    ...user,
    active_store_id: effectiveActiveStoreId || null,
    store_id: effectiveActiveStoreId || primaryStoreId || null,
    primary_store_id: primaryStoreId || activeStoreId || null,
    store_label: effectiveActiveStoreId ? formatStoreIdLabel(effectiveActiveStoreId) : (primaryStoreId ? formatStoreIdLabel(primaryStoreId) : normalizeText(user.store_label || "")),
    allowed_stores: normalizedAllowedStores
  };
}

function getActiveStoreOptionsForCurrentUser() {
  if (!state.currentUser) {
    return [];
  }
  if (canViewAllStores()) {
    return getOfficialStoreOptions();
  }
  const allowed = toArray(state.currentUser.allowed_stores || state.currentUser.allowedStores)
    .map((item) => normalizePdvStoreIdentifier(item))
    .filter(Boolean);
  const current = normalizePdvStoreIdentifier(state.currentUser.active_store_id || state.currentUser.store_id || state.currentUser.store || "");
  const allowedSet = new Set([current, ...allowed].filter(Boolean));
  return getOfficialStoreOptions().filter((item) => allowedSet.has(item.value));
}

function buildActiveStoreSelectMarkup({ compact = false } = {}) {
  const activeStoreOptions = getActiveStoreOptionsForCurrentUser();
  if (activeStoreOptions.length <= 1) {
    return "";
  }
  const currentStoreId = getCurrentPdvStoreId();
  return `
    <select class="pdv-active-store-select${compact ? " is-compact" : ""}" data-active-store-select aria-label="Loja ativa">
      ${activeStoreOptions.map((option) => `<option value="${escapeHtml(option.value)}"${option.value === currentStoreId ? " selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
    </select>
  `;
}

function getCurrentUserDisplayName() {
  return normalizeVisibleText(state.currentUser?.name || state.currentUser?.username || state.currentUser?.email || "Usuario");
}

function getCurrentUserInitials() {
  const displayName = getCurrentUserDisplayName();
  const parts = displayName.split(/\s+/).filter(Boolean);
  const initials = parts.length > 1
    ? `${parts[0][0] || ""}${parts[1][0] || ""}`
    : displayName.slice(0, 2);
  return normalizeText(initials || "AE").slice(0, 2).toUpperCase();
}

function normalizeTheme(theme) {
  const normalizedTheme = String(theme || "").trim().toLowerCase();
  if (normalizedTheme === "dark" || normalizedTheme === "light") {
    return normalizedTheme;
  }
  return "";
}

function getUserThemePreference(user = state.currentUser) {
  return normalizeTheme(
    user?.theme ||
    user?.appearanceTheme ||
    user?.preferences?.theme ||
    user?.settings?.theme ||
    user?.profile?.theme
  );
}

function getStoredThemePreference() {
  return normalizeTheme(localStorage.getItem(THEME_STORAGE_KEY));
}

function getPreferredTheme(user = state.currentUser) {
  return getUserThemePreference(user) || getStoredThemePreference() || "dark";
}

function syncThemeControl() {
  const themeModeSelect = document.getElementById("theme-mode-select");
  if (themeModeSelect) {
    themeModeSelect.value = state.appTheme;
  }
}

function applyTheme(theme, options = {}) {
  const { persist = true } = options;
  const resolvedTheme = normalizeTheme(theme) || "dark";
  state.appTheme = resolvedTheme;
  document.documentElement.setAttribute("data-theme", resolvedTheme);
  document.body.dataset.theme = resolvedTheme;
  document.body.classList.toggle("theme-dark", resolvedTheme === "dark");
  document.body.classList.toggle("theme-light", resolvedTheme === "light");
  if (persist) {
    localStorage.setItem(THEME_STORAGE_KEY, resolvedTheme);
  }
  syncThemeControl();
}

function loadSavedTheme(user = state.currentUser) {
  const preferredTheme = getPreferredTheme(user);
  applyTheme(preferredTheme, { persist: true });
  return preferredTheme;
}

function syncAuthShellState() {
  const authShell = state.authLoading
    ? "checking"
    : state.currentUser
      ? "authenticated"
      : "guest";
  document.body.dataset.authShell = authShell;
  document.body.classList.toggle("auth-shell-hidden", authShell !== "authenticated");
  syncLoginOverlayForAuthShell(authShell);
}

function redirectToLogin() {
  if (window.location.pathname !== "/login" || window.location.hash) {
    window.history.replaceState({}, "", "/login");
  }
  document.body.dataset.section = "login";
}

function setLoginOverlayMode(mode = "guest") {
  const overlay = document.getElementById("login-overlay");
  if (!overlay) {
    return;
  }
  const resolvedMode = mode === "checking"
    ? "checking"
    : mode === "authenticated"
      ? "authenticated"
      : "guest";
  overlay.dataset.mode = resolvedMode;
  if (resolvedMode === "authenticated") {
    overlay.setAttribute("aria-hidden", "true");
    return;
  }
  const title = document.getElementById("login-title");
  const description = document.getElementById("login-description");
  const statusBox = document.getElementById("login-status");
  const errorBox = document.getElementById("login-error");
  if (title) {
    title.textContent = resolvedMode === "checking" ? "Carregando sistema..." : "Entrar na AEROSTORE OS";
  }
  if (description) {
    description.textContent = resolvedMode === "checking"
      ? "Estamos validando sua sessão para abrir a rota correta."
      : "Use seu perfil para acessar o PDV, CRM e permissoes da loja.";
  }
  if (statusBox) {
    statusBox.textContent = resolvedMode === "checking" ? "Verificando sessão..." : "";
  }
  if (errorBox && resolvedMode === "checking") {
    errorBox.textContent = "";
  }
}

function syncLoginOverlayForAuthShell(authShell = document.body.dataset.authShell) {
  const overlay = document.getElementById("login-overlay");
  if (!overlay) {
    return;
  }

  if (authShell === "authenticated") {
    if (overlay.classList.contains("active")) {
      overlay.classList.remove("active");
    }
    if (overlay.dataset.mode !== "authenticated") {
      overlay.dataset.mode = "authenticated";
    }
    if (overlay.style.display !== "none") {
      overlay.style.display = "none";
    }
    if (overlay.style.pointerEvents !== "none") {
      overlay.style.pointerEvents = "none";
    }
    if (overlay.getAttribute("aria-hidden") !== "true") {
      overlay.setAttribute("aria-hidden", "true");
    }
    return;
  }

  overlay.style.removeProperty("display");
  overlay.style.removeProperty("pointer-events");
  overlay.setAttribute("aria-hidden", overlay.classList.contains("active") ? "false" : "true");
}

let loginOverlayAuthGuard = null;

function ensureLoginOverlayAuthGuard() {
  if (loginOverlayAuthGuard || typeof MutationObserver === "undefined") {
    return;
  }

  const overlay = document.getElementById("login-overlay");
  if (!overlay) {
    return;
  }

  loginOverlayAuthGuard = new MutationObserver(() => {
    if (document.body.dataset.authShell === "authenticated") {
      syncLoginOverlayForAuthShell("authenticated");
    }
  });

  loginOverlayAuthGuard.observe(document.body, {
    attributes: true,
    attributeFilter: ["data-auth-shell", "class"]
  });
  loginOverlayAuthGuard.observe(overlay, {
    attributes: true,
    attributeFilter: ["class", "style", "data-mode"]
  });
}

function setAuthSession(token, user) {
  if (token) {
    localStorage.setItem("aerostore_auth_token", token);
  } else {
    localStorage.removeItem("aerostore_auth_token");
  }
  if (user) {
    const normalizedUser = normalizeAuthUserStoreContext(user);
    localStorage.setItem("aerostore_auth_user", JSON.stringify(normalizedUser));
    state.currentUser = normalizedUser;
  } else {
    localStorage.removeItem("aerostore_auth_user");
    state.currentUser = null;
  }
  state.isAuthenticated = Boolean(state.currentUser);
  state.authLoading = false;
  loadSavedTheme(state.currentUser);
  syncAuthShellState();
  renderSidebarMenu();
}

function clearAuthSession() {
  localStorage.removeItem("aerostore_auth_token");
  localStorage.removeItem("aerostore_auth_user");
  state.currentUser = null;
  state.isAuthenticated = false;
  state.authLoading = false;
  loadSavedTheme(null);
  syncAuthShellState();
  renderSidebarMenu();
}

function getCurrentRole() {
  return state.currentUser?.role || "";
}

function getCurrentUserRole() {
  const rawRole = state.currentUser?.role
    || state.currentUser?.perfil
    || state.currentUser?.profile
    || state.currentUser?.permission_profile
    || "";
  const normalizedRole = String(rawRole || "").trim().toLowerCase();
  if (["admin", "administrator", "administrador"].includes(normalizedRole)) return "admin";
  if (["manager", "gerente", "gestor"].includes(normalizedRole)) return "gestor";
  if (["seller", "vendedor", "sales"].includes(normalizedRole)) return "vendedor";
  if (["cashier", "caixa"].includes(normalizedRole)) return "caixa";
  if (["consult", "consulta", "readonly"].includes(normalizedRole)) return "consulta";
  return normalizedRole;
}

function getCurrentPermissions() {
  return state.currentUser?.permissions || {};
}

function hasPermission(permissionKey) {
  return Boolean(getCurrentPermissions()?.[permissionKey]);
}

function hasAnyPermission(...permissionKeys) {
  return permissionKeys.some((permissionKey) => hasPermission(permissionKey));
}

function isCurrentUserManagerProfile() {
  return ["admin", "gestor"].includes(getCurrentUserRole());
}

function isCurrentUserSellerProfile() {
  return getCurrentUserRole() === "vendedor";
}

function canManageUsersPanel() {
  return getCurrentUserRole() === "admin" || hasPermission("can_manage_users");
}

function canViewAuditLogsPanel() {
  return getCurrentUserRole() === "admin" || hasPermission("can_view_audit");
}

function getDefaultRouteForCurrentUser() {
  const role = getCurrentUserRole();
  if (role === "caixa") {
    return "/pdv/caixa";
  }
  if (role === "consulta") {
    return "/pdv/produtos";
  }
  return "/pdv";
}

function canSellPdvFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_sell");
}

function canViewPdvCashFrontend() {
  return isCurrentUserManagerProfile() || hasAnyPermission("can_view_cash_register", "can_open_close_register");
}

function canViewPdvProductsFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_products") || hasPermission("can_sell");
}

function canViewPdvCustomersFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_customers") || hasPermission("can_sell");
}

function canViewPdvStockFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_stock") || hasPermission("can_view_products");
}

function canAdjustPdvInventoryFrontend() {
  return hasPermission("can_adjust_inventory");
}

function canAdjustPdvProductPriceFrontend() {
  return hasPermission("can_adjust_product_price");
}

function canCreatePdvLabelProductFrontend() {
  return isCurrentUserManagerProfile() || hasAnyPermission("can_manage_products", "can_move_stock");
}

function canImportPdvTinyFrontend() {
  return getCurrentUserRole() === "admin" || hasPermission("can_manage_products");
}

function canImportCrmContactsFrontend() {
  return getCurrentUserRole() === "admin" || hasAnyPermission("can_export_data", "can_manage_campaigns");
}

function canViewPdvOrdersFrontend() {
  return isCurrentUserManagerProfile() || hasAnyPermission("can_sell", "can_view_cash_register", "can_view_orders");
}

function canCancelPdvSaleFrontend() {
  return getCurrentUserRole() === "admin" || hasPermission("can_cancel_sale");
}

function canViewPdvDashboardFrontend() {
  return isCurrentUserManagerProfile() || hasAnyPermission(
    "can_sell",
    "can_view_products",
    "can_view_customers",
    "can_view_cash_register",
    "can_view_orders",
    "can_view_stock"
  );
}

function canViewPdvExchangesFrontend() {
  return isCurrentUserManagerProfile() || hasAnyPermission("can_sell", "can_view_exchanges");
}

function canViewPdvReservationsFrontend() {
  return isCurrentUserManagerProfile();
}

function canViewPdvGestaoFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_commercial_management");
}

function canManageSettings() {
  return isCurrentUserManagerProfile();
}

function canManageSellers() {
  return getCurrentUserRole() === "admin";
}

function canCallSellersEndpoint() {
  return canManageSellers() || hasPermission("can_manage_users");
}

function canManageGlobalSettings() {
  return hasPermission("can_manage_global_settings");
}

function canManageStoreSettingsPanel() {
  return hasPermission("can_manage_store_settings");
}

function canViewStoreSettingsPanel() {
  return canManageGlobalSettings() || canManageStoreSettingsPanel() || hasPermission("can_view_store_settings");
}

function canViewGlobalSettingsPanel() {
  return canManageGlobalSettings() || isCurrentUserManagerProfile();
}

function canViewSettingsTeamPanel() {
  return canCallSellersEndpoint();
}

function canViewRealStoreSettings() {
  return canManageGlobalSettings() || canManageStoreSettingsPanel();
}

function canEditRealStoreSettings() {
  return canManageGlobalSettings() || canManageStoreSettingsPanel();
}

function canEditFullStoreSettings() {
  return canManageGlobalSettings();
}

function canViewReports() {
  return isCurrentUserManagerProfile();
}

function canDeleteRecords() {
  return getCurrentUserRole() === "admin";
}

function canViewAllStores() {
  return getCurrentUserRole() === "admin" || hasPermission("can_view_all_stores");
}

function canViewConsolidationMenu() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_consolidation");
}

function canViewAerointelMenu() {
  return isCurrentUserManagerProfile() || hasPermission("can_view_aerointel");
}

function canViewAerointelConversationRead() {
  return isCurrentUserManagerProfile();
}

