function normalizePathname(pathname = "") {
  const normalized = String(pathname || "").trim();
  if (!normalized) {
    return "/";
  }
  if (normalized.length > 1 && normalized.endsWith("/")) {
    return normalized.slice(0, -1);
  }
  return normalized;
}

function getSectionFromPathname(pathname = window.location.pathname || "/") {
  return PATHNAME_SECTION_MAP[normalizePathname(pathname)] || "";
}

function getSectionMeta(sectionId = "") {
  return PATHNAME_SECTION_META[sectionId] || null;
}

