function isVirtualPdvProductId(productId = "") {
  return /^[a-z_]+:/i.test(normalizeText(productId || ""));
}

function ensurePdvProductsCrudState() {
  state.pdvProducts = state.pdvProducts || {};
  state.pdvProducts.loadingRequestId = Math.max(0, Number(state.pdvProducts.loadingRequestId || 0));
  const currentPagination = state.pdvProducts.pagination && typeof state.pdvProducts.pagination === "object"
    ? state.pdvProducts.pagination
    : {};
  const requestedPageSize = Number(currentPagination.limit || currentPagination.pageSize || 25);
  const pageSize = [25, 50, 100].includes(requestedPageSize) ? requestedPageSize : 25;
  const total = Math.max(0, Number(currentPagination.total || 0));
  const totalPages = Math.max(1, Number(currentPagination.totalPages || currentPagination.total_pages || Math.ceil(total / pageSize) || 1));
  const requestedPage = Number(currentPagination.page || 1);
  const page = Math.min(totalPages, Math.max(1, Number.isFinite(requestedPage) ? requestedPage : 1));
  state.pdvProducts.pagination = {
    page,
    limit: pageSize,
    total,
    totalPages,
    hasMore: currentPagination.hasMore !== undefined ? Boolean(currentPagination.hasMore) : page < totalPages
  };
  state.pdvProducts.filters = {
    store: normalizePdvStoreIdentifier(state.pdvProducts.filters?.store ?? getDefaultPdvProductsStoreFilter()),
    status: normalizeText(state.pdvProducts.filters?.status || "").toLowerCase(),
    productType: normalizeText(state.pdvProducts.filters?.productType || "").toLowerCase(),
    brand: normalizeText(state.pdvProducts.filters?.brand || ""),
    category: normalizeText(state.pdvProducts.filters?.category || ""),
    color: normalizeText(state.pdvProducts.filters?.color || ""),
    size: normalizeText(state.pdvProducts.filters?.size || ""),
    stockMode: normalizeText(state.pdvProducts.filters?.stockMode || "").toLowerCase(),
    useInAi: String(state.pdvProducts.filters?.useInAi || "0"),
    useInPos: String(state.pdvProducts.filters?.useInPos || "0"),
    withoutPrice: String(state.pdvProducts.filters?.withoutPrice || "0"),
    withoutSku: String(state.pdvProducts.filters?.withoutSku || "0"),
    withoutPhoto: String(state.pdvProducts.filters?.withoutPhoto || "0"),
    zeroStock: String(state.pdvProducts.filters?.zeroStock || "0")
  };
  if (!state.pdvProducts.drawerDraft || typeof state.pdvProducts.drawerDraft !== "object") {
    state.pdvProducts.drawerDraft = getDefaultPdvProductDraft();
  }
  state.pdvProducts.drawerMode = state.pdvProducts.drawerMode || "create";
  state.pdvProducts.drawerOpen = Boolean(state.pdvProducts.drawerOpen);
  state.pdvProducts.drawerSaving = Boolean(state.pdvProducts.drawerSaving);
  state.pdvProducts.drawerError = state.pdvProducts.drawerError || "";
  state.pdvProducts.drawerPhotoUploading = Boolean(state.pdvProducts.drawerPhotoUploading);
  state.pdvProducts.drawerPhotoRemoving = Boolean(state.pdvProducts.drawerPhotoRemoving);
  state.pdvProducts.drawerPhotoMessage = state.pdvProducts.drawerPhotoMessage || "";
  state.pdvProducts.drawerPhotoPreviewUrl = state.pdvProducts.drawerPhotoPreviewUrl || "";
  state.pdvProducts.drawerPhotoFile = state.pdvProducts.drawerPhotoFile || null;
  state.pdvProducts.drawerCodeLoading = Boolean(state.pdvProducts.drawerCodeLoading);
  state.pdvProducts.movementsByProduct = state.pdvProducts.movementsByProduct || {};
}

function buildPdvSearchResultState({ title = "", detail = "", tone = "loading" } = {}) {
  const isLoading = tone === "loading";
  return `
    <div class="pdv-search-result-state is-${escapeHtml(tone)}" role="${isLoading ? "status" : "alert"}" aria-live="polite">
      <div class="pdv-search-result-state-copy">
        ${isLoading ? '<span class="pdv-search-result-spinner" aria-hidden="true"></span>' : ""}
        <div>
          <strong>${escapeHtml(title)}</strong>
          ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
        </div>
      </div>
      ${isLoading ? `
        <div class="pdv-search-result-skeleton" aria-hidden="true">
          ${Array.from({ length: 3 }, (_, index) => `
            <span class="pdv-search-result-skeleton-row" style="--pdv-skeleton-delay: ${index * 90}ms">
              <i></i><b></b><em></em>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </div>
  `;
}

