function getAerointelStoreOptions() {
  const allowedStores = toArray(state.currentUser?.allowed_stores || state.currentUser?.allowedStores || [])
    .map((item) => normalizeText(item).toLowerCase())
    .filter(Boolean);
  const seen = new Set();
  const options = [];
  if (canViewAllStores()) {
    options.push({ value: "", label: "Todas as lojas permitidas" });
  }
  allowedStores.forEach((storeId) => {
    if (!storeId || seen.has(storeId)) {
      return;
    }
    seen.add(storeId);
    options.push({ value: storeId, label: formatStoreIdLabel(storeId) });
  });
  const currentStore = normalizeText(getCurrentPdvStoreId() || "").toLowerCase();
  if (currentStore && !seen.has(currentStore)) {
    options.push({ value: currentStore, label: formatStoreIdLabel(currentStore) });
  }
  return options;
}

function getAerointelActiveStoreLabel() {
  const selectedStore = normalizeText(state.aerointel.filters.store || "");
  if (!selectedStore && canViewAllStores()) {
    return "Todas as lojas permitidas";
  }
  return formatStoreIdLabel(selectedStore || getCurrentPdvStoreId() || getCurrentUserStoreLabel());
}

function getAerointelWhatsAppMeta() {
  const statusData = state.aerointel.whatsappStatus || {};
  return getWhatsappCrmStatusMeta({
    ...statusData,
    status: statusData.status || state.whatsappStatus || "desconectado",
    sessionStateLabel: statusData.sessionStateLabel || statusData.authMode || ""
  });
}

