function buildAerointelMetricCards() {
  const metrics = state.aerointel.summary?.metrics || {};
  const stores = toArray(state.aerointel.stores);
  const customers = toArray(state.aerointel.customers);
  const inventoryMetrics = state.aerointel.inventory?.metrics || {};
  const whatsappMeta = getAerointelWhatsAppMeta();
  const campaigns = getAerointelCampaignRows();
  const activeRegisters = stores.filter((item) => Boolean(item.caixa_aberto));
  const cards = [
    {
      label: "Vendas no periodo",
      value: String(Number(metrics.quantidade_vendas || 0)),
      detail: `${Number(metrics.vendas_canceladas || 0)} cancelada(s) no recorte.`
    },
    {
      label: "Faturamento",
      value: currency(metrics.venda_liquida || 0),
      detail: `Venda bruta ${currency(metrics.venda_bruta || 0)}.`
    },
    {
      label: "Ticket medio",
      value: currency(metrics.ticket_medio || 0),
      detail: `Desconto total ${currency(metrics.desconto_total || 0)}.`
    },
    {
      label: "Caixa ativo",
      value: activeRegisters.length ? (canViewAllStores() ? `${activeRegisters.length} loja(s)` : "Aberto") : "Fechado",
      detail: activeRegisters.length ? activeRegisters.map((item) => item.loja).slice(0, 3).join(" • ") : "Nenhum caixa aberto neste escopo."
    },
    {
      label: "Clientes",
      value: String(customers.length),
      detail: customers.length ? `${customers.filter((item) => item.segmento_vip).length} cliente(s) VIP no recorte.` : "Dados indisponiveis no periodo."
    },
    {
      label: "Produtos / estoque",
      value: String(Number(inventoryMetrics.total_itens_disponiveis || 0)),
      detail: `${Number(inventoryMetrics.itens_esgotados || 0)} item(ns) esgotado(s).`
    },
    {
      label: "WhatsApp CRM",
      value: whatsappMeta.label,
      detail: normalizeText(state.aerointel.whatsappStatus?.connectedNumber || "") || whatsappMeta.detail
    },
    {
      label: "Campanhas / logs",
      value: String(campaigns.length),
      detail: canViewWhatsappLogs()
        ? `${toArray(state.aerointel.whatsappLogs).length} log(s) recente(s) visivel(is).`
        : "Logs protegidos por permissao."
    }
  ];
  return cards.map((item) => `
    <article class="stat-card aerointel-stat-card">
      <span>${escapeHtml(item.label)}</span>
      <strong>${escapeHtml(item.value)}</strong>
      <small>${escapeHtml(item.detail)}</small>
    </article>
  `).join("");
}

