function renderGestaoCampaignCard(campaign) {
  const rawStatus = (campaign.status || "draft").toString().toLowerCase().trim();
  const isActive = rawStatus === "active" || rawStatus === "ativa";
  const isSettled = rawStatus === "settled" || rawStatus === "apurada";
  const isDraft = !isActive && !isSettled;
  const statusClass = isActive ? "status-active" : isSettled ? "status-settled" : "status-draft";
  const statusLabel = isActive ? "Ativa" : isSettled ? "Apurada" : "Rascunho";
  const ruleLabel = campaign.rule_type === "quantity_target" ? "Qtd. itens" : campaign.rule_type === "ticket_threshold_count" ? "Vendas acima de ticket" : "Maior volume";
  const prize = campaign.prize || {};
  const prizeStr = prize.type === "per_item" ? "R$ " + (prize.value || 0) + "/item" : prize.type === "per_win" ? "R$ " + (prize.value || 0) + " (1º lugar)" : "R$ " + (prize.value || 0);
  const campaignName = (campaign.name || "").toString().trim();
  // Normaliza store_ids para array — usa campaign.store_ids (já array do normalizeChallenge)
  let storeIds = [];
  if (Array.isArray(campaign.store_ids) && campaign.store_ids.length > 0) {
    storeIds = campaign.store_ids;
  } else if (Array.isArray(campaign.store_ids_json)) {
    storeIds = campaign.store_ids_json;
  } else {
    try { storeIds = JSON.parse(campaign.store_ids_json || "[]"); } catch (_) { }
  }
  if (storeIds.length === 0) {
    if (campaign.store_id) storeIds = [campaign.store_id];
  }
  const storeLabels = { vila: "Vila", botanico: "Bot\u00e2nico", sul: "Sul" };
  const storesDisplay = storeIds.length > 0 ? storeIds.map((s) => storeLabels[s] || s).join(", ") : "Todas";
  const hasName = Boolean(campaignName);
  const hasPrize = prize.value && Number(prize.value) > 0;
  const isIncomplete = !hasName || !hasPrize;
  const canManage = canManageCampaignChallenges();
  const actions = [];
  // Rascunho: Editar sempre (para revisar antes de ativar)
  if (canManage && isDraft) actions.push('<button class="small-secondary" type="button" data-gestao-action="edit" data-id="' + campaign.id + '">Editar</button>');
  // Completa + rascunho: Ativar
  if (canManage && isDraft && !isIncomplete) actions.push('<button class="small-primary" type="button" data-gestao-action="activate" data-id="' + campaign.id + '">Ativar</button>');
  // Rascunho: Excluir
  if (canManage && isDraft) actions.push('<button class="small-danger" type="button" data-gestao-action="delete" data-id="' + campaign.id + '">Excluir</button>');
  // Ativa: Cancelar
  if (canManage && isActive) actions.push('<button class="small-danger" type="button" data-gestao-action="cancel" data-id="' + campaign.id + '">Cancelar</button>');
  // Ativa + completa: Ranking Live e Apurar
  if (isActive && !isIncomplete) actions.push('<button class="small-secondary" type="button" data-gestao-action="live" data-id="' + campaign.id + '">Ranking Live</button>');
  if ((canManageCampaignSettle() || isCurrentUserManagerProfile()) && isActive && !isIncomplete) actions.push('<button class="small-primary" type="button" data-gestao-action="settle" data-id="' + campaign.id + '">Apurar</button>');
  // Settled: Resultados
  if (isSettled) actions.push('<button class="small-secondary" type="button" data-gestao-action="results" data-id="' + campaign.id + '">Resultados</button>');
  return `
    <div class="gestao-card ${statusClass}${isIncomplete ? " gestao-card-incomplete" : ""}">
      <div class="gestao-card-header">
        <div>
          <strong>${escapeHtml(campaignName || "Campanha sem nome")}</strong>
          ${isIncomplete ? '<span class="gestao-badge gestao-badge-warning">⚠️ Incompleta</span>' : ""}
          <span class="gestao-badge ${statusClass}">${statusLabel}</span>
        </div>
        <div class="gestao-card-actions">${actions.join("")}</div>
      </div>
      <div class="gestao-card-meta">
        <span>${escapeHtml(ruleLabel)}</span>
        <span>${campaign.start_date || "—"} a ${campaign.end_date || "—"}</span>
        <span>Prêmio: ${prizeStr}</span>
        <span>Lojas: ${escapeHtml(storesDisplay)}</span>
      </div>
    </div>`;
}

function canManageCampaignChallenges() {
  return isCurrentUserManagerProfile() || hasPermission("can_manage_campaign_challenges");
}

function canManageCampaignSettle() {
  return isCurrentUserManagerProfile() || hasPermission("can_settle_campaign_rewards");
}

function bindPdvGestaoActions(container) {
  container.querySelectorAll("[data-action]").forEach((btn) => {
    if (btn.dataset.boundAction) return;
    btn.dataset.boundAction = "true";
    btn.addEventListener("click", async () => {
      const action = btn.dataset.action;
      if (action === "gestao-refresh") { await loadPdvGestaoFront(); return; }
      if (action === "gestao-create") { openGestaoCreateModal(); return; }
      if (action === "gestao-close-create") { closeGestaoCreateModal(); return; }
    });
  });
  container.querySelectorAll("[data-gestao-action]").forEach((btn) => {
    if (btn.dataset.boundGa) return;
    btn.dataset.boundGa = "true";
    btn.addEventListener("click", async () => {
      await handleGestaoAction(btn.dataset.gestaoAction, Number(btn.dataset.id));
    });
  });
  const form = container.querySelector("#gestao-create-form");
  if (form && !form.dataset.boundSubmit) {
    form.dataset.boundSubmit = "true";
    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      if (pdvGestaoState.editingId) {
        await handleGestaoEditSubmit(form);
      } else {
        await handleGestaoCreateSubmit(form);
      }
    });
  }
  const backdrop = container.querySelector(".modal-backdrop");
  if (backdrop && !backdrop.dataset.boundBackdrop) {
    backdrop.dataset.boundBackdrop = "true";
    backdrop.addEventListener("click", closeGestaoCreateModal);
  }
}

function openGestaoCreateModal() {
  pdvGestaoState.createModalOpen = true;
  const modal = document.getElementById("gestao-create-modal");
  if (modal) modal.style.display = "";
  const today = getToday();
  const form = document.querySelector("#gestao-create-form");
  if (form) {
    form.reset();
    form.start_date.value = today;
    form.end_date.value = today;
  }
}

function closeGestaoCreateModal() {
  pdvGestaoState.createModalOpen = false;
  pdvGestaoState.editingId = null;
  const modal = document.getElementById("gestao-create-modal");
  if (modal) modal.style.display = "none";
  const title = modal ? modal.querySelector("h3") : null;
  if (title) title.textContent = "Nova Corridinha";
  const submitBtn = modal ? modal.querySelector('button[type="submit"]') : null;
  if (submitBtn) submitBtn.textContent = "Criar";
}

function openGestaoEditModal(campaign) {
  pdvGestaoState.createModalOpen = true;
  pdvGestaoState.editingId = campaign.id;
  const modal = document.getElementById("gestao-create-modal");
  if (!modal) return;
  modal.style.display = "";
  const title = modal.querySelector("h3");
  if (title) title.textContent = "Editar Corridinha";
  const submitBtn = modal.querySelector('button[type="submit"]');
  if (submitBtn) submitBtn.textContent = "Salvar alterações";
  const form = modal.querySelector("#gestao-create-form");
  if (!form) return;
  form.reset();
  const rules = campaign.rules_json ? (typeof campaign.rules_json === "string" ? JSON.parse(campaign.rules_json) : campaign.rules_json) : {};
  const prize = campaign.prize_json ? (typeof campaign.prize_json === "string" ? JSON.parse(campaign.prize_json) : campaign.prize_json) : (campaign.prize || {});
  // name
  if (form.name) form.name.value = campaign.name || "";
  // description
  if (form.description) form.description.value = campaign.description || "";
  // dates
  if (form.start_date) form.start_date.value = campaign.start_date || "";
  if (form.end_date) form.end_date.value = campaign.end_date || "";
  // rule_type
  if (form.rule_type) form.rule_type.value = campaign.rule_type || "quantity_target";
  // quantity_target — usado para ambos: quantity_target e ticket_threshold_count
  if (form.quantity_target) {
    form.quantity_target.value = rules.quantity_target || rules.ticket_threshold_count || 1;
  }
  // ticket_threshold — min_ticket do rules
  if (form.ticket_threshold) {
    form.ticket_threshold.value = rules.ticket_threshold || rules.min_ticket || 0;
  }
  // prize
  const prizeValue = prize.amount ?? prize.value ?? 0;
  if (form.prize_value) form.prize_value.value = prizeValue;
  if (form.prize_type) form.prize_type.value = prize.type || "fixed";
  // store_ids — popula checkboxes (campaign.store_ids já é array do normalizeChallenge)
  let storeIds = [];
  if (Array.isArray(campaign.store_ids) && campaign.store_ids.length > 0) {
    storeIds = campaign.store_ids;
  } else if (Array.isArray(campaign.store_ids_json)) {
    storeIds = campaign.store_ids_json;
  } else {
    try { storeIds = JSON.parse(campaign.store_ids_json || campaign.store_ids || "[]"); } catch (_) { }
  }
  if (storeIds.length === 0) {
    if (campaign.store_id) storeIds = [campaign.store_id];
    else storeIds = ["vila", "botanico", "sul"];
  }
  form.querySelectorAll('[name="store_ids"]').forEach((cb) => {
    cb.checked = storeIds.includes(cb.value);
  });
}

async function handleGestaoCreateSubmit(form) {
  const fd = new FormData(form);
  const name = (fd.get("name") || "").toString().trim();
  const startDate = (fd.get("start_date") || "").toString().trim();
  const endDate = (fd.get("end_date") || "").toString().trim();
  const ruleType = (fd.get("rule_type") || "").toString().trim();
  const prizeValue = Number(fd.get("prize_value") || 0);
  const prizeType = (fd.get("prize_type") || "fixed").toString().trim();
  if (!name) { alert("Nome da campanha e obrigatorio."); return; }
  if (!startDate) { alert("Data de inicio e obrigatoria."); return; }
  if (!endDate) { alert("Data de termino e obrigatoria."); return; }
  if (!["quantity_target", "ticket_threshold_count", "highest_quantity"].includes(ruleType)) { alert("Tipo de regra invalido."); return; }
  if (prizeValue <= 0) { alert("Premio deve ser maior que zero."); return; }
  // Montar rules conforme tipo de regra
  let rules = {};
  if (ruleType === "quantity_target") {
    rules = { quantity_target: Number(fd.get("quantity_target") || 1) };
  } else if (ruleType === "ticket_threshold_count") {
    const ticketThreshold = Number(fd.get("ticket_threshold") || 0);
    const ticketCount = Number(fd.get("quantity_target") || 1);
    rules = { min_ticket: ticketThreshold, ticket_threshold: ticketThreshold, required_count: ticketCount, ticket_threshold_count: ticketCount };
  } else {
    rules = {};
  }
  // Extrair store_ids dos checkboxes marcados
  const storeIds = fd.getAll("store_ids");
  if (storeIds.length === 0) { alert("Selecione pelo menos uma loja participante."); return; }
  const payload = {
    name: name,
    description: (fd.get("description") || "").toString().trim(),
    store_ids: storeIds,
    start_date: startDate,
    end_date: endDate,
    rule_type: ruleType,
    rules: rules,
    target_skus: [],
    target_categories: [],
    prize: { type: prizeType, value: prizeValue }
  };
  try {
    const res = await api("/api/pdv/commercial/campaigns", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    closeGestaoCreateModal();
    await loadPdvGestaoFront();
  } catch (err) {
    alert("Erro ao criar: " + (err.message || err.error || ""));
  }
}

async function handleGestaoEditSubmit(form) {
  const editingId = pdvGestaoState.editingId;
  if (!editingId) return;
  const fd = new FormData(form);
  const name = (fd.get("name") || "").toString().trim();
  const startDate = (fd.get("start_date") || "").toString().trim();
  const endDate = (fd.get("end_date") || "").toString().trim();
  const ruleType = (fd.get("rule_type") || "").toString().trim();
  const prizeValue = Number(fd.get("prize_value") || 0);
  const prizeType = (fd.get("prize_type") || "fixed").toString().trim();
  if (!name) { alert("Nome da campanha e obrigatorio."); return; }
  if (!startDate) { alert("Data de inicio e obrigatoria."); return; }
  if (!endDate) { alert("Data de termino e obrigatoria."); return; }
  if (!["quantity_target", "ticket_threshold_count", "highest_quantity"].includes(ruleType)) { alert("Tipo de regra invalido."); return; }
  if (prizeValue <= 0) { alert("Premio deve ser maior que zero."); return; }
  let rules = {};
  if (ruleType === "quantity_target") {
    rules = { quantity_target: Number(fd.get("quantity_target") || 1) };
  } else if (ruleType === "ticket_threshold_count") {
    const ticketThreshold = Number(fd.get("ticket_threshold") || 0);
    const ticketCount = Number(fd.get("quantity_target") || 1);
    rules = { min_ticket: ticketThreshold, ticket_threshold: ticketThreshold, required_count: ticketCount, ticket_threshold_count: ticketCount };
  } else {
    rules = {};
  }
  // Extrair store_ids dos checkboxes marcados
  const storeIds = fd.getAll("store_ids");
  if (storeIds.length === 0) { alert("Selecione pelo menos uma loja participante."); return; }
  const payload = {
    name: name || null,
    description: (fd.get("description") || "").toString().trim() || null,
    store_ids: storeIds,
    start_date: startDate,
    end_date: endDate,
    rule_type: ruleType,
    rules: rules,
    target_skus: [],
    target_categories: [],
    prize: { type: prizeType, value: prizeValue }
  };
  try {
    const res = await api("/api/pdv/commercial/campaigns/" + editingId, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    closeGestaoCreateModal();
    await loadPdvGestaoFront();
  } catch (err) {
    alert("Erro ao editar: " + (err.message || err.error || ""));
  }
}

async function handleGestaoAction(action, campaignId) {
  try {
    if (action === "activate") {
      await api("/api/pdv/commercial/campaigns/" + campaignId + "/activate", { method: "POST" });
      await loadPdvGestaoFront();
    } else if (action === "cancel") {
      if (!confirm("Cancelar esta campanha?")) return;
      await api("/api/pdv/commercial/campaigns/" + campaignId + "/cancel", { method: "POST" });
      await loadPdvGestaoFront();
    } else if (action === "live") {
      await loadGestaoRankingPanel(campaignId);
    } else if (action === "settle") {
      if (!confirm("Apurar esta campanha? Esta acao nao pode ser desfeita.")) return;
      await api("/api/pdv/commercial/campaigns/" + campaignId + "/settle", { method: "POST" });
      await loadPdvGestaoFront();
    } else if (action === "results") {
      await loadGestaoRankingPanel(campaignId, true);
    } else if (action === "edit") {
      // Busca campanha completa para abrir no modal de edição
      try {
        const res = await api("/api/pdv/commercial/campaigns/" + campaignId);
        const campaign = res?.data;
        if (campaign) openGestaoEditModal(campaign);
      } catch (err) {
        alert("Erro ao carregar campanha: " + (err.message || err.error || ""));
      }
    } else if (action === "delete") {
      if (!confirm("Excluir esta campanha? Esta acao nao pode ser desfeita.")) return;
      await api("/api/pdv/commercial/campaigns/" + campaignId, { method: "DELETE" });
      await loadPdvGestaoFront();
    }
  } catch (err) {
    alert("Erro: " + (err.message || err.error || ""));
  }
}

async function loadGestaoRankingPanel(campaignId, settled = false) {
  const panel = document.getElementById("gestao-ranking-panel");
  if (!panel) return;
  panel.innerHTML = '<div class="panel-header"><h3>Ranking</h3></div><div class="loading-indicator">Carregando...</div>';
  try {
    const endpoint = settled ? "/api/pdv/commercial/campaigns/" + campaignId + "/results" : "/api/pdv/commercial/campaigns/" + campaignId + "/live";
    const res = await api(endpoint);
    const data = res?.data || {};
    const challenge = data.challenge || {};
    const ranking = data.ranking || data.results || [];
    panel.innerHTML = `
      <div class="panel">
        <div class="panel-header">
          <h3>${escapeHtml(challenge.name || "Ranking")} — ${settled ? "Resultados" : "Live"}</h3>
          <button class="ghost-button" type="button" data-action="gestao-close-ranking">Fechar</button>
        </div>
        ${ranking.length === 0 ? '<div class="empty-state"><strong>Sem dados</strong></div>' :
          '<table class="data-table"><thead><tr><th>#</th><th>Vendedor</th><th>Valor</th><th>Vendas</th><th>Itens</th>' + (settled ? "<th>Prêmio</th><th>Pago</th>" : "") + "</tr></thead><tbody>" +
          ranking.map((r) => {
            const isWinner = r.rank === 1 || r.is_winner;
            const prizeCell = settled ? "<td>R$ " + (r.prize_earned || 0).toFixed(2) + "</td><td>" + (r.paid ? "✅" : "—") + "</td>" : "";
            return "<tr" + (isWinner ? ' class="winner-row"' : "") + "><td>" + (r.rank || "-") + "</td><td>" + escapeHtml(r.seller_name || "") + "</td><td>" + (settled ? "R$ " : "") + (r.current_value || 0) + (settled ? "" : " itens") + "</td><td>" + (r.eligible_sales_count || 0) + "</td><td>" + (r.eligible_items_count || 0) + "</td>" + prizeCell + "</tr>";
          }).join("") + "</tbody></table>"}
      </div>`;
    panel.querySelector('[data-action="gestao-close-ranking"]')?.addEventListener("click", () => { panel.innerHTML = ""; });
  } catch (err) {
    panel.innerHTML = '<div class="panel"><div class="panel-header"><h3>Ranking</h3></div><div class="empty-state"><strong>Erro ao carregar ranking</strong><span>' + escapeHtml(err.message || err.error || "") + '</span></div></div>';
  }
}

async function loadPdvImportsFront() {
  ensurePdvImportsState();
  const container = document.getElementById("pdv-imports-content");
  if (!container) return;
  if (isCrmContactsImportRoute()) {
    renderCrmContactsImportFront(container);
    return;
  }
  renderPdvImportsFront(container);
  if (!state.pdvImports.uploads.loading && !toArray(state.pdvImports.uploads.files).length && !toArray(state.pdvImports.uploads.history).length) {
    await loadPdvTinyImportUploads();
  }
}

function ensurePdvCockpitState() {
  state.pdvCockpit = state.pdvCockpit && typeof state.pdvCockpit === "object" ? state.pdvCockpit : {};
  state.pdvCockpit.loading = state.pdvCockpit.loading && typeof state.pdvCockpit.loading === "object" ? state.pdvCockpit.loading : {};
  state.pdvCockpit.errors = state.pdvCockpit.errors && typeof state.pdvCockpit.errors === "object" ? state.pdvCockpit.errors : {};
  state.pdvCockpit.filters = state.pdvCockpit.filters && typeof state.pdvCockpit.filters === "object" ? state.pdvCockpit.filters : {};
  state.pdvCockpit.filterMeta = state.pdvCockpit.filterMeta && typeof state.pdvCockpit.filterMeta === "object" ? state.pdvCockpit.filterMeta : {};
  state.pdvCockpit.loading.summary = Boolean(state.pdvCockpit.loading.summary);
  state.pdvCockpit.loading.curve = Boolean(state.pdvCockpit.loading.curve);
  state.pdvCockpit.loading.margin = Boolean(state.pdvCockpit.loading.margin);
  state.pdvCockpit.loading.decisionMap = Boolean(state.pdvCockpit.loading.decisionMap);
  state.pdvCockpit.loading.trends = Boolean(state.pdvCockpit.loading.trends);
  state.pdvCockpit.errors.summary = String(state.pdvCockpit.errors.summary || "");
  state.pdvCockpit.errors.curve = String(state.pdvCockpit.errors.curve || "");
  state.pdvCockpit.errors.margin = String(state.pdvCockpit.errors.margin || "");
  state.pdvCockpit.errors.decisionMap = String(state.pdvCockpit.errors.decisionMap || "");
  state.pdvCockpit.errors.trends = String(state.pdvCockpit.errors.trends || "");
  state.pdvCockpit.filters.period = normalizeText(state.pdvCockpit.filters.period || "30d").toLowerCase() || "30d";
  state.pdvCockpit.filters.start_date = String(state.pdvCockpit.filters.start_date || "").trim();
  state.pdvCockpit.filters.end_date = String(state.pdvCockpit.filters.end_date || "").trim();
  state.pdvCockpit.filters.store_id = String(state.pdvCockpit.filters.store_id || "").trim();
  state.pdvCockpit.filters.brand = String(state.pdvCockpit.filters.brand || "").trim();
  state.pdvCockpit.filters.category = String(state.pdvCockpit.filters.category || "").trim();
  state.pdvCockpit.filters.vendor_id = String(state.pdvCockpit.filters.vendor_id || "").trim();
  state.pdvCockpit.filters.product_search = String(state.pdvCockpit.filters.product_search || "").trim();
  state.pdvCockpit.summary = state.pdvCockpit.summary && typeof state.pdvCockpit.summary === "object" ? state.pdvCockpit.summary : null;
  state.pdvCockpit.curve = toArray(state.pdvCockpit.curve);
  state.pdvCockpit.curveWarnings = toArray(state.pdvCockpit.curveWarnings);
  state.pdvCockpit.curveFilter = normalizeLookup(state.pdvCockpit.curveFilter || "");
  state.pdvCockpit.curveSearch = String(state.pdvCockpit.curveSearch || "");
  state.pdvCockpit.curveSortBy = normalizeText(state.pdvCockpit.curveSortBy || "total_revenue");
  state.pdvCockpit.curveSortDir = normalizeText(state.pdvCockpit.curveSortDir || "desc");
  state.pdvCockpit.visibleCurveRows = Math.max(20, Number(state.pdvCockpit.visibleCurveRows || 20));
  state.pdvCockpit.margin = state.pdvCockpit.margin && typeof state.pdvCockpit.margin === "object" ? state.pdvCockpit.margin : null;
  state.pdvCockpit.marginTab = normalizeText(state.pdvCockpit.marginTab || "stores");
  state.pdvCockpit.decisionMap = state.pdvCockpit.decisionMap && typeof state.pdvCockpit.decisionMap === "object" ? state.pdvCockpit.decisionMap : null;
  state.pdvCockpit.trends = state.pdvCockpit.trends && typeof state.pdvCockpit.trends === "object" ? state.pdvCockpit.trends : null;
  state.pdvCockpit.warnings = toArray(state.pdvCockpit.warnings);
  state.pdvCockpit.filterMeta.brands = toArray(state.pdvCockpit.filterMeta.brands);
  state.pdvCockpit.filterMeta.categories = toArray(state.pdvCockpit.filterMeta.categories);
}

function isPdvCockpitRoute() {
  return normalizePathname(window.location.pathname || "") === "/pdv/relatorios/cockpit";
}

function getPdvCockpitAppliedFilters() {
  ensurePdvCockpitState();
  return { ...state.pdvCockpit.filters };
}

function buildPdvCockpitQuery(filters = {}) {
  const params = new URLSearchParams();
  params.set("period", normalizeText(filters.period || "30d").toLowerCase() || "30d");
  if (normalizeText(filters.period || "") === "custom") {
    if (normalizeText(filters.start_date || "")) {
      params.set("start_date", normalizeText(filters.start_date || ""));
    }
    if (normalizeText(filters.end_date || "")) {
      params.set("end_date", normalizeText(filters.end_date || ""));
    }
  }
  ["store_id", "brand", "category", "vendor_id", "product_search"].forEach((key) => {
    const value = normalizeText(filters[key] || "");
    if (value) {
      params.set(key, value);
    }
  });
  return params.toString();
}

function getPdvCockpitMetricValue(metric = null, suffix = "") {
  if (!metric || metric.current === null || metric.current === undefined) {
    return "Sem dados";
  }
  if (suffix === "currency") {
    return currency(metric.current);
  }
  if (suffix === "percent") {
    return `${toNumber(metric.current).toFixed(2)}%`;
  }
  return escapeHtml(String(metric.current));
}

function getPdvCockpitTrendTone(trend = "") {
  const normalized = normalizeText(trend || "");
  if (["up", "rising", "recovering"].includes(normalized)) return "success";
  if (["down", "falling", "accelerated_drop"].includes(normalized)) return "danger";
  if (normalized === "stable") return "info";
  return "warning";
}

function buildPdvCockpitDeltaPill(metric = null, { currencyMode = false, percentMode = false } = {}) {
  if (!metric || metric.delta_percent === null || metric.delta_percent === undefined) {
    return `<span class="pdv-report-badge warning">Sem comparativo</span>`;
  }
  const tone = getPdvCockpitTrendTone(metric.trend);
  const deltaValue = currencyMode
    ? currency(metric.delta_value || 0)
    : percentMode
      ? `${toNumber(metric.delta_value || 0).toFixed(2)}%`
      : `${metric.delta_value || 0}`;
  const deltaPercent = `${metric.delta_percent > 0 ? "+" : ""}${toNumber(metric.delta_percent || 0).toFixed(2)}%`;
  const trendLabel = metric.trend === "up" ? "Subiu" : metric.trend === "down" ? "Caiu" : "Estável";
  return `<span class="pdv-report-badge ${tone}" title="${escapeHtml(`Período anterior: ${deltaValue}`)}">${trendLabel} ${escapeHtml(deltaPercent)}</span>`;
}

function buildPdvCockpitSummaryCards() {
  const summary = state.pdvCockpit.summary || {};
  const metrics = summary.metrics || {};
  const cards = [
    { key: "gross_revenue", label: "Faturamento bruto", mode: "currency" },
    { key: "net_revenue", label: "Receita líquida", mode: "currency" },
    { key: "discounts_total", label: "Descontos concedidos", mode: "currency" },
    { key: "cashback_used", label: "Cashback usado", mode: "currency" },
    { key: "items_sold", label: "Peças vendidas", mode: "number" },
    { key: "orders_count", label: "Pedidos", mode: "number" },
    { key: "average_ticket", label: "Ticket médio", mode: "currency" },
    { key: "estimated_margin_percent", label: "Margem estimada", mode: "percent" }
  ];
  if (state.pdvCockpit.loading.summary) {
    return `<div class="pdv-cockpit-summary-grid stats-grid">${cards.map((card) => `
      <article class="stat-card pdv-cockpit-stat-card is-loading">
        <span>${card.label}</span>
        <strong>Carregando...</strong>
        <small>Atualizando comparativo do período.</small>
      </article>
    `).join("")}</div>`;
  }
  if (state.pdvCockpit.errors.summary) {
    return buildPdvCockpitBlockError("Não foi possível carregar a visão geral.", "summary");
  }
  return `<div class="pdv-cockpit-summary-grid stats-grid">${cards.map((card) => {
    const metric = metrics[card.key] || null;
    const value = card.mode === "currency"
      ? getPdvCockpitMetricValue(metric, "currency")
      : card.mode === "percent"
        ? getPdvCockpitMetricValue(metric, "percent")
        : getPdvCockpitMetricValue(metric);
    const helper = metric && metric.previous !== null && metric.previous !== undefined
      ? (card.mode === "currency" ? `Anterior ${currency(metric.previous)}` : card.mode === "percent" ? `Anterior ${toNumber(metric.previous).toFixed(2)}%` : `Anterior ${metric.previous}`)
      : "Sem histórico comparável";
    return `
      <article class="stat-card pdv-cockpit-stat-card">
        <span>${card.label}</span>
        <strong>${value}</strong>
        <div class="pdv-cockpit-stat-meta">
          ${buildPdvCockpitDeltaPill(metric, { currencyMode: card.mode === "currency", percentMode: card.mode === "percent" })}
          <small>${escapeHtml(helper)}</small>
        </div>
      </article>
    `;
  }).join("")}</div>`;
}

function buildPdvCockpitCurveBadge(item = {}) {
  const curve = normalizeText(item.curve || "");
  const toneMap = {
    curva_a: "success",
    curva_isca: "warning",
    curva_luxo: "info",
    curva_b: "low",
    curva_problema: "danger",
    curva_c: "muted"
  };
  return `<span class="pdv-report-badge ${toneMap[curve] || "info"}">${escapeHtml(item.curve_label || item.curve || "Observação")}</span>`;
}

