function getFilteredPdvCockpitCurveRows() {
  ensurePdvCockpitState();
  const curveFilter = normalizeLookup(state.pdvCockpit.curveFilter || "");
  const curveSearch = normalizeLookup(state.pdvCockpit.curveSearch || "");
  const sortBy = normalizeText(state.pdvCockpit.curveSortBy || "total_revenue");
  const sortDir = normalizeText(state.pdvCockpit.curveSortDir || "desc") === "asc" ? "asc" : "desc";
  const rows = toArray(state.pdvCockpit.curve).filter((item) => {
    if (curveFilter && normalizeLookup(item.curve || "") !== curveFilter) {
      return false;
    }
    if (!curveSearch) {
      return true;
    }
    const haystack = normalizeLookup([
      item.name,
      item.sku,
      item.brand,
      item.category,
      item.curve_label,
      item.reason,
      item.suggested_action
    ].join(" "));
    return haystack.includes(curveSearch);
  });
  rows.sort((a, b) => {
    const av = a?.[sortBy];
    const bv = b?.[sortBy];
    const aNumber = typeof av === "number" ? av : toNumber(av, Number.NaN);
    const bNumber = typeof bv === "number" ? bv : toNumber(bv, Number.NaN);
    let result = 0;
    if (!Number.isNaN(aNumber) && !Number.isNaN(bNumber)) {
      result = aNumber - bNumber;
    } else {
      result = String(av || "").localeCompare(String(bv || ""), "pt-BR", { sensitivity: "base" });
    }
    return sortDir === "asc" ? result : -result;
  });
  return rows;
}

function buildPdvCockpitCurveTable() {
  if (state.pdvCockpit.loading.curve) {
    return `<div class="pdv-report-empty-state"><strong>Carregando curva de produtos...</strong><span>Aplicando critérios de caixa, margem, giro e risco para o período atual.</span></div>`;
  }
  if (state.pdvCockpit.errors.curve) {
    return buildPdvCockpitBlockError("Não foi possível carregar a curva de produtos.", "curve");
  }
  const rows = getFilteredPdvCockpitCurveRows();
  const hasRows = rows.length > 0;
  const visibleRows = rows.slice(0, state.pdvCockpit.visibleCurveRows);
  return `
    <div class="pdv-cockpit-curve-toolbar">
      <label>Curva
        <select id="pdv-cockpit-curve-filter">
          <option value="">Todas</option>
          <option value="curva_a"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_a" ? " selected" : ""}>Curva A</option>
          <option value="curva_isca"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_isca" ? " selected" : ""}>Curva Isca</option>
          <option value="curva_luxo"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_luxo" ? " selected" : ""}>Curva Luxo</option>
          <option value="curva_b"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_b" ? " selected" : ""}>Curva B</option>
          <option value="curva_problema"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_problema" ? " selected" : ""}>Curva Problema</option>
          <option value="curva_c"${normalizeText(state.pdvCockpit.curveFilter || "") === "curva_c" ? " selected" : ""}>Curva C</option>
        </select>
      </label>
      <label>Busca local
        <input id="pdv-cockpit-curve-search" type="search" value="${escapeHtml(state.pdvCockpit.curveSearch || "")}" placeholder="Produto, SKU, marca ou ação" />
      </label>
      <label>Ordenar por
        <select id="pdv-cockpit-curve-sort-by">
          <option value="total_revenue"${state.pdvCockpit.curveSortBy === "total_revenue" ? " selected" : ""}>Faturamento</option>
          <option value="gross_margin_percent"${state.pdvCockpit.curveSortBy === "gross_margin_percent" ? " selected" : ""}>Margem %</option>
          <option value="stock_current"${state.pdvCockpit.curveSortBy === "stock_current" ? " selected" : ""}>Estoque</option>
          <option value="days_since_last_sale"${state.pdvCockpit.curveSortBy === "days_since_last_sale" ? " selected" : ""}>Dias sem venda</option>
          <option value="total_quantity"${state.pdvCockpit.curveSortBy === "total_quantity" ? " selected" : ""}>Quantidade</option>
        </select>
      </label>
      <label>Direção
        <select id="pdv-cockpit-curve-sort-dir">
          <option value="desc"${state.pdvCockpit.curveSortDir === "desc" ? " selected" : ""}>Maior primeiro</option>
          <option value="asc"${state.pdvCockpit.curveSortDir === "asc" ? " selected" : ""}>Menor primeiro</option>
        </select>
      </label>
    </div>
    ${hasRows ? `
      <div class="pdv-report-table-wrap pdv-cockpit-curve-wrap">
        <table class="pdv-report-table pdv-cockpit-table">
          <thead>
            <tr>
              <th>Produto</th>
              <th>Curva</th>
              <th>Faturamento</th>
              <th>Quantidade</th>
              <th>Margem %</th>
              <th>Estoque</th>
              <th>Última venda</th>
              <th>Ação</th>
              <th>Motivo</th>
            </tr>
          </thead>
          <tbody>
            ${visibleRows.map((item) => `
              <tr>
                <td>
                  <div class="pdv-cockpit-product-cell">
                    <strong>${escapeHtml(item.name || "-")}</strong>
                    <small>${escapeHtml([item.sku || "-", item.brand || "Sem marca", item.category || "Sem categoria"].join(" • "))}</small>
                  </div>
                </td>
                <td>${buildPdvCockpitCurveBadge(item)}</td>
                <td>${currency(item.total_revenue || 0)}</td>
                <td>${escapeHtml(String(item.total_quantity || 0))}</td>
                <td>${item.gross_margin_percent === null || item.gross_margin_percent === undefined ? "Sem dados" : `${toNumber(item.gross_margin_percent).toFixed(2)}%`}</td>
                <td>${item.stock_current === null || item.stock_current === undefined ? "-" : escapeHtml(String(item.stock_current))}</td>
                <td>${item.last_sale_date ? escapeHtml(formatDateBR(item.last_sale_date)) : "-"}</td>
                <td>
                  <div class="pdv-cockpit-action-cell">
                    <strong>${escapeHtml(item.suggested_action || "Monitorar")}</strong>
                    <small>${escapeHtml(item.days_since_last_sale !== null && item.days_since_last_sale !== undefined ? `${item.days_since_last_sale} dia(s) sem venda` : "Sem histórico de giro")}</small>
                  </div>
                </td>
                <td>${escapeHtml(item.reason || "-")}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
      ${rows.length > visibleRows.length ? `<div class="action-row"><button class="ghost-button" type="button" data-pdv-cockpit-more-curve="true">Ver mais ${Math.min(20, rows.length - visibleRows.length)} itens</button></div>` : ""}
    ` : buildPdvCockpitEmptyState("Sem produtos relevantes neste período.", "Ajuste os filtros ou remova restrições para visualizar a curva inteligente.")}
  `;
}

function buildPdvCockpitDecisionCard(title = "", group = null, tone = "info") {
  const items = toArray(group?.items);
  if (!items.length) {
    return `
      <article class="panel pdv-cockpit-decision-card">
        <div class="panel-header compact"><h3>${escapeHtml(title)}</h3><span class="pdv-report-badge ${tone}">0 itens</span></div>
        ${buildPdvCockpitEmptyState("Nenhum produto neste grupo para o período selecionado.", group?.empty_state || "Sem itens acionáveis no recorte atual.")}
      </article>
    `;
  }
  return `
    <article class="panel pdv-cockpit-decision-card">
      <div class="panel-header compact"><h3>${escapeHtml(title)}</h3><span class="pdv-report-badge ${tone}">${items.length} itens</span></div>
      <div class="pdv-cockpit-decision-list">
        ${items.slice(0, 5).map((item) => `
          <article class="pdv-cockpit-decision-item">
            <div class="pdv-cockpit-decision-head">
              <strong>${escapeHtml(item.name || "-")}</strong>
              <span>${escapeHtml(item.sku || "-")}</span>
            </div>
            <small>${escapeHtml([item.brand || "Sem marca", item.category || "Sem categoria", `Estoque ${item.stock_current ?? "-"}`].join(" • "))}</small>
            <p>${escapeHtml(item.reason || "-")}</p>
            <div class="pdv-cockpit-decision-foot">
              ${buildPdvCockpitCurveBadge(item)}
              <span>${escapeHtml(item.suggested_action || "Monitorar")}</span>
            </div>
          </article>
        `).join("")}
      </div>
    </article>
  `;
}

