function buildWhatsappCrmOperationDetail() {
  if (!canViewWhatsappCampaigns()) {
    return "";
  }
  if (state.whatsappCrm.operationLoading) {
    return `<div class="empty-state compact"><strong>Carregando operacao...</strong><span>Buscando contatos, logs e status real da campanha selecionada.</span></div>`;
  }
  if (state.whatsappCrm.operationError) {
    return `<div class="empty-state compact"><strong>Falha ao carregar operacao</strong><span>${escapeHtml(state.whatsappCrm.operationError)}</span></div>`;
  }
  const payload = state.whatsappCrm.operationData;
  if (!payload?.campaign) {
    return `<div class="empty-state compact"><strong>Selecione uma campanha</strong><span>Os detalhes da operacao, logs e ultimo preview real aparecem aqui.</span></div>`;
  }
  const campaign = payload.campaign || {};
  const contacts = toArray(payload.contacts).slice(0, 5);
  const logs = toArray(payload.logs).slice(0, 5);
  const mediaUrl = normalizeText(payload.media?.preview_url || payload.media?.previewUrl || campaign.preview_url || "");
  return `
    <div class="whatsapp-crm-operation-card">
      <div class="panel-header">
        <h3>${escapeHtml(campaign.name || "Campanha selecionada")}</h3>
        <span class="table-meta">${escapeHtml(getWhatsappCrmCampaignStatusLabel(campaign))} • ${escapeHtml(formatStoreIdLabel(campaign.loja || campaign.store || ""))}</span>
      </div>
      <div class="stats-grid whatsapp-crm-operation-stats">
        <article class="stat-card"><span>Contatos</span><strong>${escapeHtml(String(payload.summary?.total || contacts.length || 0))}</strong></article>
        <article class="stat-card"><span>Enviados</span><strong>${escapeHtml(String(payload.summary?.sent || 0))}</strong></article>
        <article class="stat-card"><span>Pendentes</span><strong>${escapeHtml(String(payload.summary?.pending || 0))}</strong></article>
        <article class="stat-card"><span>Erros</span><strong>${escapeHtml(String(payload.summary?.errors || 0))}</strong></article>
      </div>
      <div class="split-grid whatsapp-crm-operation-grid">
        <article class="panel whatsapp-crm-preview-panel">
          <div class="panel-header">
            <h3>Preview salvo</h3>
            <span class="table-meta">Texto real da campanha selecionada, sem reescrita por IA nesta frente.</span>
          </div>
          <div class="message-preview whatsapp-crm-literal-preview">${escapeHtml(campaign.message || campaign.template || "Sem mensagem cadastrada.")}</div>
          ${mediaUrl ? `
            <div class="whatsapp-crm-media-preview-box">
              <strong>Midia vinculada</strong>
              <img src="${escapeHtml(mediaUrl)}" alt="Preview da midia da campanha" />
            </div>
          ` : ""}
        </article>
        <article class="panel">
          <div class="panel-header">
            <h3>Ultimos contatos</h3>
          </div>
          ${contacts.length ? `
            <div class="whatsapp-crm-mini-list">
              ${contacts.map((item) => `
                <article class="search-result-card">
                  <strong>${escapeHtml(item.name || "Contato")}</strong>
                  <span>${escapeHtml(formatPhoneBR(item.phone || "") || "-")} • ${escapeHtml(item.execution_status || item.status || "-")}</span>
                </article>
              `).join("")}
            </div>
          ` : `<div class="empty-state compact"><strong>Sem contatos carregados</strong><span>Esta campanha ainda nao possui contatos vinculados nesta operacao.</span></div>`}
        </article>
      </div>
      <article class="panel">
        <div class="panel-header">
          <h3>Logs da campanha</h3>
        </div>
        ${logs.length ? `
          <div class="table-wrap">
            <table class="pdv-customers-table whatsapp-crm-table">
              <thead>
                <tr>
                  <th>Data</th>
                  <th>Contato</th>
                  <th>Status</th>
                  <th>Detalhe</th>
                </tr>
              </thead>
              <tbody>
                ${logs.map((row) => `
                  <tr>
                    <td>${escapeHtml(formatDateTimeBR(row.sent_at || row.created_at || ""))}</td>
                    <td>${escapeHtml(row.contact_name || row.customer_name || "Contato")}</td>
                    <td>${escapeHtml(row.status || "-")}</td>
                    <td>${escapeHtml(row.error || row.error_message || row.caption_final || row.message_text || "Sem detalhe adicional")}</td>
                  </tr>
                `).join("")}
              </tbody>
            </table>
          </div>
        ` : `<div class="empty-state compact"><strong>Sem logs detalhados</strong><span>Esta operacao ainda nao registrou envios ou retornos visiveis.</span></div>`}
      </article>
    </div>
  `;
}

function buildWhatsappCrmCampaignComposer() {
  ensureWhatsappCrmCampaignDraft();
  const draft = state.whatsappCrm.campaignDraft;
  const storeOptions = getWhatsappCrmStoreOptions();
  const selectedStoreLabel = formatStoreIdLabel(draft.store || getCurrentPdvStoreId() || getCurrentUserStoreLabel());
  const previewText = getWhatsappCrmCampaignPreviewText();
  const previewBadge = getWhatsappCrmCampaignMessageModeLabel(draft.messageMode || "manual");
  const audience = getWhatsappCrmCampaignAudienceSnapshot();
  const previewStatus = getWhatsappCrmCampaignPreviewStatus();
  const templates = toArray(state.aiTemplates).slice(0, 4);
  const canRemoveMedia = Boolean(draft.mediaPreviewUrl || draft.mediaId);
  const audienceFilters = getWhatsappCrmCampaignFilterDraft();
  const selectedContacts = getWhatsappCrmCampaignSelectedContacts();
  const sellerOptions = getOrderedSellers(draft.store || "", false);
  const topSizeOptions = getWhatsappCrmCampaignAudienceFilterOptions("topSize", draft.store || "");
  const bottomSizeOptions = getWhatsappCrmCampaignAudienceFilterOptions("bottomSize", draft.store || "");
  const shoeSizeOptions = getWhatsappCrmCampaignAudienceFilterOptions("shoeSize", draft.store || "");
  const isManualAudience = draft.audienceScope === "manual_selection" || draft.audienceScope === "campaign_contacts";
  const isAdvancedAudience = draft.audienceScope === "advanced_filter";
  const saveButtonLabel = state.whatsappCrm.campaignSaveStep === "uploading_media"
    ? "Enviando midia..."
    : state.whatsappCrm.campaignSaving
      ? "Salvando..."
      : "Salvar rascunho";
  return `
    <div class="split-grid whatsapp-crm-composer-grid">
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Rascunho operacional de campanha</h3>
          <span class="table-meta">Salva campanha real em rascunho, sem disparar nada automaticamente.</span>
        </div>
        ${canManageWhatsappCampaigns() ? `
          <form data-whatsapp-crm-campaign-form="true" class="whatsapp-crm-campaign-form">
            <input type="hidden" name="campaignId" value="${escapeHtml(String(draft.id || ""))}" />
            <div class="form-grid">
              <label>
                Nome da campanha
                <input name="campaignName" type="text" value="${escapeHtml(draft.name || "")}" placeholder="Ex.: Preview Dia das Maes" required />
              </label>
              ${canViewAllStores() ? `
                <label>
                  Loja
                  <select name="campaignStore">
                    ${storeOptions.map((option) => `<option value="${escapeHtml(option.value)}"${normalizeText(option.value) === normalizeText(draft.store || "") ? " selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
                  </select>
                </label>
              ` : `
                <label>
                  Loja
                  <input type="text" value="${escapeHtml(selectedStoreLabel)}" disabled />
                  <input type="hidden" name="campaignStore" value="${escapeHtml(draft.store || getCurrentPdvStoreId() || "")}" />
                </label>
              `}
              <label>
                Tipo de envio
                <select name="campaignSendType">
                  <option value="text"${draft.sendType === "text" ? " selected" : ""}>Texto</option>
                  <option value="image"${draft.sendType === "image" ? " selected" : ""}>Imagem</option>
                  <option value="image_with_caption"${draft.sendType === "image_with_caption" ? " selected" : ""}>Imagem com legenda</option>
                  <option value="video"${draft.sendType === "video" ? " selected" : ""}>Video</option>
                  <option value="video_with_caption"${draft.sendType === "video_with_caption" ? " selected" : ""}>Video com legenda</option>
                </select>
              </label>
              <label>
                Modo da mensagem
                <select name="campaignMessageMode">
                  <option value="manual"${draft.messageMode === "manual" ? " selected" : ""}>Texto manual</option>
                  <option value="template"${draft.messageMode === "template" ? " selected" : ""}>Template</option>
                  <option value="ai"${draft.messageMode === "ai" ? " selected" : ""}>IA / Assistant</option>
                </select>
              </label>
              <label>
                Tipo de publico
                <select name="campaignAudienceScope">
                  <option value="none"${draft.audienceScope === "none" ? " selected" : ""}>Sem publico definido</option>
                  <option value="store_all"${draft.audienceScope === "store_all" ? " selected" : ""}>Clientes da loja</option>
                  <option value="store_whatsapp_valid"${draft.audienceScope === "store_whatsapp_valid" ? " selected" : ""}>Clientes com WhatsApp valido</option>
                  <option value="cashback_active"${draft.audienceScope === "cashback_active" ? " selected" : ""}>Clientes da loja com cashback ativo</option>
                  <option value="cashback_expiring_7d"${draft.audienceScope === "cashback_expiring_7d" ? " selected" : ""}>Cashback vencendo em 7 dias</option>
                  <option value="cashback_expiring_3d"${draft.audienceScope === "cashback_expiring_3d" ? " selected" : ""}>Cashback vencendo em 3 dias</option>
                  <option value="manual_selection"${isManualAudience ? " selected" : ""}>Selecao manual</option>
                  <option value="advanced_filter"${draft.audienceScope === "advanced_filter" ? " selected" : ""}>Filtro avancado</option>
                </select>
              </label>
              <div class="pdv-customers-wide-field">
                <div class="panel whatsapp-crm-panel">
                  <div class="panel-header">
                    <h3>Publico da campanha</h3>
                    <span class="table-meta">Defina os clientes antes da execucao. Salvar rascunho continua seguro e nao dispara campanha.</span>
                  </div>
                  <div class="form-grid">
                    ${isAdvancedAudience ? `
                      <label>
                        Genero
                        <select name="campaignAudienceGender">
                          <option value="">Todos</option>
                          <option value="feminino"${audienceFilters.gender === "feminino" ? " selected" : ""}>Feminino</option>
                          <option value="masculino"${audienceFilters.gender === "masculino" ? " selected" : ""}>Masculino</option>
                          <option value="outro"${audienceFilters.gender === "outro" ? " selected" : ""}>Outro</option>
                        </select>
                      </label>
                      <label>
                        Vendedor
                        <select name="campaignAudienceSellerId">
                          <option value="">Todos</option>
                          ${sellerOptions.map((seller) => `<option value="${escapeHtml(String(seller.id))}"${String(seller.id) === String(audienceFilters.sellerId || "") ? " selected" : ""}>${escapeHtml(seller.name || "Vendedor")} - ${escapeHtml(formatStoreIdLabel(seller.store || ""))}</option>`).join("")}
                        </select>
                      </label>
                      <label>
                        Parte de cima
                        <select name="campaignAudienceTopSize">
                          <option value="">Todos</option>
                          ${topSizeOptions.map((value) => `<option value="${escapeHtml(value)}"${value === audienceFilters.topSize ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}
                        </select>
                      </label>
                      <label>
                        Parte de baixo
                        <select name="campaignAudienceBottomSize">
                          <option value="">Todos</option>
                          ${bottomSizeOptions.map((value) => `<option value="${escapeHtml(value)}"${value === audienceFilters.bottomSize ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}
                        </select>
                      </label>
                      <label>
                        Calcado
                        <select name="campaignAudienceShoeSize">
                          <option value="">Todos</option>
                          ${shoeSizeOptions.map((value) => `<option value="${escapeHtml(value)}"${value === audienceFilters.shoeSize ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}
                        </select>
                      </label>
                      <label>
                        WhatsApp valido
                        <select name="campaignAudienceHasWhatsapp">
                          <option value="">Todos</option>
                          <option value="1"${audienceFilters.hasWhatsapp === "1" ? " selected" : ""}>Somente validos</option>
                          <option value="0"${audienceFilters.hasWhatsapp === "0" ? " selected" : ""}>Somente sem WhatsApp valido</option>
                        </select>
                      </label>
                    ` : ""}
                    ${isManualAudience ? `
                      <label class="pdv-customers-wide-field">
                        Buscar cliente
                        <div class="action-row whatsapp-crm-action-row">
                          <input name="campaignAudienceSearchQuery" type="text" value="${escapeHtml(state.whatsappCrm.campaignAudienceSearchQuery || "")}" placeholder="Buscar por nome ou telefone" />
                          <button class="ghost-button" type="button" data-whatsapp-crm-audience-search="true"${state.whatsappCrm.campaignAudienceSearchLoading ? " disabled" : ""}>${state.whatsappCrm.campaignAudienceSearchLoading ? "Buscando..." : "Buscar cliente"}</button>
                        </div>
                      </label>
                    ` : ""}
                  </div>
                  <div class="stats-grid whatsapp-crm-operation-stats">
                    <article class="stat-card"><span>Total encontrado</span><strong>${escapeHtml(String(audience.estimatedCount || 0))}</strong></article>
                    <article class="stat-card"><span>WhatsApps validos</span><strong>${escapeHtml(String(audience.validWhatsappCount || 0))}</strong></article>
                    <article class="stat-card"><span>Sem WhatsApp</span><strong>${escapeHtml(String(audience.invalidWhatsappCount || 0))}</strong></article>
                    <article class="stat-card"><span>Selecionados</span><strong>${escapeHtml(String(audience.selectedCount || audience.linkedCount || 0))}</strong></article>
                  </div>
                  <div class="pdv-customers-callout">
                    <strong>${escapeHtml(previewStatus.label)}</strong>
                    <span>${escapeHtml(isManualAudience ? "Adicione clientes manualmente e preserve a lista ao salvar o rascunho." : isAdvancedAudience ? "Use apenas filtros com dados reais disponiveis nesta base." : "O escopo escolhido atualiza a estimativa antes da revisao da campanha.")}</span>
                  </div>
                  ${state.whatsappCrm.campaignAudienceError ? `<div class="empty-state compact"><strong>Falha ao montar o publico</strong><span>${escapeHtml(state.whatsappCrm.campaignAudienceError)}</span></div>` : ""}
                  ${state.whatsappCrm.campaignAudienceSearchError && isManualAudience ? `<div class="empty-state compact"><strong>Busca manual incompleta</strong><span>${escapeHtml(state.whatsappCrm.campaignAudienceSearchError)}</span></div>` : ""}
                  ${isManualAudience ? `
                    <div class="split-grid">
                      <div>
                        <strong>Resultados da busca</strong>
                        <div class="whatsapp-crm-template-list">
                          ${toArray(state.whatsappCrm.campaignAudienceSearchResults).length ? toArray(state.whatsappCrm.campaignAudienceSearchResults).map((item) => `
                            <article class="search-result-card">
                              <strong>${escapeHtml(item.name || "Cliente")}</strong>
                              <span>${escapeHtml(formatPhoneBR(item.phone || "") || "Sem telefone")} • ${escapeHtml(formatStoreIdLabel(item.store || ""))}</span>
                              <div class="action-row">
                                <button class="ghost-button" type="button" data-whatsapp-crm-audience-add="${escapeHtml(String(item.contactKey || item.id || ""))}">Adicionar</button>
                              </div>
                            </article>
                          `).join("") : `<div class="empty-state compact"><strong>Nenhum cliente encontrado</strong><span>Busque por nome ou telefone para montar a selecao manual.</span></div>`}
                        </div>
                      </div>
                      <div>
                        <strong>Selecionados manualmente</strong>
                        <div class="whatsapp-crm-template-list">
                          ${selectedContacts.length ? selectedContacts.map((item) => `
                            <article class="search-result-card">
                              <strong>${escapeHtml(item.name || "Cliente")}</strong>
                              <span>${escapeHtml(formatPhoneBR(item.phone || "") || "Sem telefone")} • ${escapeHtml(formatStoreIdLabel(item.store || ""))}</span>
                              <div class="action-row">
                                <button class="ghost-button" type="button" data-whatsapp-crm-audience-remove="${escapeHtml(String(item.id || item.contact_id || ""))}">Remover</button>
                              </div>
                            </article>
                          `).join("") : `<div class="empty-state compact"><strong>Selecao manual sem clientes</strong><span>Adicione pelo menos um cliente para liberar a revisao deste publico.</span></div>`}
                        </div>
                      </div>
                    </div>
                  ` : ""}
                  <div class="empty-state compact">
                    <strong>Filtros indisponiveis nesta rodada</strong>
                    <span>Marca de interesse permanece fora do composer porque a base atual nao expõe esse dado de forma confiavel para campanha.</span>
                  </div>
                </div>
              </div>
              <label class="pdv-customers-wide-field">
                Mensagem
                <textarea name="campaignMessage" data-whatsapp-crm-preview-input="message" placeholder="Digite a mensagem exata que deve aparecer no preview operacional.">${escapeHtml(draft.message || "")}</textarea>
              </label>
              ${(draft.sendType === "image_with_caption" || draft.sendType === "video_with_caption") ? `
                <label class="pdv-customers-wide-field">
                  Legenda da midia
                  <textarea name="campaignCaption" data-whatsapp-crm-preview-input="caption" placeholder="Legenda opcional para a midia.">${escapeHtml(draft.caption || "")}</textarea>
                </label>
              ` : ""}
              ${draft.sendType !== "text" ? `
                <label class="pdv-customers-wide-field">
                  Midia
                  <input name="campaignMedia" type="file" accept="image/*,video/*" data-whatsapp-crm-campaign-media="true" />
                  <small class="table-meta">O preview local aparece abaixo antes de salvar. Nao dispara campanha real.</small>
                </label>
              ` : ""}
            </div>
            <div class="action-row whatsapp-crm-action-row">
              <button class="primary-button" type="submit"${state.whatsappCrm.campaignSaving ? " disabled" : ""}>${saveButtonLabel}</button>
              <button class="ghost-button" type="button" data-whatsapp-crm-refresh-preview="true"${state.whatsappCrm.campaignSaving ? " disabled" : ""}>Atualizar preview</button>
              ${canRemoveMedia ? `<button class="ghost-button" type="button" data-whatsapp-crm-remove-media="true"${state.whatsappCrm.campaignSaving ? " disabled" : ""}>Remover midia</button>` : ""}
              <button class="ghost-button" type="button" data-whatsapp-crm-new-draft="true">Novo rascunho</button>
              <button class="ghost-button" type="button" data-whatsapp-crm-refresh-campaigns="true">Atualizar campanhas</button>
            </div>
          </form>
        ` : `
          <div class="empty-state compact">
            <strong>Edicao protegida por permissao</strong>
            <span>Seu perfil pode acompanhar campanhas e execucoes, mas nao pode criar ou editar rascunhos nesta frente.</span>
          </div>
        `}
      </article>
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Preview obrigatorio</h3>
          <span class="table-meta">${escapeHtml(previewBadge)} • Se voce digitar "teste", o preview mostra "teste" exatamente.</span>
        </div>
        <div class="pdv-customers-callout">
          <strong>${escapeHtml(previewStatus.label)}</strong>
          <span>${escapeHtml(previewStatus.helper)}</span>
        </div>
        <div class="message-preview whatsapp-crm-literal-preview">${escapeHtml(previewText)}</div>
        ${(draft.sendType === "image_with_caption" || draft.sendType === "video_with_caption") && normalizeText(draft.caption || "") ? `
          <div class="message-preview compact whatsapp-crm-preview-caption">${escapeHtml(draft.caption || "")}</div>
        ` : ""}
        ${draft.mediaPreviewUrl ? `
          <div class="whatsapp-crm-media-preview-box">
            <strong>Preview da midia</strong>
            ${draft.mediaPreviewType === "video"
              ? `<video src="${escapeHtml(draft.mediaPreviewUrl)}" controls></video>`
              : `<img src="${escapeHtml(draft.mediaPreviewUrl)}" alt="Preview da midia da campanha" />`}
            <span class="table-meta">${escapeHtml(draft.mediaName || "Arquivo selecionado")} • ${escapeHtml(draft.mediaPreviewType === "video" ? "Video" : "Imagem")}</span>
          </div>
        ` : draft.sendType !== "text" ? `
          <div class="empty-state compact">
            <strong>Sem midia selecionada</strong>
            <span>Quando a campanha usar imagem ou video, o preview real do arquivo aparece aqui.</span>
          </div>
        ` : ""}
        <div class="stats-grid whatsapp-crm-operation-stats">
          <article class="stat-card"><span>Escopo</span><strong>${escapeHtml(audience.scopeLabel)}</strong></article>
          <article class="stat-card"><span>Publico estimado</span><strong>${escapeHtml(String(audience.estimatedCount || 0))}</strong></article>
          <article class="stat-card"><span>Contatos vinculados</span><strong>${escapeHtml(String(audience.selectedCount || audience.linkedCount || 0))}</strong></article>
          <article class="stat-card"><span>Execucao real</span><strong>Separada</strong></article>
        </div>
        ${state.whatsappCrm.campaignAudienceLoading ? `<div class="empty-state compact"><strong>Atualizando publico...</strong><span>Conferindo o escopo real do rascunho sem disparar campanha.</span></div>` : ""}
        ${state.whatsappCrm.campaignAudienceError ? `<div class="empty-state compact"><strong>Falha ao validar publico</strong><span>${escapeHtml(state.whatsappCrm.campaignAudienceError)}</span></div>` : ""}
        <div class="whatsapp-crm-template-strip">
          <strong>Modelos e IA</strong>
          <span class="table-meta">Os modelos abaixo so preenchem o rascunho quando voce clicar. Texto manual continua literal e nao e reescrito sozinho.</span>
          <div class="whatsapp-crm-template-list">
            ${templates.length ? templates.map((template) => `
              <article class="search-result-card">
                <strong>${escapeHtml(template.title || "Modelo")}</strong>
                <span>${escapeHtml(template.template || "")}</span>
                ${canManageWhatsappCampaigns() ? `<button class="ghost-button" type="button" data-whatsapp-crm-use-template="${escapeHtml((template.template || "").replace(/"/g, "&quot;"))}">Usar no preview</button>` : ""}
              </article>
            `).join("") : `<div class="empty-state compact"><strong>Sem modelos carregados</strong><span>Os templates da IA continuam acessiveis quando a base legada estiver disponivel.</span></div>`}
          </div>
        </div>
      </article>
    </div>
  `;
}

function buildWhatsappCrmAssistantPreviewCard() {
  if (state.whatsappCrm.assistantLoading) {
    return `<div class="empty-state compact"><strong>Preparando preview...</strong><span>Buscando o proximo contato da campanha sem disparar nenhuma mensagem real.</span></div>`;
  }
  if (state.whatsappCrm.assistantError) {
    return `<div class="empty-state compact"><strong>Falha no assistant</strong><span>${escapeHtml(state.whatsappCrm.assistantError)}</span></div>`;
  }
  const preview = state.whatsappCrm.assistantPreview;
  if (!preview?.contact) {
    return `
      <div class="empty-state compact">
        <strong>Assistant pronto para simular</strong>
        <span>Selecione uma campanha, ajuste os filtros e clique em "Simular proximo contato". Nada e enviado automaticamente.</span>
      </div>
    `;
  }
  return `
    <div class="assistant-layout whatsapp-crm-assistant-card">
      <div class="badge">Contato #${escapeHtml(String(preview.contact.id || "-"))}</div>
      <span>Campanha: ${escapeHtml(preview.campaign?.name || "Sem campanha")}</span>
      <span>Telefone: ${escapeHtml(formatPhoneBR(preview.contact.phone || "") || "-")}</span>
      <span>Loja: ${escapeHtml(preview.contact.store || preview.campaign?.store || "-")}</span>
      <span>Status: ${escapeHtml(preview.contact.status || "-")}</span>
      <span>Progresso: ${escapeHtml(String(preview.index || 1))} de ${escapeHtml(String(preview.total || 1))}</span>
      <h4>${escapeHtml(preview.contact.name || "Contato")}</h4>
      <div class="message-preview whatsapp-crm-literal-preview">${escapeHtml(preview.message || "")}</div>
      <div class="action-row whatsapp-crm-action-row">
        <button class="ghost-button" type="button" data-whatsapp-crm-assistant-copy="preview">Copiar preview</button>
        <button class="secondary-button" type="button" data-whatsapp-crm-assistant-apply="preview">Aplicar em campanha</button>
        <button class="ghost-button" type="button" data-whatsapp-crm-assistant-next="true">Proximo contato</button>
      </div>
    </div>
  `;
}

function buildWhatsappCrmAssistantTab() {
  ensureWhatsappCrmAssistantDraft();
  const draft = state.whatsappCrm.assistantDraft;
  const visibleCampaigns = getVisibleWhatsappCampaigns(state.whatsappCrm.campaigns);
  const storeOptions = getWhatsappCrmStoreOptions();
  const templates = toArray(state.aiTemplates);
  const previewText = getWhatsappCrmAssistantPreviewText();
  return `
    <div class="split-grid whatsapp-crm-assistant-grid">
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Templates e IA</h3>
          <span class="table-meta">Reaproveita os modelos do legado e gera variacoes sem enviar WhatsApp real.</span>
        </div>
        <form data-whatsapp-crm-assistant-generate-form="true" class="whatsapp-crm-campaign-form">
          <div class="form-grid">
            <label class="pdv-customers-wide-field">
              Mensagem base
              <textarea name="assistantBase" data-whatsapp-crm-assistant-input="base" placeholder="Digite a mensagem base ou carregue um template.">${escapeHtml(draft.base || "")}</textarea>
            </label>
            <label>
              Estilo
              <select name="assistantStyle" data-whatsapp-crm-assistant-input="style">
                <option value="elegante"${draft.style === "elegante" ? " selected" : ""}>Elegante</option>
                <option value="direto"${draft.style === "direto" ? " selected" : ""}>Direto</option>
                <option value="caloroso"${draft.style === "caloroso" ? " selected" : ""}>Caloroso</option>
              </select>
            </label>
          </div>
          <div class="action-row whatsapp-crm-action-row">
            <button class="primary-button" type="submit"${state.whatsappCrm.assistantGenerating ? " disabled" : ""}>${state.whatsappCrm.assistantGenerating ? "Gerando..." : "Gerar preview IA"}</button>
            <button class="ghost-button" type="button" data-whatsapp-crm-assistant-copy="result">Copiar preview</button>
            <button class="secondary-button" type="button" data-whatsapp-crm-assistant-apply="result">Aplicar em campanha</button>
          </div>
        </form>
        <div class="message-preview whatsapp-crm-literal-preview">${escapeHtml(previewText)}</div>
        <div class="whatsapp-crm-template-strip">
          <strong>Templates reais</strong>
          <span class="table-meta">Os modelos continuam vindo de <code>/api/ai/templates</code> e apenas preenchem o preview.</span>
          <div class="whatsapp-crm-template-list">
            ${templates.length ? templates.map((template) => `
              <article class="search-result-card">
                <strong>${escapeHtml(template.title || "Template")}</strong>
                <span>${escapeHtml(template.template || "")}</span>
                <div class="table-actions">
                  <button class="ghost-button" type="button" data-whatsapp-crm-assistant-template="${escapeHtml((template.template || "").replace(/"/g, "&quot;"))}">Usar template</button>
                </div>
              </article>
            `).join("") : `<div class="empty-state compact"><strong>Sem templates carregados</strong><span>Se a IA ficar indisponivel, a frente continua mostrando esse aviso sem quebrar o WhatsApp CRM.</span></div>`}
          </div>
        </div>
      </article>
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Assistant operacional</h3>
          <span class="table-meta">Simula o proximo contato da campanha usando o mesmo legado de <code>#assistant</code>, sem abrir WhatsApp e sem registrar envio.</span>
        </div>
        <form data-whatsapp-crm-assistant-preview-form="true" class="whatsapp-crm-campaign-form">
          <div class="form-grid">
            <label>
              Campanha
              <select name="assistantCampaignId" data-whatsapp-crm-assistant-input="campaignId">
                <option value="">Selecione</option>
                ${visibleCampaigns.map((campaign) => `<option value="${escapeHtml(String(campaign.id || ""))}"${String(campaign.id || "") === String(draft.campaignId || "") ? " selected" : ""}>${escapeHtml(campaign.name || "Campanha")} • ${escapeHtml(formatStoreIdLabel(campaign.store || ""))}</option>`).join("")}
              </select>
            </label>
            <label>
              Tag
              <input name="assistantTag" type="text" value="${escapeHtml(draft.tag || "")}" data-whatsapp-crm-assistant-input="tag" placeholder="vip" />
            </label>
            <label>
              Status
              <select name="assistantStatus" data-whatsapp-crm-assistant-input="status">
                <option value="">Todos</option>
                ${toArray(state.settings?.contactStatuses).map((value) => `<option value="${escapeHtml(value)}"${value === draft.status ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}
              </select>
            </label>
            <label>
              Genero
              <select name="assistantGender" data-whatsapp-crm-assistant-input="gender">
                <option value="">Todos</option>
                ${toArray(state.settings?.contactGenders).map((value) => `<option value="${escapeHtml(value)}"${value === draft.gender ? " selected" : ""}>${escapeHtml(value)}</option>`).join("")}
              </select>
            </label>
            ${canViewAllStores() ? `
              <label>
                Loja
                <select name="assistantStore" data-whatsapp-crm-assistant-input="store">
                  <option value="">Todas</option>
                  ${storeOptions.map((option) => `<option value="${escapeHtml(option.value)}"${normalizeText(option.value) === normalizeText(draft.store || "") ? " selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
                </select>
              </label>
            ` : `
              <label>
                Loja
                <input type="text" value="${escapeHtml(formatStoreIdLabel(draft.store || getCurrentPdvStoreId() || ""))}" disabled />
              </label>
            `}
            <label>
              Vendedor
              <select name="assistantSellerId" data-whatsapp-crm-assistant-input="sellerId">
                <option value="">Todos</option>
                ${getOrderedSellers(draft.store || getCurrentPdvStoreId() || "", false).map((seller) => `<option value="${escapeHtml(String(seller.id || ""))}"${String(seller.id || "") === String(draft.sellerId || "") ? " selected" : ""}>${escapeHtml(seller.name)} • ${escapeHtml(seller.store || "-")}</option>`).join("")}
              </select>
            </label>
            <label>
              Cashback ativo
              <select name="assistantCashbackActive" data-whatsapp-crm-assistant-input="cashbackActive">
                <option value="">Todos</option>
                <option value="1"${draft.cashbackActive === "1" ? " selected" : ""}>Somente com cashback ativo</option>
              </select>
            </label>
          </div>
          <div class="action-row whatsapp-crm-action-row">
            <button class="primary-button" type="submit"${state.whatsappCrm.assistantLoading ? " disabled" : ""}>${state.whatsappCrm.assistantLoading ? "Simulando..." : "Simular proximo contato"}</button>
            <button class="ghost-button" type="button" data-whatsapp-crm-assistant-reset="true">Limpar filtros</button>
          </div>
        </form>
        ${buildWhatsappCrmAssistantPreviewCard()}
      </article>
    </div>
  `;
}

function buildWhatsappCrmTabContent() {
  if (state.whatsappCrm.activeTab === "campanhas") {
    const summary = getWhatsappCrmCampaignSummary(state.whatsappCrm.campaigns);
    return `
      <div class="stats-grid whatsapp-crm-campaign-summary">
        <article class="stat-card"><span>Campanhas visiveis</span><strong>${escapeHtml(String(summary.total))}</strong></article>
        <article class="stat-card"><span>Ativas</span><strong>${escapeHtml(String(summary.active))}</strong></article>
        <article class="stat-card"><span>Rascunhos</span><strong>${escapeHtml(String(summary.drafts))}</strong></article>
        <article class="stat-card"><span>Com midia</span><strong>${escapeHtml(String(summary.withMedia))}</strong></article>
      </div>
      ${buildWhatsappCrmCampaignComposer()}
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Campanhas do CRM</h3>
          <span class="table-meta">Lista real reaproveitada da operacao legada, agora dentro da frente oficial do WhatsApp CRM.</span>
        </div>
        ${buildWhatsappCrmCampaignList()}
      </article>
      <article class="panel whatsapp-crm-panel">
        ${buildWhatsappCrmOperationDetail()}
      </article>
    `;
  }
  if (state.whatsappCrm.activeTab === "execucoes") {
    return `
      <article class="panel whatsapp-crm-panel">
        <div class="panel-header">
          <h3>Execucoes de campanha</h3>
          <span class="table-meta">Resumo operacional sem disparar campanha real nesta frente.</span>
        </div>
        ${buildWhatsappCrmExecutionTable()}
      </article>
      <article class="panel whatsapp-crm-panel">
        ${buildWhatsappCrmOperationDetail()}
      </article>
    `;
  }
  if (state.whatsappCrm.activeTab === "assistant") {
    return buildWhatsappCrmAssistantTab();
  }
  return "";
}

function renderWhatsAppRouteFront() {
  const section = document.getElementById("whatsapp-crm");
  if (!section) {
    return;
  }
  ensureWhatsappCrmCampaignDraft();
  const statusData = state.whatsappCrm.statusData || {};
  const statusMeta = getWhatsappCrmStatusMeta(statusData);
  const connectedNumber = normalizeText(statusData.connectedNumber || state.whatsappConnectedNumber || "");
  const whatsappStoreLabel = getPdvStoreDisplayName(statusData.store?.store_id || statusData.store?.id || statusData.store?.label || getCurrentPdvStoreId(), statusData.store?.label || getCurrentUserStoreLabel());
  const qrWindowActive = Boolean(state.whatsappCrm.qrWindowOpen || statusData.qrRequestActive);
  const hasQr = qrWindowActive && Boolean(state.whatsappCrm.qrData?.qrBase64);
  const showQrActions = canReconnectWhatsappCrm();
  const showOpenQrButton = showQrActions && !qrWindowActive;
  const showCloseQrButton = showQrActions && qrWindowActive;
  const logsVisible = canViewWhatsappLogs();
  const showCampaignTabs = canViewWhatsappCampaigns();
  const showAssistantTab = canViewWhatsappAssistant();
  const activeTab = (showCampaignTabs || showAssistantTab) ? (state.whatsappCrm.activeTab || "motor") : "motor";
  section.innerHTML = `
    <div id="whatsapp-crm-content" class="whatsapp-crm-shell">
      <div class="hero-card pdv-hero-card">
        <div>
          <p class="eyebrow">WhatsApp CRM</p>
          <h3>Motor oficial da loja ativa para conexao, monitoramento e envio operacional.</h3>
          <p class="helper-text">${escapeHtml(state.whatsappCrm.error || state.whatsappCrm.qrClosedNotice || statusMeta.detail)}</p>
        </div>
        <div class="stats-grid pdv-route-summary">
          <div class="stat-card">
            <span>Loja ativa</span>
            <strong>${escapeHtml(whatsappStoreLabel)}</strong>
          </div>
          <div class="stat-card">
            <span>Perfil</span>
            <strong>${escapeHtml(getRoleLabel(getCurrentRole()))}</strong>
          </div>
          <div class="stat-card">
            <span>Numero conectado</span>
            <strong>${escapeHtml(connectedNumber || "-")}</strong>
          </div>
        </div>
      </div>
      <div class="pdv-route-tabs whatsapp-crm-tabs">
        <button class="pdv-route-tab${activeTab === "motor" ? " active" : ""}" type="button" data-whatsapp-crm-tab="motor">Motor</button>
        ${showCampaignTabs ? `<button class="pdv-route-tab${activeTab === "campanhas" ? " active" : ""}" type="button" data-whatsapp-crm-tab="campanhas">Campanhas</button>` : ""}
        ${showCampaignTabs ? `<button class="pdv-route-tab${activeTab === "execucoes" ? " active" : ""}" type="button" data-whatsapp-crm-tab="execucoes">Execucoes</button>` : ""}
        ${showAssistantTab ? `<button class="pdv-route-tab${activeTab === "assistant" ? " active" : ""}" type="button" data-whatsapp-crm-tab="assistant">Assistant / IA</button>` : ""}
      </div>
      ${activeTab === "motor" ? `
        <div class="split-grid">
          <article class="panel whatsapp-crm-panel">
            <div class="panel-header">
              <h3>Status do motor</h3>
            </div>
            <div class="stats-grid whatsapp-crm-status-grid">
              <article class="stat-card whatsapp-crm-status-card is-${escapeHtml(statusMeta.tone)}">
                <span>Status</span>
                <strong>${escapeHtml(statusMeta.label)}</strong>
                <small>${escapeHtml(statusMeta.detail)}</small>
              </article>
              <article class="stat-card whatsapp-crm-status-card">
                <span>Ultima conexao</span>
                <strong>${escapeHtml(formatDateTimeBR(statusData.lastConnectedAt || state.whatsappLastConnectedAt || ""))}</strong>
                <small>${escapeHtml(normalizeText(statusData.profile || statusData.authMode || "-") || "-")}</small>
              </article>
              <article class="stat-card whatsapp-crm-status-card">
                <span>Instancia</span>
                <strong>${escapeHtml(normalizeText(statusData.instanceId || statusData.store?.id || getCurrentPdvStoreId() || "-"))}</strong>
                <small>${escapeHtml(normalizeText(statusData.sessionStateLabel || "") || "Sessao local monitorada pelo CRM.")}</small>
              </article>
              <article class="stat-card whatsapp-crm-status-card">
                <span>Ultimo erro</span>
                <strong>${escapeHtml(normalizeText(statusData.lastError || state.whatsappLastError || "") || "Sem erro recente")}</strong>
                <small>${escapeHtml(normalizeText(statusData.sessionStateLabel || statusData.authMode || "") || "Diagnostico operacional protegido")}</small>
              </article>
            </div>
            <div class="action-row whatsapp-crm-action-row">
              <button class="secondary-button" type="button" data-whatsapp-crm-refresh-status="true"${state.whatsappCrm.loading ? " disabled" : ""}>${state.whatsappCrm.loading ? "Atualizando..." : "Atualizar status"}</button>
              ${showOpenQrButton ? `<button class="ghost-button" type="button" data-whatsapp-crm-open-qr="true"${state.whatsappCrm.qrLoading ? " disabled" : ""}>${state.whatsappCrm.qrLoading ? "Abrindo QR..." : "Abrir QR"}</button>` : ""}
              ${showCloseQrButton ? `<button class="secondary-button" type="button" data-whatsapp-crm-close-qr="true"${state.whatsappCrm.qrLoading ? " disabled" : ""}>${state.whatsappCrm.qrLoading ? "Fechando QR..." : "Fechar QR"}</button>` : ""}
              ${canReconnectWhatsappCrm() ? `<button class="secondary-button" type="button" data-whatsapp-crm-reinitialize="true"${state.whatsappCrm.loading ? " disabled" : ""}>${state.whatsappCrm.loading ? "Reconectando..." : "Reconectar"}</button>` : ""}
              ${canDisconnectWhatsappCrm() ? `<button class="ghost-button" type="button" data-whatsapp-crm-disconnect="true"${state.whatsappCrm.loading ? " disabled" : ""}>${state.whatsappCrm.loading ? "Desconectando..." : "Desconectar"}</button>` : ""}
              ${canResetWhatsappCrm() ? `<button class="danger-button" type="button" data-whatsapp-crm-reset-session="true"${state.whatsappCrm.loading ? " disabled" : ""}>${state.whatsappCrm.loading ? "Limpando..." : "Limpar sessao"}</button>` : ""}
            </div>
            <div class="whatsapp-crm-qr-wrap${hasQr ? " is-visible" : ""}">
              ${hasQr ? `
                <p>Escaneie o QR Code abaixo com o WhatsApp do celular da loja. A janela de conexao so permanece aberta enquanto voce nao clicar em Fechar QR.</p>
                <img class="whatsapp-crm-qr-image" src="${escapeHtml(state.whatsappCrm.qrData?.qrBase64 || "")}" alt="QR Code WhatsApp CRM" />
              ` : `
                <div class="empty-state compact">
                  <strong>${escapeHtml(connectedNumber ? "Motor conectado" : (state.whatsappCrm.qrClosedNotice ? "QR fechado" : (statusData.qrManualMode ? "QR Code protegido" : "QR nao disponivel no momento")))}</strong>
                  <span>${escapeHtml(connectedNumber ? `Motor conectado ao numero ${connectedNumber}.` : (state.whatsappCrm.qrClosedNotice || (statusData.qrManualMode ? "Para conectar, clique em Abrir QR. O sistema nao fica renovando QR sozinho." : "Quando precisar conectar, clique em Abrir QR nesta frente.")))}</span>
                </div>
              `}
            </div>
          </article>
          <article class="panel whatsapp-crm-panel">
            <div class="panel-header">
              <h3>Envio de teste</h3>
            </div>
            ${canSendWhatsappTest() ? `
              <form class="whatsapp-crm-test-form" data-whatsapp-crm-test-form="true">
                <label class="pdv-customers-search-label">
                  Telefone de teste
                  <input name="phone" type="tel" value="${escapeHtml(state.whatsappCrm.testPhone || "")}" placeholder="Ex.: 47999999999" />
                </label>
                <label class="pdv-customers-search-label pdv-customers-wide-field">
                  Mensagem
                  <textarea name="message" placeholder="Mensagem curta para validar o envio operacional">${escapeHtml(state.whatsappCrm.testMessage || "")}</textarea>
                </label>
                <div class="action-row whatsapp-crm-action-row">
                  <button class="primary-button" type="submit"${state.whatsappCrm.testSending ? " disabled" : ""}>${state.whatsappCrm.testSending ? "Enviando..." : "Enviar teste"}</button>
                </div>
              </form>
            ` : `
              <div class="empty-state compact">
                <strong>Teste protegido por permissao</strong>
                <span>Seu perfil pode acompanhar o status operacional, mas nao pode disparar testes pelo motor.</span>
              </div>
            `}
            <div class="pdv-customers-callout">
              <strong>Motor oficial do CRM</strong>
              <span>Esta frente usa o motor real do WhatsApp CRM. Nao depende de wa.me nem de fluxo manual do WhatsApp Web.</span>
            </div>
          </article>
        </div>
        <article class="panel whatsapp-crm-panel">
          <div class="panel-header">
            <h3>Logs recentes do motor</h3>
            <span class="table-meta">${escapeHtml(logsVisible ? "Ultimos envios e tentativas registrados no CRM." : "Seu perfil nao pode consultar logs completos do motor.")}</span>
          </div>
          ${buildWhatsappCrmLogsTable()}
        </article>
      ` : buildWhatsappCrmTabContent()}
    </div>
  `;
}

async function loadWhatsAppLogs() {
  if (!canViewWhatsappLogs()) {
    state.whatsappCrm.logs = [];
    state.whatsappCrm.logsError = "Acesso restrito para o seu perfil.";
    return;
  }
  state.whatsappCrm.logsLoading = true;
  state.whatsappCrm.logsError = "";
  try {
    const response = await api("/api/whatsapp/logs?limit=12");
    state.whatsappCrm.logs = toArray(response.rows);
  } catch (error) {
    state.whatsappCrm.logs = [];
    state.whatsappCrm.logsError = error.message || "Falha ao carregar os logs do WhatsApp CRM.";
  } finally {
    state.whatsappCrm.logsLoading = false;
  }
}

async function loadWhatsAppCrmCampaigns() {
  if (!canViewWhatsappCampaigns()) {
    state.whatsappCrm.campaigns = [];
    state.whatsappCrm.execution = [];
    state.whatsappCrm.operationData = null;
    state.whatsappCrm.campaignsError = "";
    state.whatsappCrm.executionError = "";
    return;
  }
  state.whatsappCrm.campaignsLoading = true;
  state.whatsappCrm.executionLoading = true;
  state.whatsappCrm.campaignsError = "";
  state.whatsappCrm.executionError = "";
  try {
    const [campaigns, executionRows] = await Promise.all([
      api("/api/campaigns"),
      api("/api/campaigns/execution")
    ]);
    state.whatsappCrm.campaigns = getVisibleWhatsappCampaigns(campaigns);
    state.whatsappCrm.execution = getVisibleWhatsappExecutionRows(executionRows);
    if (state.whatsappCrm.selectedCampaignId) {
      const stillExists = state.whatsappCrm.campaigns.find((item) => String(item.id) === String(state.whatsappCrm.selectedCampaignId));
      if (!stillExists) {
        state.whatsappCrm.selectedCampaignId = "";
        state.whatsappCrm.operationData = null;
      }
    }
    if (!state.whatsappCrm.selectedCampaignId && state.whatsappCrm.campaigns.length) {
      const preferred = state.whatsappCrm.campaigns.find((item) => Number(item.active || 0) === 1) || state.whatsappCrm.campaigns[0];
      state.whatsappCrm.selectedCampaignId = String(preferred?.id || "");
    }
  } catch (error) {
    state.whatsappCrm.campaigns = [];
    state.whatsappCrm.execution = [];
    state.whatsappCrm.campaignsError = error.message || "Falha ao carregar campanhas.";
    state.whatsappCrm.executionError = error.message || "Falha ao carregar execucoes.";
  } finally {
    state.whatsappCrm.campaignsLoading = false;
    state.whatsappCrm.executionLoading = false;
  }
}

async function loadWhatsAppCrmCampaignOperation(campaignId) {
  if (!canViewWhatsappCampaigns()) {
    return;
  }
  const normalizedId = String(campaignId || "").trim();
  if (!normalizedId) {
    state.whatsappCrm.selectedCampaignId = "";
    state.whatsappCrm.operationData = null;
    state.whatsappCrm.operationError = "";
    renderWhatsAppRouteFront();
    return;
  }
  state.whatsappCrm.selectedCampaignId = normalizedId;
  const selectedCampaign = getVisibleWhatsappCampaigns(state.whatsappCrm.campaigns).find((item) => String(item.id) === normalizedId);
  if (selectedCampaign) {
    const selectedFilters = selectedCampaign.filters && typeof selectedCampaign.filters === "object" ? selectedCampaign.filters : {};
    state.whatsappCrm.campaignDraft = {
      ...getDefaultWhatsappCrmCampaignDraft(),
      id: String(selectedCampaign.id || ""),
      name: selectedCampaign.name || "",
      store: normalizeText(selectedCampaign.store || "").toLowerCase(),
      sendType: normalizeText(selectedCampaign.send_type || "text"),
      message: selectedCampaign.template || "",
      caption: selectedCampaign.caption || "",
      messageMode: normalizeText(selectedFilters._composerSource || "manual").toLowerCase() || "manual",
      templateSource: normalizeText(selectedFilters._templateSource || "literal").toLowerCase() || "literal",
      audienceScope: normalizeText(selectedFilters._audienceScope || (toArray(selectedCampaign.selectedContactIds).length ? "manual_selection" : "none")).toLowerCase() || "none",
      selectedContactIds: toArray(selectedCampaign.selectedContactIds).map((item) => Number(item)).filter(Boolean),
      filters: selectedFilters,
      mediaId: selectedCampaign.media_id || null,
      mediaName: "",
      mediaPreviewUrl: selectedCampaign.preview_url || "",
      mediaPreviewType: normalizeText(selectedCampaign.send_type || "").includes("video") ? "video" : "image",
      mediaChanged: false
    };
    state.whatsappCrm.campaignAudienceSelectedContacts = [];
  }
  state.whatsappCrm.operationLoading = true;
  state.whatsappCrm.operationError = "";
  renderWhatsAppRouteFront();
  try {
    const payload = await api(`/api/campaigns/${encodeURIComponent(normalizedId)}/operation`);
    state.whatsappCrm.operationData = payload;
    state.whatsappCrm.campaignAudienceSelectedContacts = toArray(payload?.contacts).map((item) => ({
      id: Number(item.contact_id || item.id || 0),
      name: item.name || item.customer_name || "Cliente sem nome",
      phone: item.phone || item.customer_phone || "",
      store: normalizeText(item.store || item.loja || state.whatsappCrm.campaignDraft.store || "").toLowerCase(),
      seller_name: item.seller_name || item.seller || "",
      status: item.status || item.execution_status || ""
    })).filter((item) => item.id > 0);
    if (payload?.media?.id && String(payload.media.id) === String(state.whatsappCrm.campaignDraft.mediaId || "")) {
      const mediaType = normalizeText(payload.media.media_type || "").toLowerCase() || "image";
      state.whatsappCrm.campaignDraft = {
        ...state.whatsappCrm.campaignDraft,
        mediaName: payload.media.original_name || state.whatsappCrm.campaignDraft.mediaName || "",
        mediaPreviewType: mediaType === "video" ? "video" : "image",
        mediaPreviewUrl: mediaType === "image"
          ? `/api/uploads/media/${payload.media.id}/preview`
          : `/api/uploads/media/${payload.media.id}/file`
      };
    }
  } catch (error) {
    state.whatsappCrm.operationData = null;
    state.whatsappCrm.operationError = error.message || "Falha ao carregar a operacao da campanha.";
  } finally {
    state.whatsappCrm.operationLoading = false;
    renderWhatsAppRouteFront();
  }
  loadWhatsAppCrmCampaignAudienceEstimate({ render: true }).catch(() => {});
}

function syncWhatsappCrmAssistantDraftFromForm(formLike) {
  ensureWhatsappCrmAssistantDraft();
  const formData = new FormData(formLike);
  const nextStore = canViewAllStores()
    ? normalizeText(formData.get("assistantStore") || "").toLowerCase()
    : normalizeText(getCurrentPdvStoreId() || "").toLowerCase();
  state.whatsappCrm.assistantDraft = {
    ...state.whatsappCrm.assistantDraft,
    campaignId: normalizeText(formData.get("assistantCampaignId") || "").trim(),
    tag: normalizeText(formData.get("assistantTag") || "").trim(),
    status: normalizeText(formData.get("assistantStatus") || "").trim(),
    gender: normalizeText(formData.get("assistantGender") || "").trim(),
    store: nextStore,
    sellerId: normalizeText(formData.get("assistantSellerId") || "").trim(),
    cashbackActive: normalizeText(formData.get("assistantCashbackActive") || "").trim(),
    base: String(formData.get("assistantBase") || "").trim(),
    style: normalizeText(formData.get("assistantStyle") || "elegante").toLowerCase() || "elegante"
  };
  if (!canViewAllStores()) {
    state.whatsappCrm.assistantDraft.store = normalizeText(getCurrentPdvStoreId() || "").toLowerCase();
  }
}

async function loadWhatsAppCrmAssistantPreview(options = {}) {
  if (state.whatsappCrm.assistantLoading) {
    return;
  }
  const { resetOffset = false, advance = false } = options;
  ensureWhatsappCrmAssistantDraft();
  if (resetOffset) {
    state.whatsappCrm.assistantDraft.offset = 0;
  } else if (advance) {
    state.whatsappCrm.assistantDraft.offset = Math.max(0, Number(state.whatsappCrm.assistantDraft.offset || 0) + 1);
  }
  const query = new URLSearchParams();
  const draft = state.whatsappCrm.assistantDraft;
  [
    ["campaignId", draft.campaignId],
    ["tag", draft.tag],
    ["status", draft.status],
    ["gender", draft.gender],
    ["store", draft.store],
    ["sellerId", draft.sellerId],
    ["cashbackActive", draft.cashbackActive]
  ].forEach(([key, value]) => {
    if (normalizeText(value || "").trim()) {
      query.set(key, normalizeText(value || "").trim());
    }
  });
  query.set("offset", String(Math.max(0, Number(draft.offset || 0))));
  state.whatsappCrm.assistantLoading = true;
  state.whatsappCrm.assistantError = "";
  renderWhatsAppRouteFront();
  try {
    const payload = await api(`/api/assistant/next?${query.toString()}`);
    state.whatsappCrm.assistantPreview = payload;
    state.whatsappCrm.assistantDraft.offset = Math.max(0, Number(draft.offset || 0));
    if (payload?.campaign?.id) {
      state.whatsappCrm.assistantDraft.campaignId = String(payload.campaign.id);
      if (!state.whatsappCrm.selectedCampaignId) {
        state.whatsappCrm.selectedCampaignId = String(payload.campaign.id);
      }
    }
    showFeedback("Preview do assistant preparado dentro do WhatsApp CRM.");
  } catch (error) {
    if (advance) {
      state.whatsappCrm.assistantDraft.offset = Math.max(0, Number(state.whatsappCrm.assistantDraft.offset || 1) - 1);
    }
    state.whatsappCrm.assistantPreview = null;
    state.whatsappCrm.assistantError = error.message || "Falha ao preparar o preview do assistant.";
  } finally {
    state.whatsappCrm.assistantLoading = false;
    renderWhatsAppRouteFront();
  }
}

async function generateWhatsAppCrmAssistantVariation(formElement) {
  if (state.whatsappCrm.assistantGenerating) {
    return;
  }
  syncWhatsappCrmAssistantDraftFromForm(formElement);
  ensureWhatsappCrmAssistantDraft();
  if (!String(state.whatsappCrm.assistantDraft.base || "").trim()) {
    showFeedback("Escreva uma mensagem base antes de gerar a variacao da IA.", "error");
    return;
  }
  state.whatsappCrm.assistantGenerating = true;
  state.whatsappCrm.assistantError = "";
  renderWhatsAppRouteFront();
  try {
    const result = await api("/api/ai/variation", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        base: state.whatsappCrm.assistantDraft.base,
        style: state.whatsappCrm.assistantDraft.style
      })
    });
    state.whatsappCrm.assistantDraft.result = String(result?.variation || "").trim();
    state.whatsappCrm.assistantDraft.source = "ai_variation";
    showFeedback("Preview do assistant gerado com a IA.");
  } catch (error) {
    state.whatsappCrm.assistantError = error.message || "Falha ao gerar a variacao da IA.";
  } finally {
    state.whatsappCrm.assistantGenerating = false;
    renderWhatsAppRouteFront();
  }
}

async function copyWhatsAppCrmAssistantText(mode = "result") {
  ensureWhatsappCrmAssistantDraft();
  const text = mode === "preview"
    ? String(state.whatsappCrm.assistantPreview?.message || "").trim()
    : String(state.whatsappCrm.assistantDraft.result || state.whatsappCrm.assistantDraft.base || "").trim();
  if (!text) {
    showFeedback("Nao ha texto preparado para copiar no assistant.", "error");
    return;
  }
  await navigator.clipboard.writeText(text);
  showFeedback("Preview do assistant copiado.");
}

function applyWhatsAppCrmAssistantToCampaign(mode = "result") {
  ensureWhatsappCrmAssistantDraft();
  ensureWhatsappCrmCampaignDraft();
  const text = mode === "preview"
    ? String(state.whatsappCrm.assistantPreview?.message || "").trim()
    : String(state.whatsappCrm.assistantDraft.result || state.whatsappCrm.assistantDraft.base || "").trim();
  if (!text) {
    showFeedback("Nao ha preview do assistant para aplicar na campanha.", "error");
    return;
  }
  const campaignId = normalizeText(
    state.whatsappCrm.assistantDraft.campaignId
    || state.whatsappCrm.assistantPreview?.campaign?.id
    || state.whatsappCrm.selectedCampaignId
    || ""
  ).trim();
  const selectedCampaign = getVisibleWhatsappCampaigns(state.whatsappCrm.campaigns).find((item) => String(item.id) === String(campaignId));
  state.whatsappCrm.selectedCampaignId = campaignId || state.whatsappCrm.selectedCampaignId;
  state.whatsappCrm.campaignDraft = {
    ...state.whatsappCrm.campaignDraft,
    id: campaignId || state.whatsappCrm.campaignDraft.id,
    name: state.whatsappCrm.campaignDraft.name || selectedCampaign?.name || "",
    store: normalizeText(
      state.whatsappCrm.campaignDraft.store
      || selectedCampaign?.store
      || state.whatsappCrm.assistantDraft.store
      || getCurrentPdvStoreId()
      || ""
    ).toLowerCase(),
    message: text,
    messageMode: "ai",
    templateSource: mode === "preview" ? "assistant_preview" : state.whatsappCrm.assistantDraft.source || "literal"
  };
  state.whatsappCrm.activeTab = "campanhas";
  renderWhatsAppRouteFront();
  showFeedback("Preview do assistant aplicado no rascunho da campanha.");
}

function syncWhatsAppCrmCampaignDraftFromForm(formElement) {
  if (!formElement) {
    return;
  }
  ensureWhatsappCrmCampaignDraft();
  const formData = new FormData(formElement);
  state.whatsappCrm.campaignDraft = {
    ...state.whatsappCrm.campaignDraft,
    id: String(formData.get("campaignId") || "").trim(),
    name: String(formData.get("campaignName") || "").trim(),
    store: normalizeText(formData.get("campaignStore") || "").toLowerCase(),
    sendType: normalizeText(formData.get("campaignSendType") || "text"),
    messageMode: normalizeText(formData.get("campaignMessageMode") || "manual").toLowerCase() || "manual",
    audienceScope: normalizeText(formData.get("campaignAudienceScope") || "none").toLowerCase() || "none",
    message: String(formData.get("campaignMessage") || "").trim(),
    caption: String(formData.get("campaignCaption") || "").trim(),
    filters: {
      ...(state.whatsappCrm.campaignDraft.filters && typeof state.whatsappCrm.campaignDraft.filters === "object" ? state.whatsappCrm.campaignDraft.filters : {}),
      gender: normalizeText(formData.get("campaignAudienceGender") || "").toLowerCase(),
      sellerId: normalizeText(formData.get("campaignAudienceSellerId") || "").trim(),
      topSize: normalizeText(formData.get("campaignAudienceTopSize") || "").trim(),
      bottomSize: normalizeText(formData.get("campaignAudienceBottomSize") || "").trim(),
      shoeSize: normalizeText(formData.get("campaignAudienceShoeSize") || "").trim(),
      hasWhatsapp: normalizeText(formData.get("campaignAudienceHasWhatsapp") || "").trim() || (normalizeText(formData.get("campaignAudienceScope") || "").toLowerCase() === "store_whatsapp_valid" ? "1" : "")
    }
  };
}

async function loadWhatsAppCrmCampaignAudienceEstimate(options = {}) {
  ensureWhatsappCrmCampaignDraft();
  const { render = false } = options;
  const draft = state.whatsappCrm.campaignDraft;
  const scope = normalizeText(draft.audienceScope || "none").toLowerCase() || "none";
  const selectedContactIds = toArray(draft.selectedContactIds).map((item) => Number(item)).filter(Boolean);
  const selectedContacts = getWhatsappCrmCampaignSelectedContacts();
  if (scope === "none") {
    state.whatsappCrm.campaignAudienceEstimate = {
      scope,
      store: normalizeText(draft.store || "").toLowerCase(),
      estimatedCount: 0,
      linkedCount: selectedContactIds.length,
      validWhatsappCount: 0,
      invalidWhatsappCount: 0,
      blockedCount: 0
    };
    state.whatsappCrm.campaignAudienceError = "";
    if (render) {
      renderWhatsAppRouteFront();
    }
    return state.whatsappCrm.campaignAudienceEstimate;
  }
  if (scope === "campaign_contacts" || scope === "manual_selection") {
    const validWhatsappCount = selectedContacts.filter((item) => normalizePhone(item.phone || "")).length;
    state.whatsappCrm.campaignAudienceEstimate = {
      scope,
      store: normalizeText(draft.store || "").toLowerCase(),
      estimatedCount: selectedContactIds.length,
      linkedCount: selectedContactIds.length,
      validWhatsappCount,
      invalidWhatsappCount: Math.max(selectedContactIds.length - validWhatsappCount, 0),
      blockedCount: 0
    };
    state.whatsappCrm.campaignAudienceError = "";
    if (render) {
      renderWhatsAppRouteFront();
    }
    return state.whatsappCrm.campaignAudienceEstimate;
  }
  if (!draft.store) {
    state.whatsappCrm.campaignAudienceEstimate = {
      scope,
      store: "",
      estimatedCount: 0,
      linkedCount: selectedContactIds.length,
      validWhatsappCount: 0,
      invalidWhatsappCount: 0,
      blockedCount: 0
    };
    state.whatsappCrm.campaignAudienceError = "Selecione uma loja para validar o publico.";
    if (render) {
      renderWhatsAppRouteFront();
    }
    return state.whatsappCrm.campaignAudienceEstimate;
  }
  state.whatsappCrm.campaignAudienceLoading = true;
  state.whatsappCrm.campaignAudienceError = "";
  if (render) {
    renderWhatsAppRouteFront();
  }
  try {
    const query = new URLSearchParams({
      store: draft.store,
      scope
    });
    const filters = getWhatsappCrmCampaignFilterDraft();
    if (filters.gender) query.set("gender", filters.gender);
    if (filters.sellerId) query.set("sellerId", filters.sellerId);
    if (filters.topSize) query.set("topSize", filters.topSize);
    if (filters.bottomSize) query.set("bottomSize", filters.bottomSize);
    if (filters.shoeSize) query.set("shoeSize", filters.shoeSize);
    if (filters.hasWhatsapp) query.set("hasWhatsapp", filters.hasWhatsapp);
    if (draft.id) {
      query.set("campaignId", String(draft.id));
    }
    const payload = await api(`/api/campaigns/audience-estimate?${query.toString()}`);
    state.whatsappCrm.campaignAudienceEstimate = {
      scope,
      store: normalizeText(payload.store || draft.store || "").toLowerCase(),
      estimatedCount: Number(payload.estimatedCount || 0),
      linkedCount: Number(payload.linkedCount || selectedContactIds.length || 0),
      validWhatsappCount: Number(payload.validWhatsappCount || 0),
      invalidWhatsappCount: Number(payload.invalidWhatsappCount || 0),
      blockedCount: Number(payload.blockedCount || 0)
    };
    return state.whatsappCrm.campaignAudienceEstimate;
  } catch (error) {
    state.whatsappCrm.campaignAudienceEstimate = {
      scope,
      store: normalizeText(draft.store || "").toLowerCase(),
      estimatedCount: 0,
      linkedCount: selectedContactIds.length,
      validWhatsappCount: 0,
      invalidWhatsappCount: 0,
      blockedCount: 0
    };
    state.whatsappCrm.campaignAudienceError = error.message || "Falha ao validar o publico da campanha.";
    throw error;
  } finally {
    state.whatsappCrm.campaignAudienceLoading = false;
    if (render) {
      renderWhatsAppRouteFront();
    }
  }
}

async function refreshWhatsAppCrmCampaignMediaPreview(file) {
  ensureWhatsappCrmCampaignDraft();
  if (!file) {
    state.whatsappCrm.campaignDraft = {
      ...state.whatsappCrm.campaignDraft,
      mediaName: "",
      mediaPreviewUrl: "",
      mediaPreviewType: "",
      mediaChanged: false
    };
    renderWhatsAppRouteFront();
    return;
  }
  const previewUrl = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Nao foi possivel gerar o preview da midia."));
    reader.readAsDataURL(file);
  });
  state.whatsappCrm.campaignDraft = {
    ...state.whatsappCrm.campaignDraft,
    mediaName: file.name || "midia",
    mediaPreviewUrl: previewUrl,
    mediaPreviewType: String(file.type || "").startsWith("video/") ? "video" : "image",
    mediaChanged: true
  };
  renderWhatsAppRouteFront();
}

async function uploadWhatsAppCrmCampaignMedia(file) {
  const formData = new FormData();
  formData.append("media", file);
  const response = await fetch("/api/uploads/media", {
    method: "POST",
    body: formData,
    credentials: "include"
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(payload.details || payload.error || "Falha ao fazer upload da midia da campanha.");
  }
  return payload;
}

async function saveWhatsAppCrmCampaignDraft(formElement) {
  if (state.whatsappCrm.campaignSaving) {
    return;
  }
  if (!canManageWhatsappCampaigns()) {
    throw new Error("Seu perfil nao pode salvar campanhas nesta frente.");
  }
  syncWhatsAppCrmCampaignDraftFromForm(formElement);
  ensureWhatsappCrmCampaignDraft();
  const draft = state.whatsappCrm.campaignDraft;
  if (!draft.name) {
    throw new Error("Informe o nome da campanha.");
  }
  if (!draft.message) {
    throw new Error("Informe a mensagem da campanha.");
  }
  if (!draft.store) {
    throw new Error("Informe a loja da campanha.");
  }

  state.whatsappCrm.campaignSaving = true;
  state.whatsappCrm.campaignSaveStep = "saving_draft";
  renderWhatsAppRouteFront();
  try {
    let mediaId = draft.mediaId || null;
    const mediaInput = formElement.querySelector('[name="campaignMedia"]');
    const mediaFile = mediaInput?.files?.[0] || null;
    if (draft.sendType !== "text") {
      if (mediaFile) {
        state.whatsappCrm.campaignSaveStep = "uploading_media";
        renderWhatsAppRouteFront();
        const uploadResult = await uploadWhatsAppCrmCampaignMedia(mediaFile);
        mediaId = Number(uploadResult.mediaId || 0) || null;
      } else if (!mediaId) {
        throw new Error("Selecione uma midia antes de salvar uma campanha com imagem ou video.");
      }
    } else {
      mediaId = null;
    }

    const method = draft.id ? "PUT" : "POST";
    const path = draft.id ? `/api/campaigns/${encodeURIComponent(draft.id)}` : "/api/campaigns";
    const payload = await api(path, {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: draft.name,
        store: draft.store,
        template: draft.message,
        filters: {
          ...(draft.filters && typeof draft.filters === "object" ? draft.filters : {}),
          _composerSource: draft.messageMode || "manual",
          _templateSource: draft.templateSource || "literal",
          _audienceScope: draft.audienceScope || "none",
          _audienceEstimate: Number(state.whatsappCrm.campaignAudienceEstimate?.estimatedCount || 0)
        },
        selectedContactIds: toArray(draft.selectedContactIds).map((item) => Number(item)).filter(Boolean),
        sendType: draft.sendType,
        mediaId,
        caption: draft.caption || "",
        sellerId: "__all__"
      })
    });
    state.whatsappCrm.selectedCampaignId = String(payload.id || "");
    state.whatsappCrm.campaignDraft = {
      ...getDefaultWhatsappCrmCampaignDraft(),
      id: String(payload.id || ""),
      name: payload.name || draft.name,
      store: normalizeText(payload.store || draft.store || "").toLowerCase(),
      sendType: normalizeText(payload.send_type || draft.sendType || "text"),
      message: payload.template || draft.message,
      caption: payload.caption || draft.caption || "",
      messageMode: draft.messageMode || "manual",
      templateSource: draft.templateSource || "literal",
      audienceScope: draft.audienceScope || "none",
      selectedContactIds: toArray(payload.selectedContactIds || draft.selectedContactIds).map((item) => Number(item)).filter(Boolean),
      filters: payload.filters && typeof payload.filters === "object" ? payload.filters : (draft.filters || {}),
      mediaId: payload.media_id || mediaId || null,
      mediaName: draft.mediaName || "",
      mediaPreviewUrl: payload.preview_url || draft.mediaPreviewUrl || "",
      mediaPreviewType: draft.mediaPreviewType || "",
      mediaChanged: false
    };
    showFeedback(draft.id ? "Rascunho da campanha atualizado no WhatsApp CRM." : "Rascunho da campanha salvo no WhatsApp CRM.");
    await loadWhatsAppCrmCampaigns();
    if (state.whatsappCrm.selectedCampaignId) {
      await loadWhatsAppCrmCampaignOperation(state.whatsappCrm.selectedCampaignId);
    }
  } finally {
    state.whatsappCrm.campaignSaving = false;
    state.whatsappCrm.campaignSaveStep = "";
    renderWhatsAppRouteFront();
  }
}

function isWhatsappCrmQrWindowActive() {
  const statusData = state.whatsappCrm.statusData || {};
  return Boolean(state.whatsappCrm.qrWindowOpen || statusData.qrRequestActive);
}

function stopWhatsAppCrmQrPolling() {
  if (whatsappCrmQrPollingInterval) {
    clearInterval(whatsappCrmQrPollingInterval);
    whatsappCrmQrPollingInterval = null;
  }
}

async function pollWhatsAppCrmQrWindow() {
  if (!isWhatsappCrmQrWindowActive()) {
    stopWhatsAppCrmQrPolling();
    return;
  }
  try {
    const statusResponse = await api("/api/whatsapp/status");
    state.whatsappCrm.statusData = statusResponse;
    state.whatsappStatus = statusResponse.status;
    state.whatsappConnectedNumber = statusResponse.connectedNumber;
    state.whatsappLastConnectedAt = statusResponse.lastConnectedAt;
    state.whatsappLastError = statusResponse.lastError;
    state.whatsappHasQr = statusResponse.hasQr;

    if (statusResponse.status === "conectado") {
      state.whatsappCrm.qrWindowOpen = false;
      state.whatsappCrm.qrData = null;
      state.whatsappCrm.qrClosedNotice = "";
      stopWhatsAppCrmQrPolling();
      renderWhatsAppRouteFront();
      return;
    }

    if (!statusResponse.qrRequestActive) {
      state.whatsappCrm.qrWindowOpen = false;
      state.whatsappCrm.qrData = null;
      stopWhatsAppCrmQrPolling();
      renderWhatsAppRouteFront();
      return;
    }

    const qrResponse = await api("/api/whatsapp/qr");
    state.whatsappCrm.qrData = qrResponse;
    renderWhatsAppRouteFront();
  } catch (error) {
    if (String(error.message || "").trim()) {
      state.whatsappCrm.error = error.message;
    }
  }
}

function startWhatsAppCrmQrPolling() {
  stopWhatsAppCrmQrPolling();
  pollWhatsAppCrmQrWindow().catch(() => {});
  whatsappCrmQrPollingInterval = setInterval(() => {
    pollWhatsAppCrmQrWindow().catch(() => {});
  }, 2500);
}

async function openWhatsAppCrmQr() {
  if (!canReconnectWhatsappCrm() || state.whatsappCrm.qrLoading) {
    return;
  }
  state.whatsappCrm.qrWindowOpen = true;
  state.whatsappCrm.qrClosedNotice = "";
  state.whatsappCrm.error = "";
  state.whatsappCrm.qrLoading = true;
  renderWhatsAppRouteFront();
  try {
    await api("/api/whatsapp/qr/refresh", { method: "POST" });
    startWhatsAppCrmQrPolling();
  } catch (error) {
    state.whatsappCrm.qrWindowOpen = false;
    state.whatsappCrm.qrData = null;
    stopWhatsAppCrmQrPolling();
    if (String(error.message || "").trim()) {
      state.whatsappCrm.error = error.message;
    }
    throw error;
  } finally {
    state.whatsappCrm.qrLoading = false;
    renderWhatsAppRouteFront();
  }
}

async function closeWhatsAppCrmQr() {
  if (state.whatsappCrm.qrLoading) {
    return;
  }
  stopWhatsAppCrmQrPolling();
  state.whatsappCrm.qrLoading = true;
  renderWhatsAppRouteFront();
  try {
    await api("/api/whatsapp/qr/close", { method: "POST" });
    state.whatsappCrm.qrWindowOpen = false;
    state.whatsappCrm.qrData = null;
    state.whatsappCrm.qrClosedNotice = "QR fechado. Clique em Abrir QR quando quiser conectar.";
    const response = await api("/api/whatsapp/status");
    state.whatsappStatus = response.status;
    state.whatsappConnectedNumber = response.connectedNumber;
    state.whatsappLastConnectedAt = response.lastConnectedAt;
    state.whatsappLastError = response.lastError;
    state.whatsappHasQr = response.hasQr;
    state.whatsappCrm.statusData = response;
  } catch (error) {
    if (String(error.message || "").trim()) {
      state.whatsappCrm.error = error.message;
    }
    throw error;
  } finally {
    state.whatsappCrm.qrLoading = false;
    renderWhatsAppRouteFront();
  }
}

async function loadWhatsAppQrData(options = {}) {
  const { requestFresh = false } = options || {};
  if (!canReconnectWhatsappCrm()) {
    state.whatsappCrm.qrData = null;
    return null;
  }
  if (!requestFresh && !isWhatsappCrmQrWindowActive()) {
    state.whatsappCrm.qrData = null;
    return null;
  }
  state.whatsappCrm.qrLoading = true;
  try {
    if (requestFresh) {
      state.whatsappCrm.qrWindowOpen = true;
      state.whatsappCrm.qrClosedNotice = "";
      await api("/api/whatsapp/qr/refresh", { method: "POST" });
      startWhatsAppCrmQrPolling();
    }
    const response = await api("/api/whatsapp/qr");
    state.whatsappCrm.qrData = response;
    return response;
  } catch (error) {
    state.whatsappCrm.qrData = null;
    if (String(error.message || "").trim()) {
      state.whatsappCrm.error = error.message;
    }
    return null;
  } finally {
    state.whatsappCrm.qrLoading = false;
  }
}

async function loadWhatsAppCrmFront(options = {}) {
  const { refreshQr = false, refreshLogs = true, refreshCampaigns = true } = options;
  state.whatsappCrm.loading = true;
  state.whatsappCrm.error = "";
  renderWhatsAppRouteFront();
  try {
    const response = await api("/api/whatsapp/status");
    state.whatsappStatus = response.status;
    state.whatsappConnectedNumber = response.connectedNumber;
    state.whatsappLastConnectedAt = response.lastConnectedAt;
    state.whatsappLastError = response.lastError;
    state.whatsappHasQr = response.hasQr;
    state.whatsappCrm.statusData = response;
    updateWhatsAppUI(response);
    if (response.status === "conectado") {
      state.whatsappCrm.qrWindowOpen = false;
      state.whatsappCrm.qrData = null;
      state.whatsappCrm.qrClosedNotice = "";
      stopWhatsAppCrmQrPolling();
    } else if (refreshQr && isWhatsappCrmQrWindowActive() && (response.hasQr || response.status === "aguardando_qr" || response.status === "aguardando qr")) {
      await loadWhatsAppQrData();
    } else if (!isWhatsappCrmQrWindowActive()) {
      state.whatsappCrm.qrData = null;
    }
    if (refreshLogs) {
      await loadWhatsAppLogs();
    }
    if (refreshCampaigns) {
      await Promise.all([
        loadWhatsAppCrmCampaigns(),
        !state.aiTemplates.length ? loadAiTemplates().catch(() => {}) : Promise.resolve()
      ]);
      if (state.whatsappCrm.selectedCampaignId) {
        await loadWhatsAppCrmCampaignOperation(state.whatsappCrm.selectedCampaignId);
      }
    }
  } catch (error) {
    state.whatsappCrm.statusData = null;
    state.whatsappCrm.error = error.message || "Falha ao consultar o motor do WhatsApp CRM.";
  } finally {
    state.whatsappCrm.loading = false;
    renderWhatsAppRouteFront();
  }
}

async function reinitializeWhatsApp() {
  if (state.whatsappCrm.loading) {
    return;
  }
  state.whatsappCrm.loading = true;
  renderWhatsAppRouteFront();
  try {
    const response = await api("/api/whatsapp/reinitialize", { method: "POST" });
    showFeedback(response.message || "Reconexao do WhatsApp CRM iniciada.");
    await loadWhatsAppCrmFront({ refreshQr: false, refreshLogs: true });
  } finally {
    state.whatsappCrm.loading = false;
    renderWhatsAppRouteFront();
  }
}

async function disconnectWhatsApp() {
  if (state.whatsappCrm.loading) {
    return;
  }
  stopWhatsAppCrmQrPolling();
  state.whatsappCrm.qrWindowOpen = false;
  state.whatsappCrm.qrData = null;
  state.whatsappCrm.qrClosedNotice = "";
  state.whatsappCrm.loading = true;
  renderWhatsAppRouteFront();
  try {
    const response = await api("/api/whatsapp/disconnect", { method: "POST" });
    showFeedback(response.message || "WhatsApp CRM desconectado.");
    await loadWhatsAppCrmFront({ refreshQr: false, refreshLogs: true });
  } finally {
    state.whatsappCrm.loading = false;
    renderWhatsAppRouteFront();
  }
}

async function sendWhatsAppCrmTest(formElement) {
  if (state.whatsappCrm.testSending) {
    return;
  }
  const formData = new FormData(formElement);
  state.whatsappCrm.testPhone = normalizeText(formData.get("phone") || "");
  state.whatsappCrm.testMessage = normalizeText(formData.get("message") || "");
  state.whatsappCrm.testSending = true;
  renderWhatsAppRouteFront();
  try {
    const response = await api("/api/whatsapp/test-send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        phone: state.whatsappCrm.testPhone,
        message: state.whatsappCrm.testMessage
      })
    });
    showFeedback(response.message || "Mensagem de teste enviada pelo WhatsApp CRM.");
    await loadWhatsAppCrmFront({ refreshQr: false, refreshLogs: true });
  } finally {
    state.whatsappCrm.testSending = false;
    renderWhatsAppRouteFront();
  }
}

function getUsersAdminMeta() {
  const meta = state.usersAdmin.meta || {};
  return {
    profiles: toArray(meta.profiles).length ? toArray(meta.profiles) : [
      { key: "admin", label: "Administrador" },
      { key: "manager", label: "Gestor" },
      { key: "seller", label: "Vendedor" },
      { key: "cashier", label: "Caixa" },
      { key: "consult", label: "Consulta" }
    ],
    permission_catalog: toArray(meta.permission_catalog),
    store_options: toArray(meta.store_options).length ? toArray(meta.store_options) : [
      { id: "vila", label: "Vila" },
      { id: "botanico", label: "Botânico" },
      { id: "sul", label: "Sul" }
    ]
  };
}

function getUsersAdminSelectedUser() {
  const selectedId = Number(state.usersAdmin.selectedId || 0);
  return toArray(state.usersAdmin.rows).find((user) => Number(user.id) === selectedId) || null;
}

function createUsersAdminDraft(user = null) {
  const meta = getUsersAdminMeta();
  const role = user?.role || "seller";
  const profile = meta.profiles.find((item) => item.key === role) || null;
  const storeId = normalizePdvStoreIdentifier(user?.store_id || meta.store_options?.[0]?.id || "vila") || "vila";
  return {
    id: user?.id || "",
    name: user?.name || "",
    email: user?.email || "",
    username: user?.username || "",
    phone: user?.phone || "",
    role,
    status: user?.status || "ativo",
    store_id: storeId,
    allowed_stores: toArray(user?.allowed_stores).length ? toArray(user.allowed_stores) : [storeId],
    permissions: user?.permissions || profile?.default_permissions || {},
    password: ""
  };
}

async function loadUsersAdmin() {
  if (!canManageUsersPanel()) {
    return;
  }
  state.usersAdmin.loading = true;
  state.usersAdmin.error = "";
  renderUsersAdminFront();
  try {
    const params = new URLSearchParams();
    if (state.usersAdmin.query) params.set("q", state.usersAdmin.query);
    if (state.usersAdmin.status) params.set("status", state.usersAdmin.status);
    const response = await api(`/api/admin/users${params.toString() ? `?${params.toString()}` : ""}`);
    state.usersAdmin.rows = toArray(response.users);
    state.usersAdmin.meta = response.meta || state.usersAdmin.meta;
    if (state.usersAdmin.selectedId && !getUsersAdminSelectedUser()) {
      state.usersAdmin.selectedId = "";
      state.usersAdmin.draft = null;
    }
  } catch (error) {
    state.usersAdmin.error = error.message || "Falha ao carregar usuarios.";
    throw error;
  } finally {
    state.usersAdmin.loading = false;
    renderUsersAdminFront();
  }
}

function renderUsersAdminFront() {
  const container = document.getElementById("users-admin-content");
  if (!container) {
    return;
  }
  if (!canManageUsersPanel()) {
    container.innerHTML = `
      <article class="hero-card">
        <p class="eyebrow">Acesso restrito</p>
        <h3>Usuários e Permissões</h3>
        <p>Somente administrador ou perfil com permissão pode gerenciar acessos.</p>
      </article>
    `;
    return;
  }
  const meta = getUsersAdminMeta();
  const users = toArray(state.usersAdmin.rows).filter((user) => !state.usersAdmin.role || user.role === state.usersAdmin.role);
  const selected = getUsersAdminSelectedUser();
  const draft = state.usersAdmin.draft || createUsersAdminDraft(selected);
  const activeCount = users.filter((user) => String(user.status || "") === "ativo").length;
  const profileOptions = meta.profiles.map((profile) => `<option value="${escapeHtml(profile.key)}"${profile.key === draft.role ? " selected" : ""}>${escapeHtml(profile.label)}</option>`).join("");
  const filterProfileOptions = meta.profiles.map((profile) => `<option value="${escapeHtml(profile.key)}"${profile.key === state.usersAdmin.role ? " selected" : ""}>${escapeHtml(profile.label)}</option>`).join("");
  const storeOptions = meta.store_options.map((store) => `<option value="${escapeHtml(store.id)}"${store.id === draft.store_id ? " selected" : ""}>${escapeHtml(store.label)}</option>`).join("");
  const allowedStores = meta.store_options.map((store) => `
    <label class="users-admin-check"><input type="checkbox" name="allowed_stores" value="${escapeHtml(store.id)}"${toArray(draft.allowed_stores).includes(store.id) ? " checked" : ""} /><span>${escapeHtml(store.label)}</span></label>
  `).join("");
  const permissionCatalog = meta.permission_catalog.map((group) => {
    const items = toArray(group.items);
    const activePermissions = items.filter((permission) => draft.permissions?.[permission.key]).length;
    return `
    <section class="users-admin-permission-group">
      <div class="users-admin-permission-head">
        <h4>${escapeHtml(group.group || "Permissões")}</h4>
        <span>${escapeHtml(String(activePermissions))} de ${escapeHtml(String(items.length))} ativas</span>
      </div>
      <div class="users-admin-permissions">
        ${items.map((permission) => `
          <label class="users-admin-check"><input type="checkbox" name="permissions" value="${escapeHtml(permission.key)}"${draft.permissions?.[permission.key] ? " checked" : ""} /><span>${escapeHtml(permission.label || permission.key)}</span></label>
        `).join("")}
      </div>
    </section>
  `;
  }).join("");
  container.innerHTML = `
    <section class="users-admin-shell">
      <div class="users-admin-hero">
        <div>
          <p class="eyebrow">ACESSOS AEROSTORE</p>
          <h3>Usuários e Permissões</h3>
          <p>Gerencie quem acessa o CRM/PDV, lojas permitidas e permissões por módulo.</p>
        </div>
        <div class="users-admin-kpis">
          <span><strong>${users.length}</strong> usuários</span>
          <span><strong>${activeCount}</strong> ativos</span>
          <span><strong>${escapeHtml(getRoleLabel(getCurrentUserRole()))}</strong> seu perfil</span>
        </div>
      </div>
      <div class="users-admin-toolbar">
        <input data-users-admin-filter="query" value="${escapeHtml(state.usersAdmin.query || "")}" placeholder="Buscar por nome, e-mail, perfil ou loja" />
        <select data-users-admin-filter="role"><option value="">Todos os perfis</option>${filterProfileOptions}</select>
        <select data-users-admin-filter="status">
          <option value="">Todos os status</option>
          <option value="ativo"${state.usersAdmin.status === "ativo" ? " selected" : ""}>Ativos</option>
          <option value="inativo"${state.usersAdmin.status === "inativo" ? " selected" : ""}>Inativos</option>
        </select>
        <button class="secondary-button" type="button" data-users-admin-refresh>Atualizar</button>
        <button class="primary-button" type="button" data-users-admin-new>Novo usuário</button>
      </div>
      ${state.usersAdmin.error ? `<div class="users-admin-alert">${escapeHtml(state.usersAdmin.error)}</div>` : ""}
      <div class="users-admin-grid">
        <article class="users-admin-card users-admin-list">
          <div class="users-admin-list-head"><strong>${state.usersAdmin.loading ? "Carregando..." : "Equipe cadastrada"}</strong><small>Selecione um usuário para editar.</small></div>
          <div class="users-admin-rows">
            ${users.length ? users.map((user) => `
              <button class="users-admin-row${Number(user.id) === Number(draft.id || 0) ? " active" : ""}" type="button" data-users-admin-select="${escapeHtml(user.id)}">
                <span><strong>${escapeHtml(user.name || user.email)}</strong><small>${escapeHtml(user.email)}${user.username ? ` / ${escapeHtml(user.username)}` : ""}</small></span>
                <span class="users-admin-row-meta"><em>${escapeHtml(user.role_label || getRoleLabel(user.role))}</em><small>${escapeHtml(user.store_label || "-")}</small></span>
                <span class="users-admin-status ${escapeHtml(user.status || "ativo")}">${escapeHtml(user.status || "ativo")}</span>
              </button>
            `).join("") : `<div class="users-admin-empty">Nenhum usuário encontrado para os filtros atuais.</div>`}
          </div>
        </article>
        <article class="users-admin-card users-admin-editor">
          <form data-users-admin-form>
            <input type="hidden" name="id" value="${escapeHtml(draft.id || "")}" />
            <div class="users-admin-editor-head">
              <div><p class="eyebrow">${draft.id ? "Editar acesso" : "Novo acesso"}</p><h3>${escapeHtml(draft.name || "Usuário AEROSTORE")}</h3></div>
              <span class="users-admin-status ${escapeHtml(draft.status || "ativo")}">${escapeHtml(draft.status || "ativo")}</span>
            </div>
            <div class="users-admin-section users-admin-data-section"><h4>Dados do usuário</h4><div class="users-admin-form-grid">
              <label>Nome<input name="name" value="${escapeHtml(draft.name)}" required /></label>
              <label>E-mail/login<input name="email" type="email" value="${escapeHtml(draft.email)}" required /></label>
              <label>Usuário curto<input name="username" value="${escapeHtml(draft.username)}" /></label>
              <label>WhatsApp<input name="phone" value="${escapeHtml(draft.phone)}" /></label>
              <label>Perfil<select name="role">${profileOptions}</select></label>
              <label>Status<select name="status"><option value="ativo"${draft.status === "ativo" ? " selected" : ""}>ativo</option><option value="inativo"${draft.status === "inativo" ? " selected" : ""}>inativo</option></select></label>
              <label>Loja principal<select name="store_id">${storeOptions}</select></label>
              <label>Senha ${draft.id ? "<small>preencha apenas para redefinir</small>" : ""}<input name="password" type="password" value="" placeholder="${draft.id ? "manter senha atual" : "mínimo 8 caracteres"}" /></label>
            </div></div>
            <div class="users-admin-section"><h4>Lojas permitidas</h4><div class="users-admin-check-grid">${allowedStores}</div></div>
            <div class="users-admin-section users-admin-permissions-section"><h4>Permissões por módulo</h4>${permissionCatalog || `<p class="helper-text">Catálogo de permissões indisponível.</p>`}</div>
            <div class="users-admin-actions">
              <button class="primary-button" type="submit">${state.usersAdmin.saving ? "Salvando..." : "Salvar usuário"}</button>
              ${draft.id ? `<button class="secondary-button" type="button" data-users-admin-reset-password="${escapeHtml(draft.id)}">Redefinir senha</button>` : ""}
              ${draft.id ? `<button class="secondary-button" type="button" data-users-admin-toggle-status="${escapeHtml(draft.id)}" data-status="${draft.status === "ativo" ? "inativo" : "ativo"}">${draft.status === "ativo" ? "Desativar" : "Reativar"}</button>` : ""}
              ${draft.id ? `<button class="danger-button" type="button" data-users-admin-delete="${escapeHtml(draft.id)}">Excluir teste</button>` : ""}
            </div>
          </form>
        </article>
      </div>
    </section>
  `;
}

function readUsersAdminForm(form) {
  const data = new FormData(form);
  const permissions = {};
  Array.from(form.querySelectorAll('input[name="permissions"]')).forEach((input) => {
    permissions[input.value] = Boolean(input.checked);
  });
  const allowedStores = Array.from(form.querySelectorAll('input[name="allowed_stores"]:checked')).map((input) => input.value);
  return {
    id: normalizeText(data.get("id") || ""),
    name: normalizeText(data.get("name") || ""),
    email: normalizeText(data.get("email") || "").toLowerCase(),
    username: normalizeText(data.get("username") || "").toLowerCase(),
    phone: normalizeText(data.get("phone") || ""),
    role: normalizeText(data.get("role") || "seller"),
    status: normalizeText(data.get("status") || "ativo"),
    store_id: normalizePdvStoreIdentifier(data.get("store_id") || "vila") || "vila",
    allowed_stores: allowedStores.length ? allowedStores.map((item) => normalizePdvStoreIdentifier(item)).filter(Boolean) : [normalizePdvStoreIdentifier(data.get("store_id") || "vila") || "vila"],
    permissions,
    password: String(data.get("password") || "").trim()
  };
}

async function saveUsersAdminForm(form) {
  const payload = readUsersAdminForm(form);
  state.usersAdmin.saving = true;
  renderUsersAdminFront();
  try {
    const isEdit = Boolean(payload.id);
    const response = await api(isEdit ? `/api/admin/users/${encodeURIComponent(payload.id)}` : "/api/admin/users", {
      method: isEdit ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const saved = response.user || null;
    if (saved?.id) {
      state.usersAdmin.selectedId = String(saved.id);
      state.usersAdmin.draft = createUsersAdminDraft(saved);
    }
    showFeedback("Usuario salvo com sucesso.");
    await loadUsersAdmin();
  } finally {
    state.usersAdmin.saving = false;
    renderUsersAdminFront();
  }
}

async function setUsersAdminStatus(userId, status) {
  await api(`/api/admin/users/${encodeURIComponent(userId)}/status`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status })
  });
  showFeedback(status === "ativo" ? "Usuario reativado." : "Usuario desativado.");
  await loadUsersAdmin();
}

async function resetUsersAdminPassword(userId) {
  const password = window.prompt("Nova senha temporária para este usuário (mínimo 8 caracteres):", "");
  if (!password) {
    return;
  }
  if (password.length < 8) {
    showFeedback("Use uma senha com pelo menos 8 caracteres.", "error");
    return;
  }
  const mustChangePassword = window.confirm("Exigir que o usuário troque a senha no próximo acesso?");
  await api(`/api/admin/users/${encodeURIComponent(userId)}/reset-password`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newPassword: password, mustChangePassword })
  });
  showFeedback("Senha redefinida com sucesso.");
}

async function deleteUsersAdminUser(userId) {
  if (!window.confirm("Excluir este usuario de teste? Usuarios reais devem ser desativados para preservar historico.")) {
    return;
  }
  await api(`/api/admin/users/${encodeURIComponent(userId)}`, { method: "DELETE" });
  state.usersAdmin.selectedId = "";
  state.usersAdmin.draft = null;
  showFeedback("Usuario excluido.");
  await loadUsersAdmin();
}

function renderOfficialRouteSection(sectionId = "") {
  if (OFFICIAL_PDV_SECTIONS.has(sectionId)) {
    renderPdvFront(sectionId);
    return;
  }
  if (sectionId === "aerointel") {
    renderAeroIntelFront();
    loadAeroIntelFront().catch((error) => {
      handleUiError("Erro ao carregar o painel AEROINTEL", error);
    });
    return;
  }
  if (sectionId === "whatsapp-crm") {
    renderWhatsAppRouteFront();
    loadWhatsAppCrmFront().catch((error) => {
      handleUiError("Erro ao carregar a frente do WhatsApp CRM", error);
    });
    return;
  }
  if (sectionId === "users-admin") {
    renderUsersAdminFront();
    loadUsersAdmin().catch((error) => {
      handleUiError("Erro ao carregar usuarios e permissoes", error);
    });
    return;
  }
  if (sectionId === "audit-logs") {
    renderAuditLogsFront();
    loadAuditLogs().catch((error) => {
      handleUiError("Erro ao carregar auditoria operacional", error);
    });
    return;
  }
  if (sectionId === "ai") {
    renderAiStrategicProductsPanel();
    if (canManageAiStrategicImport() && !state.aiStrategicProducts.length) {
      loadAiStrategicProducts().catch((error) => {
        handleUiError("Erro ao carregar os produtos estrategicos", error);
      });
    }
  }
}

function getAuditLogsContainer() {
  return document.getElementById("audit-logs-content");
}

function formatAuditJsonPreview(value = "") {
  if (!value) return "-";
  try {
    return JSON.stringify(JSON.parse(value), null, 2);
  } catch (error) {
    return String(value || "-");
  }
}

function safeParseAuditJson(value = "") {
  if (!value) return null;
  try {
    return JSON.parse(value);
  } catch (error) {
    return value;
  }
}

function buildAuditDetailPayload(row = {}) {
  return {
    message: row.message || "",
    reason: row.reason || "",
    sale_id: row.sale_id || "",
    customer_id: row.customer_id || "",
    product_id: row.product_id || "",
    amount: row.amount,
    before: safeParseAuditJson(row.before_json || ""),
    after: safeParseAuditJson(row.after_json || ""),
    metadata: safeParseAuditJson(row.metadata_json || "")
  };
}

function buildAuditLogsFilters() {
  const filters = state.auditLogs.filters || {};
  return `
    <form class="audit-toolbar" data-audit-logs-filters>
      <input name="user" value="${escapeHtml(filters.user || "")}" placeholder="Usuário/e-mail" />
      <input name="module" value="${escapeHtml(filters.module || "")}" placeholder="Módulo" />
      <input name="action" value="${escapeHtml(filters.action || "")}" placeholder="Ação" />
      <input name="sale_id" value="${escapeHtml(filters.sale_id || "")}" placeholder="Venda" />
      <select name="result">
        <option value="">Todos os resultados</option>
        <option value="success"${filters.result === "success" ? " selected" : ""}>Sucesso</option>
        <option value="blocked"${filters.result === "blocked" ? " selected" : ""}>Bloqueado</option>
        <option value="failed"${filters.result === "failed" ? " selected" : ""}>Falha</option>
      </select>
      <button class="secondary-button" type="submit">Filtrar</button>
      <button class="ghost-button" type="button" data-audit-logs-reset>Limpar</button>
    </form>
  `;
}

function buildAuditLogsList() {
  const rows = toArray(state.auditLogs.rows);
  if (state.auditLogs.loading) {
    return `<div class="empty-state compact"><strong>Carregando auditoria...</strong><span>Buscando eventos operacionais sensíveis.</span></div>`;
  }
  if (state.auditLogs.error) {
    return `<div class="empty-state compact error"><strong>Não foi possível carregar auditoria.</strong><span>${escapeHtml(state.auditLogs.error)}</span></div>`;
  }
  if (!rows.length) {
    return `<div class="empty-state compact"><strong>Nenhum evento encontrado.</strong><span>Ajuste os filtros ou execute uma ação sensível para gerar histórico.</span></div>`;
  }
  return `
    <div class="audit-table-wrap">
      <table class="audit-table">
        <thead>
          <tr><th>Data/hora</th><th>Usuário</th><th>Perfil</th><th>Loja</th><th>Módulo</th><th>Ação</th><th>Entidade</th><th>Resultado</th><th>Detalhes</th></tr>
        </thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              <td>${escapeHtml(formatDateTimeBR(row.created_at || ""))}</td>
              <td><strong>${escapeHtml(row.user_name || "-")}</strong><span>${escapeHtml(row.user_email || "")}</span></td>
              <td>${escapeHtml(getRoleLabel(row.user_role || "") || row.user_role || "-")}</td>
              <td>${escapeHtml(row.store_name || row.store_id || "-")}</td>
              <td>${escapeHtml(row.module || "-")}</td>
              <td>${escapeHtml(row.action || "-")}</td>
              <td><strong>${escapeHtml(row.entity_label || row.entity_id || row.sale_id || row.customer_id || row.product_id || "-")}</strong><span>${escapeHtml(row.entity_type || "")}</span></td>
              <td><span class="audit-result is-${escapeHtml(row.result || "neutral")}">${escapeHtml(row.result || "-")}</span></td>
              <td>
                <details class="audit-details">
                  <summary>Ver</summary>
                  <pre>${escapeHtml(formatAuditJsonPreview(JSON.stringify(buildAuditDetailPayload(row))))}</pre>
                </details>
              </td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderAuditLogsFront() {
  const container = getAuditLogsContainer();
  if (!container) return;
  if (!canViewAuditLogsPanel()) {
    container.innerHTML = `<article class="hero-card"><p class="eyebrow">Acesso restrito</p><h3>Auditoria operacional</h3><p>Seu perfil não tem permissão para acessar esta frente.</p></article>`;
    return;
  }
  container.innerHTML = `
    <section class="audit-shell">
      <div class="users-admin-hero">
        <div>
          <p class="eyebrow">Segurança AEROSTORE OS</p>
          <h3>Auditoria operacional</h3>
          <p>Histórico de ações sensíveis por usuário, loja, módulo e entidade afetada.</p>
        </div>
        <div class="users-admin-kpis">
          <span><strong>${toArray(state.auditLogs.rows).length}</strong> eventos</span>
          <span><strong>${escapeHtml(getRoleLabel(getCurrentUserRole()))}</strong> seu perfil</span>
        </div>
      </div>
      ${buildAuditLogsFilters()}
      <article class="panel">
        <div class="panel-header">
          <div><h3>Eventos recentes</h3><p class="panel-helper">Senhas, PINs e tokens são mascarados antes de gravar.</p></div>
          <button class="ghost-button small" type="button" data-audit-logs-refresh>${state.auditLogs.loading ? "Atualizando..." : "Atualizar"}</button>
        </div>
        ${buildAuditLogsList()}
      </article>
    </section>
  `;
}

async function loadAuditLogs() {
  if (!canViewAuditLogsPanel()) return;
  state.auditLogs.loading = true;
  state.auditLogs.error = "";
  renderAuditLogsFront();
  try {
    const params = new URLSearchParams();
    Object.entries(state.auditLogs.filters || {}).forEach(([key, value]) => {
      const normalized = normalizeText(value || "");
      if (normalized) params.set(key, normalized);
    });
    const result = await api(`/api/admin/audit-logs${params.toString() ? `?${params.toString()}` : ""}`);
    state.auditLogs.rows = toArray(result?.rows);
  } catch (error) {
    state.auditLogs.error = normalizeVisibleText(error?.message || "Falha ao carregar auditoria.");
    throw error;
  } finally {
    state.auditLogs.loading = false;
    renderAuditLogsFront();
  }
}

function applyAuditLogsFilters(form = null) {
  const data = new FormData(form);
  state.auditLogs.filters = {
    user: normalizeText(data.get("user") || ""),
    module: normalizeText(data.get("module") || ""),
    action: normalizeText(data.get("action") || ""),
    result: normalizeText(data.get("result") || ""),
    sale_id: normalizeText(data.get("sale_id") || "")
  };
  loadAuditLogs().catch((error) => handleUiError("Erro ao filtrar auditoria", error));
}

function getSidebarMenuIcon(label = "") {
  const normalized = normalizeText(label || "").toLowerCase();
  const iconMap = [
    ["painel", "PD"],
    ["venda", "VD"],
    ["pedido", "PE"],
    ["caixa", "CX"],
    ["produto", "PR"],
    ["cliente", "CL"],
    ["estoque", "ES"],
    ["reserva", "RS"],
    ["troca", "TR"],
    ["whatsapp", "WA"],
    ["campanha", "CP"],
    ["cashback", "CB"],
    ["relatorio", "RL"],
    ["consolidacao", "CO"],
    ["aerointel", "AI"],
    ["usuario", "US"],
    ["auditoria", "AU"],
    ["config", "CF"],
    ["import", "IM"],
    ["automatico", "AT"],
    ["execucao", "EX"]
  ];
  const match = iconMap.find(([key]) => normalized.includes(key));
  return match ? match[1] : normalizeText(label || "AE").slice(0, 2).toUpperCase();
}

function renderGlobalSidebarIdentity() {
  const brandText = document.querySelector("#sidebar-brand p");
  const userName = document.getElementById("sidebar-user-name");
  const userMeta = document.getElementById("sidebar-user-meta");
  const userStore = document.getElementById("sidebar-user-store");
  const userAvatar = document.getElementById("sidebar-user-avatar");
  const logoutButton = document.getElementById("sidebar-logout-button");
  if (brandText) {
    brandText.textContent = "PDV/CRM operacional da loja.";
  }
  if (!state.currentUser) {
    if (userName) userName.textContent = "Sessao nao iniciada";
    if (userMeta) userMeta.textContent = "Faca login para continuar";
    if (userStore) {
      userStore.classList.remove("sidebar-user-store-switcher");
      userStore.textContent = "AEROSTORE OS";
    }
    if (userAvatar) userAvatar.textContent = "AE";
    if (logoutButton) logoutButton.style.display = "none";
    return;
  }
  const roleLabel = getRoleLabel(getCurrentRole());
  const storeLabel = getCurrentUserStoreLabel();
  const storeSelector = buildActiveStoreSelectMarkup({ compact: true });
  if (userName) userName.textContent = getCurrentUserDisplayName();
  if (userMeta) userMeta.textContent = `Perfil: ${roleLabel}`;
  if (userStore) {
    if (storeSelector) {
      userStore.classList.add("sidebar-user-store-switcher");
      userStore.innerHTML = `<span class="sidebar-store-label">Loja ativa</span>${storeSelector}`;
    } else {
      userStore.classList.remove("sidebar-user-store-switcher");
      userStore.textContent = `Loja ativa: ${storeLabel || "-"}`;
    }
  }
  if (userAvatar) userAvatar.textContent = getCurrentUserInitials();
  if (logoutButton) logoutButton.style.display = "";
}

function renderTopbarActiveStoreSelector() {
  const actions = document.querySelector(".topbar-actions");
  if (!actions) {
    return;
  }
  let wrapper = document.getElementById("topbar-active-store-switcher");
  const storeSelector = buildActiveStoreSelectMarkup({ compact: true });
  if (!state.currentUser || !storeSelector) {
    if (wrapper) wrapper.remove();
    return;
  }
  if (!wrapper) {
    wrapper = document.createElement("div");
    wrapper.id = "topbar-active-store-switcher";
    wrapper.className = "topbar-active-store-switcher";
    const userChip = document.getElementById("current-user-label");
    actions.insertBefore(wrapper, userChip || actions.firstChild);
  }
  wrapper.innerHTML = `<span>Loja ativa</span>${storeSelector}`;
}

