function isMenuItemActive(item) {
  const currentPath = window.location.pathname || "/";
  const currentHash = String(window.location.hash || "").replace(/^#/, "").trim();
  const pathnameSection = getSectionFromPathname(currentPath);
  if (item.section) {
    if (pathnameSection) {
      return pathnameSection === item.section;
    }
    if (currentPath !== "/" && currentPath !== "/login") {
      return false;
    }
    const effectiveHash = currentHash || "dashboard";
    return effectiveHash === item.section;
  }
  if (item.route) {
    if (item.route === "/pdv/vendas" || item.route === "/pdv/pedidos") {
      return currentPath === "/pdv/vendas" || currentPath === "/pdv/pedidos";
    }
    if (item.route === "/pdv") {
      return currentPath === "/pdv" || currentPath === "/pdv/dashboard";
    }
    return currentPath === item.route;
  }
  return false;
}

