function selectPdvManualExchangeCreditCustomer(index = -1) {
  const customer = toArray(state.pdvExchanges.manualCreditCustomerResults)[Number(index)] || null;
  if (!customer) return;
  state.pdvExchanges.manualCreditSelectedCustomer = customer;
  state.pdvExchanges.manualCreditCustomerResults = [];
  state.pdvExchanges.manualCreditCustomerError = "";
  state.pdvExchanges.manualCreditError = "";
  renderPdvExchangesFront();
}

function clearPdvManualExchangeCreditCustomer() {
  state.pdvExchanges.manualCreditSelectedCustomer = null;
  state.pdvExchanges.manualCreditCustomerResults = [];
  state.pdvExchanges.manualCreditLastCreated = null;
  renderPdvExchangesFront();
}

async function createPdvManualExchangeCredit(form) {
  const customer = getPdvManualExchangeSelectedCustomer();
  if (!customer) {
    state.pdvExchanges.manualCreditError = "Selecione o cliente favorecido antes de criar o crédito.";
    renderPdvExchangesFront();
    return;
  }
  const data = new FormData(form);
  const payload = {
    customer_id: customer.master_customer_id || customer.customer_id || customer.id || "",
    master_customer_id: customer.master_customer_id || customer.customer_id || customer.id || "",
    contact_id: customer.contact_id || customer.operational_contact_id || "",
    crm_contact_id: customer.crm_contact_id || "",
    legacy_contact_id: customer.legacy_contact_id || "",
    name: customer.name || customer.nome || "",
    phone: customer.phone || customer.telefone || "",
    document: customer.document || customer.cpf || customer.cnpj || "",
    store_id: normalizePdvStoreIdentifier(data.get("store_id") || getCurrentPdvStoreId() || ""),
    source_origin: normalizeText(data.get("source_origin") || "tiny_legacy"),
    source_reference: normalizeText(data.get("source_reference") || ""),
    amount: parseMoneyAmount(data.get("amount") || 0),
    reason: normalizeText(data.get("reason") || ""),
    notes: normalizeText(data.get("notes") || "")
  };
  state.pdvExchanges.manualCreditSaving = true;
  state.pdvExchanges.manualCreditError = "";
  renderPdvExchangesFront();
  try {
    const response = await api("/api/pdv/exchanges/credits/manual", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    state.pdvExchanges.manualCreditLastCreated = response.credit || null;
    state.pdvExchanges.manualCreditCustomerQuery = "";
    state.pdvExchanges.manualCreditCustomerResults = [];
    form?.reset?.();
    showFeedback("Crédito de Troca manual criado e disponível no checkout.", "success");
  } catch (error) {
    state.pdvExchanges.manualCreditError = error.message || "Falha ao criar crédito manual.";
  } finally {
    state.pdvExchanges.manualCreditSaving = false;
    renderPdvExchangesFront();
  }
}

async function createPdvExchangeQuickCustomer(form) {
  const data = new FormData(form);
  const payload = {
    name: normalizeText(data.get("name") || ""),
    phone: normalizeText(data.get("phone") || ""),
    document: normalizeText(data.get("document") || ""),
    store_id: getCurrentPdvStoreId()
  };
  if (!payload.name || !payload.phone) {
    state.pdvExchanges.customerError = "Informe nome e telefone para cadastrar quem esta efetuando a troca.";
    renderPdvExchangesFront();
    return;
  }
  state.pdvExchanges.customerError = "";
  try {
    const customer = await api("/api/pdv/operational/customers/quick-register", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    await setPdvExchangeCustomer(customer);
    showFeedback("Cliente da troca vinculado.", "success");
  } catch (error) {
    state.pdvExchanges.customerError = error.message || "Falha ao cadastrar cliente da troca.";
    renderPdvExchangesFront();
  }
}

function getPdvExchangeReasonLabel(reason = "") {
  const key = normalizeText(reason || "").toLowerCase();
  const labels = {
    tamanho: "Tamanho",
    cor: "Cor",
    defeito: "Defeito",
    presente: "Presente",
    arrependimento: "Arrependimento",
    troca_por_outro_produto: "Troca por outro produto",
    outro: "Outro"
  };
  return labels[key] || normalizeVisibleText(reason || "-");
}

function getPdvExchangeConditionLabel(condition = "") {
  const key = normalizeText(condition || "").toLowerCase();
  const labels = {
    disponivel: "Disponivel para venda",
    aguardando_conferencia: "Aguardando conferencia",
    defeito: "Defeito",
    avaria: "Com avaria",
    perda: "Perda / nao retornar ao estoque",
    sem_etiqueta: "Sem etiqueta"
  };
  return labels[key] || normalizeVisibleText(condition || "-");
}

function buildPdvExchangeReceiptPrint(receipt = {}) {
  const returnedItems = getPdvExchangeReturnedItems(receipt);
  const returnedItem = returnedItems[0] || receipt.returned_item || {};
  const exchangeCustomer = receipt.exchange_customer || {};
  const variation = [
    returnedItem.sku || returnedItem.codigo,
    returnedItem.marca,
    returnedItem.categoria,
    returnedItem.cor,
    returnedItem.tamanho
  ].map((item) => normalizeVisibleText(item || "")).filter(Boolean).join(" | ");
  const customerName = exchangeCustomer.name || receipt.credit_owner_customer_id || "-";
  const customerPhone = exchangeCustomer.phone || exchangeCustomer.telefone || "-";
  return `
    <article class="exchange-receipt-print" data-pdv-exchange-receipt-print>
      <header>
        <strong>AEROSTORE</strong>
        <span>Comprovante de Cr&eacute;dito de Troca</span>
      </header>
      <section class="exchange-receipt-print-block">
        <div><span>Troca</span><strong>${escapeHtml(receipt.exchange_id || "-")}</strong></div>
        <div><span>Venda original</span><strong>${escapeHtml(receipt.original_sale_id || "-")}</strong></div>
        <div><span>Data/hora</span><strong>${escapeHtml(formatDateTimeBR(receipt.finalized_at || ""))}</strong></div>
        <div><span>Loja</span><strong>${escapeHtml(receipt.store_id || "-")}</strong></div>
        <div><span>Vendedor</span><strong>${escapeHtml(receipt.seller_name || "-")}</strong></div>
      </section>
      <section class="exchange-receipt-print-block">
        <h3>Cliente favorecido</h3>
        <div><span>Nome</span><strong>${escapeHtml(customerName)}</strong></div>
        <div><span>Telefone</span><strong>${escapeHtml(customerPhone)}</strong></div>
        <div><span>Cr&eacute;dito vinculado a</span><strong>${escapeHtml(customerName)}</strong></div>
      </section>
      <section class="exchange-receipt-print-block">
        <h3>${returnedItems.length > 1 ? "Produtos devolvidos" : "Produto devolvido"}</h3>
        ${returnedItems.map((item) => {
          const itemVariation = [
            item.sku || item.codigo,
            item.marca,
            item.categoria,
            item.cor,
            item.tamanho
          ].map((entry) => normalizeVisibleText(entry || "")).filter(Boolean).join(" | ");
          return `
            <p class="exchange-receipt-product">${escapeHtml(item.nome || "-")}</p>
            ${itemVariation ? `<p class="exchange-receipt-muted">${escapeHtml(itemVariation)}</p>` : ""}
            <div><span>Quantidade</span><strong>${escapeHtml(String(item.quantity || item.quantidade || 1))}</strong></div>
          `;
        }).join("") || `
          <p class="exchange-receipt-product">${escapeHtml(returnedItem.nome || "-")}</p>
          ${variation ? `<p class="exchange-receipt-muted">${escapeHtml(variation)}</p>` : ""}
          <div><span>Quantidade</span><strong>${escapeHtml(String(returnedItem.quantity || returnedItem.quantidade || 1))}</strong></div>
        `}
        <div><span>Motivo</span><strong>${escapeHtml(getPdvExchangeReasonLabel(receipt.reason || ""))}</strong></div>
        <div><span>Condi&ccedil;&atilde;o</span><strong>${escapeHtml(getPdvExchangeConditionLabel(receipt.returned_condition || ""))}</strong></div>
      </section>
      <section class="exchange-receipt-print-total">
        <span>Cr&eacute;dito gerado</span>
        <strong>${escapeHtml(currency(receipt.credit_generated || 0))}</strong>
      </section>
      <section class="exchange-receipt-policy">
        <p>Este cr&eacute;dito poder&aacute; ser usado em venda futura no PDV da AEROSTORE. N&atilde;o h&aacute; devolu&ccedil;&atilde;o autom&aacute;tica em dinheiro.</p>
        <p>Cr&eacute;dito sem expira&ccedil;&atilde;o autom&aacute;tica, salvo pol&iacute;tica interna da loja.</p>
      </section>
      <footer>AEROSTORE &bull; Operacao de troca registrada no PDV</footer>
    </article>
  `;
}

function printPdvExchangeReceipt() {
  const receipt = state.pdvExchanges.receipt;
  if (!receipt?.exchange_id) {
    showFeedback("Finalize a troca antes de imprimir o comprovante.", "error");
    return;
  }
  if (!document.querySelector("[data-pdv-exchange-receipt-print]")) {
    renderPdvExchangesFront();
  }
  document.body.classList.add("is-printing-exchange-receipt");
  const cleanup = () => document.body.classList.remove("is-printing-exchange-receipt");
  window.addEventListener("afterprint", cleanup, { once: true });
  setTimeout(() => {
    window.print();
    setTimeout(cleanup, 1500);
  }, 80);
}

function buildPdvExchangeSummary() {
  const draft = state.pdvExchanges.draft;
  const receipt = state.pdvExchanges.receipt;
  if (receipt) {
    const returnedItems = getPdvExchangeReturnedItems(receipt);
    return `
      <div class="pdv-exchange-receipt">
        <span>Troca finalizada</span>
        <strong>${escapeHtml(receipt.exchange_id || "")}</strong>
        <p>${escapeHtml(receipt.customer?.name || "Cliente")} • ${escapeHtml(formatDateTimeBR(receipt.finalized_at || ""))}</p>
        <div><span>${returnedItems.length > 1 ? "Produtos devolvidos" : "Produto devolvido"}</span><strong>${escapeHtml(returnedItems.length > 1 ? `${returnedItems.length} itens selecionados` : (receipt.returned_item?.nome || "-"))}</strong></div>
        <div><span>Cliente favorecido</span><strong>${escapeHtml(receipt.exchange_customer?.name || receipt.credit_owner_customer_id || "-")}</strong></div>
        <div><span>Credito gerado</span><strong>${currency(receipt.credit_generated || 0)}</strong></div>
        ${receipt.credit_generated > 0 ? `<div><span>Credito vinculado a</span><strong>${escapeHtml(receipt.exchange_customer?.name || receipt.credit_owner_customer_id || "-")}</strong></div>` : ""}
        ${buildPdvExchangeReceiptPrint(receipt)}
        <button class="secondary-button" type="button" data-pdv-exchange-print-receipt>Imprimir comprovante</button>
        <button class="ghost-button" type="button" data-pdv-exchange-new>Nova troca</button>
      </div>
    `;
  }
  if (!draft) {
    return `<div class="empty-state compact"><strong>Resumo da troca</strong><span>Selecione uma venda original para iniciar.</span></div>`;
  }
  const totals = getPdvExchangeTotals(draft);
  const returnedItems = getPdvExchangeReturnedItems(draft);
  const creditNeedsCustomer = !hasValidPdvExchangeFavoredCustomer(draft);
  const conditionMissing = !isValidPdvExchangeReturnedCondition(draft.returned_condition);
  const computedStatus = getPdvExchangeComputedStatus(draft);
  const canFinalize = Boolean(
    draft.original_sale_id
    && returnedItems.length
    && totals.creditGenerated > 0
    && !creditNeedsCustomer
    && draft.reason
    && !conditionMissing
    && !state.pdvExchanges.finalizing
  );
  return `
    <div class="pdv-exchange-summary-card">
      <span>Status</span>
      <strong>${escapeHtml(getPdvExchangeDisplayStatus(computedStatus))}</strong>
      <div><span>Valor devolvido</span><strong>${currency(totals.originalValue)}</strong></div>
      <div><span>Itens devolvidos</span><strong>${returnedItems.length || 0}</strong></div>
      <div class="${totals.creditGenerated > 0 ? "is-balanced" : ""}"><span>Credito gerado</span><strong>${currency(totals.creditGenerated)}</strong></div>
      <div><span>Credito para</span><strong>${escapeHtml(draft.exchange_customer?.name || draft.customer?.name || "Selecione o cliente")}</strong></div>
      <div><span>Cliente vinculado</span><strong>${escapeHtml(getPdvExchangeFavoredCustomerId(draft) || "Sem ID valido")}</strong></div>
      <div><span>Condicao do devolvido</span><strong>${escapeHtml(normalizeVisibleText(draft.returned_condition || "-"))}</strong></div>
      ${creditNeedsCustomer ? `<div class="pdv-payment-alert warning">Selecione ou cadastre o cliente favorecido com identificador valido antes de finalizar.</div>` : ""}
      ${conditionMissing ? `<div class="pdv-payment-alert warning">Selecione a condicao do devolvido antes de finalizar a troca.</div>` : ""}
      <p class="panel-helper">A Central gera credito e devolve o item ao estoque. A escolha dos novos produtos acontece depois em uma venda normal.</p>
      ${state.pdvExchanges.error ? `<div class="pdv-payment-alert warning">${escapeHtml(state.pdvExchanges.error)}</div>` : ""}
      <button class="primary-button" type="button" data-pdv-exchange-finalize${canFinalize ? "" : " disabled"}>${state.pdvExchanges.finalizing ? "Finalizando..." : "Finalizar troca"}</button>
      <button class="ghost-button" type="button" data-pdv-exchange-new>Limpar troca</button>
    </div>
  `;
}

function canCreateManualExchangeCreditFrontend() {
  return isCurrentUserManagerProfile() || hasPermission("can_create_manual_exchange_credit");
}

function getPdvManualExchangeStoreOptions() {
  const options = getActiveStoreOptionsForCurrentUser();
  const currentStore = normalizePdvStoreIdentifier(getCurrentPdvStoreId() || "");
  if (!options.length && currentStore) {
    return [{ value: currentStore, label: formatStoreIdLabel(currentStore) }];
  }
  return options.length ? options : getOfficialStoreOptions();
}

function getPdvManualExchangeSelectedCustomer() {
  return state.pdvExchanges.manualCreditSelectedCustomer || null;
}

function buildPdvManualExchangeCreditPanel() {
  const canCreate = canCreateManualExchangeCreditFrontend();
  const selectedCustomer = getPdvManualExchangeSelectedCustomer();
  const customerResults = toArray(state.pdvExchanges.manualCreditCustomerResults);
  const storeOptions = getPdvManualExchangeStoreOptions();
  const defaultStore = normalizePdvStoreIdentifier(getCurrentPdvStoreId() || storeOptions[0]?.value || "");
  const lastCredit = state.pdvExchanges.manualCreditLastCreated;
  if (!canCreate) {
    return `
      <section class="pdv-exchange-panel pdv-manual-credit-panel is-locked">
        <div class="pdv-exchange-panel-head">
          <span>Crédito manual externo</span>
          <strong>Restrito à gestão</strong>
          <small>Vendedores e caixa não podem criar crédito manual.</small>
        </div>
      </section>
    `;
  }
  return `
    <section class="pdv-exchange-panel pdv-manual-credit-panel">
      <div class="pdv-exchange-panel-head">
        <span>Crédito manual externo</span>
        <strong>Criar crédito para venda Tiny/antiga</strong>
        <small>Use apenas para vendas antigas conferidas ou ajustes aprovados pela gestão.</small>
      </div>
      <div class="pdv-manual-credit-grid">
        <div class="pdv-manual-credit-search">
          <form class="pdv-exchange-search" data-pdv-manual-credit-customer-search-form>
            <input name="q" type="search" value="${escapeHtml(state.pdvExchanges.manualCreditCustomerQuery || "")}" placeholder="Buscar cliente por nome, telefone ou CPF" />
            <button class="secondary-button small" type="submit">${state.pdvExchanges.manualCreditCustomerLoading ? "Buscando..." : "Buscar cliente"}</button>
          </form>
          ${state.pdvExchanges.manualCreditCustomerError ? `<div class="pdv-payment-alert warning">${escapeHtml(state.pdvExchanges.manualCreditCustomerError)}</div>` : ""}
          ${selectedCustomer ? `
            <div class="pdv-manual-credit-selected">
              <span>Cliente selecionado</span>
              <strong>${escapeHtml(selectedCustomer.name || selectedCustomer.nome || "Cliente")}</strong>
              <small>${escapeHtml(selectedCustomer.phone || selectedCustomer.telefone || "Sem telefone informado")}</small>
              <button class="ghost-button tiny" type="button" data-pdv-manual-credit-clear-customer>Trocar</button>
            </div>
          ` : customerResults.length ? `
            <div class="pdv-exchange-customer-results">
              ${customerResults.map((item, index) => `
                <button type="button" class="pdv-exchange-customer-result" data-pdv-manual-credit-customer-pick="${index}">
                  <strong>${escapeHtml(item.name || item.nome || "Cliente")}</strong>
                  <span>${escapeHtml([item.phone || item.telefone || "", item.document || item.cpf || ""].filter(Boolean).join(" • "))}</span>
                </button>
              `).join("")}
            </div>
          ` : `<div class="empty-state compact"><strong>Selecione o cliente favorecido</strong><span>O crédito manual precisa ficar vinculado a um contato operacional.</span></div>`}
        </div>
        <form class="pdv-manual-credit-form" data-pdv-manual-credit-form>
          <label>Loja
            <select name="store_id">
              ${storeOptions.map((option) => `<option value="${escapeHtml(option.value)}"${normalizePdvStoreIdentifier(option.value) === defaultStore ? " selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
            </select>
          </label>
          <label>Origem
            <select name="source_origin">
              <option value="tiny_legacy">Tiny / venda antiga</option>
              <option value="venda_externa">Venda externa</option>
              <option value="ajuste_manual">Ajuste manual</option>
            </select>
          </label>
          <label>Referência externa
            <input name="source_reference" placeholder="Pedido Tiny, cupom ou observação curta" />
          </label>
          <label>Valor do crédito
            <input name="amount" inputmode="decimal" placeholder="0,00" />
          </label>
          <label>Motivo
            <input name="reason" placeholder="Ex.: troca venda antiga Tiny" />
          </label>
          <label class="pdv-manual-credit-wide">Observação detalhada
            <textarea name="notes" rows="3" minlength="20" placeholder="Mínimo 20 caracteres. Ex.: Troca referente venda antiga Tiny conferida por Milene..."></textarea>
          </label>
          ${state.pdvExchanges.manualCreditError ? `<div class="pdv-payment-alert warning pdv-manual-credit-wide">${escapeHtml(state.pdvExchanges.manualCreditError)}</div>` : ""}
          <div class="pdv-manual-credit-actions">
            <span>${selectedCustomer ? `Crédito para ${escapeHtml(selectedCustomer.name || selectedCustomer.nome || "cliente")}` : "Selecione um cliente antes de criar."}</span>
            <button class="primary-button" type="submit"${state.pdvExchanges.manualCreditSaving || !selectedCustomer ? " disabled" : ""}>${state.pdvExchanges.manualCreditSaving ? "Criando..." : "Criar crédito manual"}</button>
          </div>
        </form>
      </div>
      ${lastCredit ? `
        <div class="pdv-manual-credit-created">
          <span>Último crédito criado</span>
          <strong>${escapeHtml(lastCredit.credit_id || "")} • ${currency(lastCredit.remaining_amount || lastCredit.amount || 0)}</strong>
          <small>Já disponível no checkout do cliente selecionado.</small>
        </div>
      ` : ""}
    </section>
  `;
}

function shouldShowPdvManualExchangeCreditPanel() {
  return false;
}

function buildPdvExchangeHistoryFilters() {
  const filters = state.pdvExchanges.historyFilters || {};
  const canChooseStore = canViewAllStores();
  const storeOptions = uniqueStrings([
    getCurrentPdvStoreId(),
    ...toArray(state.pdvExchanges.historyItems).map((row) => row.store_id || row.store_label)
  ].filter(Boolean));
  return `
    <form class="pdv-orders-filters pdv-exchange-history-filters" data-pdv-exchange-history-filters="true">
      <label class="pdv-orders-search">
        <span>Busca livre</span>
        <input name="search" type="search" value="${escapeHtml(filters.search || "")}" placeholder="Cliente, troca, venda ou crédito" />
      </label>
      <label>
        <span>Status</span>
        <select name="status">
          <option value="all"${filters.status === "all" || !filters.status ? " selected" : ""}>Todos</option>
          <option value="finalizada"${filters.status === "finalizada" ? " selected" : ""}>Finalizada</option>
          <option value="pronta_para_gerar_credito"${filters.status === "pronta_para_gerar_credito" ? " selected" : ""}>Pronta para gerar crédito</option>
          <option value="aguardando_motivo_condicao"${filters.status === "aguardando_motivo_condicao" ? " selected" : ""}>Aguardando motivo/condição</option>
          <option value="aguardando_cliente_favorecido"${filters.status === "aguardando_cliente_favorecido" ? " selected" : ""}>Aguardando cliente</option>
          <option value="cancelada"${filters.status === "cancelada" ? " selected" : ""}>Cancelada</option>
        </select>
      </label>
      <label>
        <span>Período</span>
        <select name="period">
          <option value=""${!filters.period ? " selected" : ""}>Todos</option>
          <option value="today"${filters.period === "today" ? " selected" : ""}>Hoje</option>
          <option value="7d"${filters.period === "7d" ? " selected" : ""}>7 dias</option>
          <option value="30d"${filters.period === "30d" ? " selected" : ""}>30 dias</option>
          <option value="custom"${filters.period === "custom" ? " selected" : ""}>Personalizado</option>
        </select>
      </label>
      <label>
        <span>De</span>
        <input name="date_from" type="date" value="${escapeHtml(filters.date_from || "")}" />
      </label>
      <label>
        <span>Até</span>
        <input name="date_to" type="date" value="${escapeHtml(filters.date_to || "")}" />
      </label>
      <label>
        <span>Loja</span>
        <select name="store_id"${canChooseStore ? "" : " disabled"}>
          <option value="">${canChooseStore ? "Todas" : escapeHtml(getCurrentUserStoreLabel())}</option>
          ${storeOptions.map((value) => `<option value="${escapeHtml(value)}"${normalizePdvStoreIdentifier(filters.store_id || "") === normalizePdvStoreIdentifier(value) ? " selected" : ""}>${escapeHtml(formatStoreIdLabel(value))}</option>`).join("")}
        </select>
      </label>
      <div class="pdv-orders-filter-actions">
        <button class="secondary-button" type="submit">Aplicar filtros</button>
        <button class="ghost-button" type="button" data-pdv-exchange-history-refresh>Atualizar</button>
        <button class="ghost-button" type="button" data-pdv-exchange-history-reset>Limpar</button>
      </div>
    </form>
  `;
}

function buildPdvExchangeHistoryTable() {
  const items = toArray(state.pdvExchanges.historyItems);
  if (!items.length) {
    return `<div class="empty-state compact"><strong>Nenhuma troca encontrada</strong><span>Ajuste os filtros ou finalize uma nova troca para aparecer aqui.</span></div>`;
  }
  return `
    <div class="pdv-orders-table-wrap">
      <table class="pdv-orders-table pdv-exchange-history-table">
        <thead>
          <tr>
            <th>Troca</th>
            <th>Data/Hora</th>
            <th>Loja</th>
            <th>Cliente</th>
            <th>Operador</th>
            <th>Crédito</th>
            <th>Status</th>
            <th>Ação</th>
          </tr>
        </thead>
        <tbody>
          ${items.map((item) => {
            const status = normalizeText(item.status || "").toLowerCase();
            const statusLabel = status === "finalizada" ? "Finalizada" : getPdvExchangeDisplayStatus(status || "aguardando_origem");
            const customerName = normalizeText(item.customer_name || item.exchange_customer?.name || item.original_sale_summary?.customer_name || "Cliente");
            const creditAmount = item.credit_generated || item.returned_total || item.original_value || 0;
            return `
              <tr>
                <td><div class="pdv-orders-main-cell"><strong>${escapeHtml(item.exchange_id || "-")}</strong><span>${escapeHtml(item.original_sale_id || item.origin_sale_id || "-")}</span></div></td>
                <td>${escapeHtml(formatDateTimeBR(item.finalized_at || item.updated_at || item.created_at || ""))}</td>
                <td>${escapeHtml(item.store_label || formatStoreIdLabel(item.store_id || ""))}</td>
                <td><div class="pdv-orders-main-cell"><strong>${escapeHtml(customerName)}</strong></div></td>
                <td>${escapeHtml(item.operator_name || item.finalized_by || item.created_by || "-")}</td>
                <td><div class="pdv-orders-main-cell"><strong>${currency(creditAmount)}</strong>${item.credit_id ? `<span>${escapeHtml(item.credit_id)}</span>` : ""}</div></td>
                <td><div class="pdv-orders-status"><strong>${escapeHtml(statusLabel)}</strong></div></td>
                <td><button class="link-button" type="button" data-pdv-exchange-history-detail="${escapeHtml(item.exchange_id || "")}">Ver detalhes</button></td>
              </tr>
            `;
          }).join("")}
        </tbody>
      </table>
    </div>
  `;
}

