function applyRolePermissions() {
  const role = getCurrentRole();
  renderSidebarMenu();
  renderTopbarActiveStoreSelector();
  const userLabel = document.getElementById("current-user-label");
  if (userLabel) {
    if (!state.currentUser) {
      userLabel.textContent = "Sessão não iniciada";
    } else {
      const storeLabel = getCurrentUserStoreLabel();
      const terminalLabel = getCurrentUserStoreTerminalLabel();
      userLabel.textContent = `${state.currentUser.name || state.currentUser.email || "Usuario"} - ${getRoleLabel(role)}${storeLabel && storeLabel !== "-" ? ` - ${storeLabel}` : ""}${terminalLabel ? ` / ${terminalLabel}` : ""}`;
    }
  }
  if (state.currentUser) {
    loadPdvStorePublicContext(getCurrentPdvStoreId(), { silent: true }).then(() => {
      const refreshedLabel = document.getElementById("current-user-label");
      if (refreshedLabel && state.currentUser) {
        const storeLabel = getCurrentUserStoreLabel();
        const terminalLabel = getCurrentUserStoreTerminalLabel();
        refreshedLabel.textContent = `${state.currentUser.name || state.currentUser.email || "Usuario"} - ${getRoleLabel(role)}${storeLabel && storeLabel !== "-" ? ` - ${storeLabel}` : ""}${terminalLabel ? ` / ${terminalLabel}` : ""}`;
      }
      renderGlobalSidebarIdentity();
      renderTopbarActiveStoreSelector();
    }).catch(() => {});
  }
  document.getElementById("logout-button").style.display = state.currentUser ? "" : "none";
  const reportsButton = document.querySelector('[data-section="reports"]');
  if (reportsButton) {
    reportsButton.style.display = canViewReports() ? "" : "none";
  }
  const cashbackReportsButton = document.querySelector('[data-section="cashback-reports"]');
  if (cashbackReportsButton) {
    cashbackReportsButton.style.display = canViewReports() ? "" : "none";
  }
  const settingsButton = document.querySelector('[data-section="settings"]');
  if (settingsButton) {
    settingsButton.style.display = canViewStoreSettingsPanel() ? "" : "none";
  }
  const sellerForm = document.getElementById("seller-form");
  if (sellerForm) {
    sellerForm.style.display = canManageSellers() ? "" : "none";
  }
  renderSettingsWorkspace();
}
function enhanceTableScrolls() {
  document.querySelectorAll(".table-wrap").forEach((wrap) => {
    const existingTop = wrap.previousElementSibling?.classList.contains("table-scroll-top")
      ? wrap.previousElementSibling
      : null;
    if (existingTop) {
      const existingInner = existingTop.querySelector(".table-scroll-top-inner");
      const table = wrap.querySelector("table");
      if (existingInner) {
        existingInner.style.width = `${table ? table.scrollWidth : wrap.scrollWidth}px`;
      }
      return;
    }
    const top = document.createElement("div");
    top.className = "table-scroll-top";
    const inner = document.createElement("div");
    inner.className = "table-scroll-top-inner";
    top.appendChild(inner);
    wrap.parentNode.insertBefore(top, wrap);

    const syncWidth = () => {
      const table = wrap.querySelector("table");
      inner.style.width = `${table ? table.scrollWidth : wrap.scrollWidth}px`;
    };
    top.addEventListener("scroll", () => {
      wrap.scrollLeft = top.scrollLeft;
    });
    wrap.addEventListener("scroll", () => {
      top.scrollLeft = wrap.scrollLeft;
    });
    syncWidth();
    window.addEventListener("resize", syncWidth);
  });
}

function setActiveSection(sectionId) {
  if (state.authLoading) {
    return;
  }
  if (!state.currentUser) {
    redirectToLogin();
    showLoginOverlay("Faça login para acessar esta área do sistema.");
    return;
  }
  const currentPath = normalizePathname(window.location.pathname || "/");
  const pathnameSection = getSectionFromPathname(currentPath);
  let effectiveSection = pathnameSection || sectionId;
  let accessDeniedDetail = "";
  if (!canAccessOfficialSection(effectiveSection)) {
    accessDeniedDetail = "Seu perfil não tem permissão para acessar esta frente.";
    effectiveSection = "access-denied";
  }
  const sectionMeta = getSectionMeta(effectiveSection);
  const displaySectionCandidate = document.getElementById(effectiveSection)
    ? effectiveSection
    : (sectionMeta?.displaySection || effectiveSection);
  const targetSection = document.getElementById(displaySectionCandidate)
    ? displaySectionCandidate
    : (document.getElementById(sectionId) ? sectionId : "dashboard");
  cleanupTransientOverlays(effectiveSection);
  document.querySelectorAll(".menu-link").forEach((button) => {
    if (button.dataset.section) {
      button.classList.toggle("active", button.dataset.section === targetSection);
    }
  });
  document.querySelectorAll(".page").forEach((section) => {
    section.classList.toggle("active", section.id === targetSection);
  });
  document.body.dataset.section = targetSection;
  document.body.dataset.routeSection = effectiveSection;
  if (effectiveSection === "access-denied" || targetSection === "access-denied") {
    renderAccessDeniedState(accessDeniedDetail || undefined);
  }

  // Parar polling do WhatsApp se sair das frentes que mostram o motor
  if (targetSection !== "settings" && targetSection !== "whatsapp-crm") {
    stopWhatsAppPolling();
  }

  const titles = {
    dashboard: "Painel",
    contacts: "Contatos",
    imports: "Importações",
    campaigns: "Campanhas",
    assistant: "Disparo Assistido",
    "campaign-execution": "Execução de Campanhas",
    cashback: "Cashback",
    reports: "Relatórios",
    "cashback-reports": "Relatórios de Cashback",
    ai: "IA de Mensagens",
    settings: "Configurações",
    "access-denied": "Acesso restrito",
    "audit-logs": "Auditoria operacional",
    login: "Entrar",
    "whatsapp-crm": "WhatsApp CRM",
    aerointel: "AEROINTEL",
    "pdv-dashboard": "PDV AEROSTORE",
    "pdv-sale": "Venda",
    "pdv-sales-orders": "Pedidos de venda",
    "pdv-cash-register": "Caixa",
    "pdv-products": "Produtos",
    "pdv-customers": "Clientes",
    "pdv-stock": "Estoque",
    "pdv-reports": "Relatórios",
    "pdv-consolidation": "Consolidação Estratégica",
    "pdv-reservations": "Reservas",
    "pdv-exchanges": "Trocas",
    "pdv-quotes": "Orçamentos",
    "pdv-imports": "Importações"
  };
  if (!pathnameSection) {
    localStorage.setItem(SECTION_STORAGE_KEY, targetSection);
    if (window.location.hash !== `#${targetSection}`) {
      window.location.hash = targetSection;
    }
  }
  sectionTitle.textContent = titles[effectiveSection] || titles[targetSection] || "AEROSTORE CRM";
  renderOfficialRouteSection(effectiveSection);
  normalizeVisibleMojibake(document.querySelector(".page.active") || document.body);
}
function getInitialSection() {
  if (normalizePathname(window.location.pathname || "/") === "/") {
    window.history.replaceState({}, "", "/pdv");
    return "pdv-dashboard";
  }
  const pathnameSection = getSectionFromPathname(window.location.pathname || "/");
  if (pathnameSection) {
    return pathnameSection;
  }
  const hashSection = String(window.location.hash || "").replace(/^#/, "").trim();
  if (hashSection && document.getElementById(hashSection)) {
    return hashSection;
  }
  const storedSection = localStorage.getItem(SECTION_STORAGE_KEY) || "";
  if (storedSection && document.getElementById(storedSection)) {
    return storedSection;
  }
  return "dashboard";
}

