function populateSelect(selectId, values, { includeAll = false, allLabel = "Todos", placeholder = "Selecione" } = {}) {
  const select = document.getElementById(selectId);
  if (!select) {
    return;
  }
  const currentValue = select.value;
  const options = [];
  if (includeAll) {
    options.push(`<option value="">${allLabel}</option>`);
  } else {
    options.push(`<option value="">${placeholder}</option>`);
  }
  values.forEach((value) => {
    options.push(`<option value="${value}">${value === "Botânico" ? "Botânico" : value}</option>`);
  });
  select.innerHTML = options.join("");
  if (currentValue) {
    select.value = currentValue;
  }
}

