function getOrderedSellers(store = "", includeInactive = false) {
  const normalizedStore = String(store || "");
  const base = state.sellers.filter((seller) => includeInactive || seller.status === "ativo");
  const preferred = normalizedStore ? base.filter((seller) => seller.store === normalizedStore) : [];
  const others = normalizedStore ? base.filter((seller) => seller.store !== normalizedStore) : base;
  return [...preferred, ...others];
}

function populateSellerSelect(selectId, { store = "", includeAll = false, includeInactiveSelected = false } = {}) {
  const select = document.getElementById(selectId);
  if (!select) {
    return;
  }
  const currentValue = select.value;
  const sellers = getOrderedSellers(store, false);
  const options = [];
  options.push(`<option value="">${includeAll ? "Todos" : "Selecione"}</option>`);

  sellers.forEach((seller) => {
    options.push(`<option value="${seller.id}">${seller.name} - ${seller.store === "Botânico" ? "Botânico" : seller.store}</option>`);
  });

  if (includeInactiveSelected && currentValue) {
    const currentSeller = state.sellers.find((seller) => String(seller.id) === String(currentValue));
    if (currentSeller && !sellers.some((seller) => seller.id === currentSeller.id)) {
      options.push(`<option value="${currentSeller.id}">${currentSeller.name} - ${currentSeller.store === "Botânico" ? "Botânico" : currentSeller.store}</option>`);
    }
  }

  select.innerHTML = options.join("");
  if (currentValue) {
    select.value = currentValue;
  }
}

function populateSellerSelects() {
  populateSellerSelect("filter-seller", { includeAll: true });
  populateSellerSelect("assistant-seller", { includeAll: true });
  populateSellerSelect("campaign-filter-seller", { includeAll: true });
  populateSellerSelect("report-seller", { includeAll: true });
  populateSellerSelect("cashback-report-seller", { includeAll: true });
  populateSellerSelect("lost-report-seller", { includeAll: true });
  populateSellerSelect("audience-seller", { includeAll: true });
  populateSellerSelect("contact-seller", {
    store: document.getElementById("contact-store")?.value || "",
    includeInactiveSelected: true
  });
  populateSellerSelect("cashback-seller", {
    store: document.getElementById("cashback-store")?.value || "",
    includeInactiveSelected: true
  });
  const campaignSellerSelect = document.getElementById("campaign-seller-select");
  if (campaignSellerSelect) {
    const currentValue = campaignSellerSelect.value || "__all__";
    const options = ['<option value="__all__">Todos os vendedores</option>']
      .concat(
        getOrderedSellers("", false).map(
          (seller) => `<option value="${seller.id}">${seller.name} - ${seller.store === "Botânico" ? "Botânico" : seller.store}</option>`
        )
      );
    campaignSellerSelect.innerHTML = options.join("");
    campaignSellerSelect.value = currentValue;
    if (!campaignSellerSelect.value) {
      campaignSellerSelect.value = "__all__";
    }
  }
}

