function insertVariableIntoCampaignTemplate(variable) {
  const textarea = document.getElementById("campaign-template");
  const currentValue = textarea.value || "";
  const start = Number.isInteger(textarea.selectionStart) ? textarea.selectionStart : currentValue.length;
  const end = Number.isInteger(textarea.selectionEnd) ? textarea.selectionEnd : currentValue.length;
  textarea.value = `${currentValue.slice(0, start)}${variable}${currentValue.slice(end)}`;
  const cursor = start + variable.length;
  textarea.focus();
  textarea.setSelectionRange(cursor, cursor);
}

