function buildStoreSettingsPayloadFromForm(form) {
  const formData = new FormData(form);
  const checkboxValue = (name) => formData.get(name) === "on";
  const textValue = (name) => String(formData.get(name) || "").trim();
  const numberOrNull = (name) => {
    const raw = textValue(name);
    if (!raw) return null;
    const numeric = Number(raw.replace(",", "."));
    return Number.isFinite(numeric) ? numeric : null;
  };
  return {
    store_id: textValue("store_id"),
    legacy_aliases: textValue("legacy_aliases")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean),
    display_name: textValue("display_name"),
    internal_name: textValue("internal_name"),
    status: textValue("status"),
    type: textValue("type"),
    company: {
      legal_name: textValue("company.legal_name"),
      trade_name: textValue("company.trade_name"),
      cnpj: textValue("company.cnpj"),
      state_registration: textValue("company.state_registration"),
      municipal_registration: textValue("company.municipal_registration"),
      tax_regime_label: textValue("company.tax_regime_label")
    },
    address: {
      zip: textValue("address.zip"),
      street: textValue("address.street"),
      number: textValue("address.number"),
      complement: textValue("address.complement"),
      district: textValue("address.district"),
      city: textValue("address.city"),
      state: textValue("address.state"),
      country: textValue("address.country")
    },
    contact: {
      phone: textValue("contact.phone"),
      whatsapp: textValue("contact.whatsapp"),
      email: textValue("contact.email"),
      manager_name: textValue("contact.manager_name"),
      opening_hours: textValue("contact.opening_hours")
    },
    terminal: {
      default_register_id: textValue("terminal.default_register_id"),
      default_terminal_label: textValue("terminal.default_terminal_label"),
      default_printer_label: textValue("terminal.default_printer_label"),
      receipt_footer: textValue("terminal.receipt_footer"),
      sale_prefix: textValue("terminal.sale_prefix")
    },
    inventory: {
      primary_deposit_id: textValue("inventory.primary_deposit_id"),
      linked_deposit_ids: textValue("inventory.linked_deposit_ids").split(",").map((item) => item.trim()).filter(Boolean),
      allows_shared_stock: checkboxValue("inventory.allows_shared_stock"),
      allows_transfer_request: checkboxValue("inventory.allows_transfer_request"),
      requires_cross_state_transfer_review: checkboxValue("inventory.requires_cross_state_transfer_review")
    },
    policies: {
      cashback_generate_enabled: checkboxValue("policies.cashback_generate_enabled"),
      cashback_redeem_enabled: checkboxValue("policies.cashback_redeem_enabled"),
      payment_link_enabled: checkboxValue("policies.payment_link_enabled"),
      gift_card_enabled: checkboxValue("policies.gift_card_enabled"),
      exchange_enabled: checkboxValue("policies.exchange_enabled"),
      auto_discount_enabled: checkboxValue("policies.auto_discount_enabled"),
      local_discount_limit_percent: numberOrNull("policies.local_discount_limit_percent"),
      pickup_enabled: checkboxValue("policies.pickup_enabled"),
      delivery_enabled: checkboxValue("policies.delivery_enabled"),
      delivery_policy_label: textValue("policies.delivery_policy_label"),
      operational_notes: textValue("policies.operational_notes")
    },
    integrations: {
      whatsapp_instance_id: textValue("integrations.whatsapp_instance_id"),
      pagbank_account_label: textValue("integrations.pagbank_account_label"),
      tiny_store_id: textValue("integrations.tiny_store_id"),
      tiny_deposit_id: textValue("integrations.tiny_deposit_id")
    }
  };
}

async function loadStoreSettingsDetail(storeId, options = {}) {
  const selectedStoreId = normalizeText(storeId || "").toLowerCase();
  if (!selectedStoreId || !canViewRealStoreSettings()) {
    return;
  }
  state.storeSettings.loading = true;
  if (!options.preserveError) {
    state.storeSettings.error = "";
  }
  try {
    const response = await api(`/api/settings/stores/${encodeURIComponent(selectedStoreId)}`);
    state.storeSettings.current = response?.store || null;
    state.storeSettings.selectedStoreId = normalizeText(response?.store?.store_id || selectedStoreId).toLowerCase();
    renderStoreSettingsPanel();
  } catch (error) {
    state.storeSettings.error = error.message || "Falha ao carregar a configuração da loja.";
    renderStoreSettingsPanel();
    throw error;
  } finally {
    state.storeSettings.loading = false;
  }
}

async function loadStoreSettingsCatalog(options = {}) {
  if (!canViewRealStoreSettings()) {
    state.storeSettings.list = [];
    state.storeSettings.current = null;
    state.storeSettings.selectedStoreId = "";
    state.storeSettings.loaded = false;
    return;
  }
  state.storeSettings.loading = true;
  state.storeSettings.error = "";
  try {
    const response = await api("/api/settings/stores");
    const rows = toArray(response?.stores);
    state.storeSettings.list = rows;
    state.storeSettings.loaded = true;
    const preferredStoreId = normalizeText(
      options.storeId
      || state.storeSettings.selectedStoreId
      || getCurrentPdvStoreId()
      || state.currentUser?.store_id
      || rows[0]?.store_id
      || ""
    ).toLowerCase();
    state.storeSettings.selectedStoreId = preferredStoreId;
    renderStoreSettingsPanel();
    if (preferredStoreId) {
      await loadStoreSettingsDetail(preferredStoreId, { preserveError: true });
    }
  } catch (error) {
    state.storeSettings.error = error.message || "Falha ao carregar o catálogo de lojas.";
    state.storeSettings.loaded = false;
    renderStoreSettingsPanel();
    throw error;
  } finally {
    state.storeSettings.loading = false;
  }
}

async function saveStoreSettingsForm(event) {
  event.preventDefault();
  if (!canEditRealStoreSettings()) {
    showFeedback("Seu perfil não pode editar a configuração da loja.", "error");
    return;
  }
  const form = event.target;
  const payload = buildStoreSettingsPayloadFromForm(form);
  const selectedStoreId = normalizeText(state.storeSettings.selectedStoreId || payload.store_id || "").toLowerCase();
  if (!selectedStoreId) {
    showFeedback("Selecione uma loja para salvar.", "error");
    return;
  }
  state.storeSettings.saving = true;
  state.storeSettings.error = "";
  renderStoreSettingsPanel();
  try {
    const response = await api(`/api/settings/stores/${encodeURIComponent(selectedStoreId)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    state.storeSettings.current = response?.store || null;
    state.storeSettings.selectedStoreId = normalizeText(response?.store?.store_id || selectedStoreId).toLowerCase();
    const summary = toArray(state.storeSettings.list);
    const nextSummary = {
      store_id: response?.store?.store_id || selectedStoreId,
      display_name: response?.store?.display_name || formatStoreIdLabel(selectedStoreId),
      internal_name: response?.store?.internal_name || "",
      status: response?.store?.status || "active",
      type: response?.store?.type || "physical_store",
      contact: response?.store?.contact || {},
      metadata: response?.store?.metadata || {}
    };
    const existingIndex = summary.findIndex((item) => normalizeText(item.store_id || "").toLowerCase() === normalizeText(nextSummary.store_id || "").toLowerCase());
    if (existingIndex >= 0) {
      summary[existingIndex] = nextSummary;
    } else {
      summary.push(nextSummary);
    }
    state.storeSettings.list = summary;
    showFeedback("Configuracao da loja salva com sucesso.", "success");
    renderStoreSettingsPanel();
  } catch (error) {
    state.storeSettings.error = error.message || "Falha ao salvar a configuração da loja.";
    showFeedback(state.storeSettings.error, "error");
    renderStoreSettingsPanel();
  } finally {
    state.storeSettings.saving = false;
    renderStoreSettingsPanel();
  }
}

function bindStoreSettingsPanel() {
  const form = document.getElementById("store-settings-form");
  if (form && !form.dataset.bound) {
    form.dataset.bound = "true";
    form.addEventListener("submit", (event) => {
      saveStoreSettingsForm(event).catch((error) => {
        showFeedback(error.message || "Falha ao salvar a configuração da loja.", "error");
      });
    });
  }
  const selector = form?.querySelector('select[name="storeSelector"]');
  if (selector && !selector.dataset.bound) {
    selector.dataset.bound = "true";
    selector.addEventListener("change", (event) => {
      const nextStoreId = normalizeText(event.target.value || "").toLowerCase();
      state.storeSettings.selectedStoreId = nextStoreId;
      loadStoreSettingsDetail(nextStoreId).catch((error) => {
        showFeedback(error.message || "Falha ao trocar a loja das configurações.", "error");
      });
    });
  }
  const reloadButton = document.getElementById("store-settings-reload-button");
  if (reloadButton && !reloadButton.dataset.bound) {
    reloadButton.dataset.bound = "true";
    reloadButton.addEventListener("click", () => {
      loadStoreSettingsCatalog({ storeId: getSelectedStoreSettingsId() }).then(() => {
        showFeedback("Configuracoes da loja atualizadas.", "success");
      }).catch((error) => {
        showFeedback(error.message || "Falha ao atualizar a configuração da loja.", "error");
      });
    });
  }
}

function updateSettingsPanelHeader(panel, eyebrow, title, description, badgeLabel, badgeVariant = "neutral") {
  if (!panel) {
    return;
  }
  let header = panel.querySelector(".panel-header");
  if (!header) {
    header = document.createElement("div");
    header.className = "panel-header settings-panel-header";
    panel.prepend(header);
  }
  header.classList.add("settings-panel-header");
  header.innerHTML = `
    <div>
      <p class="eyebrow">${escapeHtml(eyebrow || "")}</p>
      <h3>${escapeHtml(title || "")}</h3>
      <p class="settings-panel-description">${escapeHtml(description || "")}</p>
    </div>
    <span class="tag settings-badge ${escapeHtml(badgeVariant || "neutral")}">${escapeHtml(badgeLabel || "")}</span>
  `;
}

