function renderCashbackSettings() {
  if (!state.settings) {
    syncThemeControl();
    renderSettingsWorkspace();
    return;
  }

  document.getElementById("cashback-setting-percentages").value = state.settings.percentages.join(", ");
  document.getElementById("cashback-setting-validity").value = state.settings.defaultValidityDays;
  document.getElementById("cashback-setting-minimum").value = state.settings.defaultMinimumPurchase;
  document.getElementById("cashback-setting-reactivation-limit").value = state.settings.reactivationLimitPerStore;
  document.getElementById("cashback-setting-reactivated").value = state.settings.reactivatedValidityDays;
  document.getElementById("cashback-setting-anticipated").value = state.settings.anticipatedValidityDays;
  document.getElementById("cashback-percentages-list").innerHTML = state.settings.percentages
    .map((value) => `<span>${value}%</span>`)
    .join("");
  const userModeLabel = document.getElementById("user-mode-label");
  if (userModeLabel) {
    userModeLabel.textContent = getCurrentRole();
  }
  document.getElementById("cashback-settings-panel").style.display = canViewGlobalSettingsPanel() ? "" : "none";
  syncThemeControl();

  document.getElementById("cashback-expires-at").value = formatDateBR(addDays(today(), state.settings.defaultValidityDays));
  populateSellerSelects();
  renderSettingsWorkspace();
}

function getConfiguredCashbackPercentage() {
  const configured = Array.isArray(state.settings?.percentages)
    ? state.settings.percentages.map(Number).filter((value) => value > 0)
    : [];
  return configured[0] || 12;
}

async function updateCashbackPreview() {
  const purchaseValue = Number(document.getElementById("cashback-purchase-value").value || 0);
  const percentage = getConfiguredCashbackPercentage();
  const generatedValue = Number((purchaseValue * (percentage / 100)).toFixed(2));
  const generatedField = document.getElementById("cashback-generated-value");
  const validFrom = today();
  const expiresAt = addDays(validFrom, state.settings?.defaultValidityDays || 30);

  if (purchaseValue <= 0) {
    generatedField.value = generatedValue.toFixed(2);
    renderCashbackWizardSummary();
    return;
  }

  try {
    const previewData = await api("/api/cashbacks/wizard/preview", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(getCashbackWizardPayload())
    });

    if (previewData.contact?.id) {
      state.cashbackContact = previewData.contact;
      document.getElementById("cashback-contact-id").value = String(previewData.contact.id);
      document.getElementById("cashback-wizard-phone").value = formatPhoneBR(previewData.contact.phone || "");
      document.getElementById("cashback-wizard-name").value = previewData.contact.name || "";
      updateCashbackCustomerGender();
      if (!state.cashbackSummary || Number(state.cashbackContact?.id || 0) !== Number(previewData.contact.id)) {
        await loadCashbackContactById(previewData.contact.id);
      }
      document.getElementById("cashback-customer-hint").textContent = "Cliente encontrado. Confira o resumo e gere o PIN para confirmar o bônus.";
    } else {
      document.getElementById("cashback-customer-hint").textContent = "Cliente novo. Confira o resumo e gere o PIN para concluir o cadastro rápido com o bônus.";
    }

    state.cashbackWizard = { ...state.cashbackWizard, preview: previewData.preview };
    generatedField.value = Number(previewData.preview.generatedValue || 0).toFixed(2);
    document.getElementById("cashback-expires-at").value = formatDateBR(previewData.preview.expiresAt);
    renderCashbackWizardSummary(previewData.preview);
  } catch (error) {
    generatedField.value = generatedValue.toFixed(2);
    document.getElementById("cashback-expires-at").value = formatDateBR(expiresAt);
    renderCashbackWizardSummary({
      availableCashback: 0,
      cashbackUsed: 0,
      amountPaid: purchaseValue,
      generatedValue,
      expiresAt
    });
  }
}

function getCashbackWizardPayload() {
  const contactId = Number(document.getElementById("cashback-contact-id").value || 0);
  const selectedContact = state.contacts.find((item) => item.id === contactId) || state.cashbackContact || null;
  return {
    contactId: contactId || null,
    phone: normalizePhone(document.getElementById("cashback-wizard-phone")?.value || selectedContact?.phone || ""),
    name: document.getElementById("cashback-wizard-name")?.value.trim() || selectedContact?.name || "",
    gender: document.getElementById("cashback-customer-gender").value || selectedContact?.gender || "",
    store: document.getElementById("cashback-store").value,
    sellerId: document.getElementById("cashback-seller").value || null,
    purchaseValue: Number(document.getElementById("cashback-purchase-value").value || 0)
  };
}

async function generateCashbackWizardPin() {
  const payload = getCashbackWizardPayload();
  if (!payload.phone || !payload.purchaseValue) {
    showFeedback("Informe telefone e valor da compra para gerar o PIN.", "error");
    return;
  }
  const result = await api("/api/cashbacks/wizard/pin", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  state.cashbackWizard = result;
  document.getElementById("cashback-generated-pin").value = result.pin;
  document.getElementById("cashback-expires-at").value = formatDateBR(result.preview.expiresAt);
  document.getElementById("cashback-generated-value").value = Number(result.preview.generatedValue || 0).toFixed(2);
  renderCashbackWizardSummary(result.preview);
  document.getElementById("cashback-lgpd-box").textContent =
    `Ao gerar ou utilizar o bônus, o cliente concorda com os termos de uso e privacidade: ${result.termsLink}`;
  showFeedback("PIN gerado com sucesso.");
}

async function sendCashbackWizardWhatsapp() {
  if (!state.cashbackWizard?.tokenId) {
    showFeedback("Gere o PIN antes de enviar por WhatsApp.", "error");
    return;
  }
  const result = await api("/api/cashbacks/wizard/send-pin", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ tokenId: state.cashbackWizard.tokenId })
  });
  window.open(buildWhatsAppWebUrl(result.phone, result.message), "_blank");
  showFeedback("WhatsApp Web aberto com a mensagem do bônus.");
}

function getSelectedCampaignContactIds() {
  return Array.from(state.selectedCampaignContactIds);
}

function syncSelectedContactsState() {
  const selectedMap = new Map(
    [...state.selectedCampaignContacts, ...state.filteredCampaignContacts, ...state.contacts]
      .filter(Boolean)
      .map((contact) => [Number(contact.id), contact])
  );
  state.selectedCampaignContacts = getSelectedCampaignContactIds()
    .map((contactId) => selectedMap.get(Number(contactId)))
    .filter(Boolean);
  state.selectedContacts = state.selectedCampaignContacts;
}

function getAssistantProgressData(campaignId) {
  const normalizedCampaignId = Number(campaignId || 0);
  const rows = state.campaignExecution.filter((row) => Number(row.campaign_id) === normalizedCampaignId);
  if (!rows.length) {
    return { total: 0, sent: 0, remaining: 0, percent: 0 };
  }
  const total = rows.reduce((sum, row) => sum + Number(row.total_clients || 0), 0);
  const sent = rows.reduce((sum, row) => sum + Number(row.sent_count || 0), 0);
  const remaining = rows.reduce((sum, row) => sum + Number(row.pending_count || 0), 0);
  const percent = total > 0 ? Math.round((sent / total) * 100) : 0;
  return { total, sent, remaining, percent };
}

function renderAssistantProgress(campaignId) {
  const target = document.getElementById("assistant-progress");
  if (!target) {
    return;
  }
  const progress = getAssistantProgressData(campaignId || document.getElementById("assistant-campaign")?.value);
  target.textContent = `${progress.sent} / ${progress.total} (${progress.percent}%) • Restantes: ${progress.remaining}`;
}

function getReportFilters() {
  return {
    dateFrom: document.getElementById("report-date-from")?.value || "",
    dateTo: document.getElementById("report-date-to")?.value || "",
    store: document.getElementById("report-store")?.value || "",
    sellerId: document.getElementById("report-seller")?.value || "",
    gender: document.getElementById("report-gender")?.value || "",
    status: document.getElementById("report-status")?.value || "",
    campaignId: document.getElementById("report-campaign")?.value || ""
  };
}

function toDateInputValue(date) {
  const target = new Date(date);
  const year = target.getFullYear();
  const month = String(target.getMonth() + 1).padStart(2, "0");
  const day = String(target.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getCashbackReportRange(preset) {
  const base = new Date();
  const todayValue = toDateInputValue(base);
  switch (preset) {
    case "yesterday": {
      const date = new Date(base);
      date.setDate(date.getDate() - 1);
      const value = toDateInputValue(date);
      return { dateFrom: value, dateTo: value };
    }
    case "7d": {
      const start = new Date(base);
      start.setDate(start.getDate() - 6);
      return { dateFrom: toDateInputValue(start), dateTo: todayValue };
    }
    case "30d": {
      const start = new Date(base);
      start.setDate(start.getDate() - 29);
      return { dateFrom: toDateInputValue(start), dateTo: todayValue };
    }
    case "month": {
      const start = new Date(base.getFullYear(), base.getMonth(), 1);
      return { dateFrom: toDateInputValue(start), dateTo: todayValue };
    }
    case "last-month": {
      const start = new Date(base.getFullYear(), base.getMonth() - 1, 1);
      const end = new Date(base.getFullYear(), base.getMonth(), 0);
      return { dateFrom: toDateInputValue(start), dateTo: toDateInputValue(end) };
    }
    case "custom":
      return {
        dateFrom: document.getElementById("cashback-report-date-from")?.value || "",
        dateTo: document.getElementById("cashback-report-date-to")?.value || ""
      };
    case "today":
    default:
      return { dateFrom: todayValue, dateTo: todayValue };
  }
}

function applyCashbackReportPreset(preset, { resetPage = true } = {}) {
  const range = getCashbackReportRange(preset);
  state.cashbackReports.filters.preset = preset;
  document.getElementById("cashback-report-date-from").value = range.dateFrom;
  document.getElementById("cashback-report-date-to").value = range.dateTo;
  if (resetPage) {
    state.cashbackReports.filters.page = 1;
  }
  document.querySelectorAll("#cashback-report-quick-ranges [data-range]").forEach((button) => {
    button.classList.toggle("active", button.dataset.range === preset);
  });
}

