async function loadContacts(filters = {}) {
  const query = new URLSearchParams();
  Object.entries(filters).forEach(([key, value]) => {
    if (value) {
      query.set(key, value);
    }
  });
  state.contacts = await api(`/api/contatos${query.toString() ? `?${query.toString()}` : ""}`);
  state.filteredCampaignContacts = [];
  renderContacts();
}

async function loadCampaignContactsForSelection() {
  const filters = getCampaignSelectionFilters();
  const hasActiveFilter = Object.values(filters).some((value) => String(value || "").trim() !== "");
  if (!hasActiveFilter) {
    state.filteredCampaignContacts = [];
    renderCampaignContactsTable();
    return;
  }
  const query = new URLSearchParams();
  Object.entries(filters).forEach(([key, value]) => {
    if (value) {
      query.set(key, value);
    }
  });
  query.set("limit", "10");
  state.filteredCampaignContacts = await api(`/api/clientes/busca?${query.toString()}`);
  renderCampaignContactsTable();
}

async function selectAllCampaignContactsFromCurrentFilter() {
  if (!state.filteredCampaignContacts.length) {
    renderCampaignContactsTable();
    return;
  }
  state.filteredCampaignContacts.forEach((contact) => state.selectedCampaignContactIds.add(contact.id));
  renderCampaignContactsTable();
}

