async function loadReports() {
  if (!canViewReports()) {
    state.reportsOverview = null;
    state.reportsSellers = [];
    state.reportsGender = [];
    state.reportsStores = [];
    renderReportsOverview();
    renderReportsTables();
    await loadCashbackReports();
    return;
  }
  const query = new URLSearchParams();
  Object.entries(getReportFilters()).forEach(([key, value]) => {
    if (value) {
      query.set(key, value);
    }
  });
  const suffix = query.toString() ? `?${query.toString()}` : "";
  const [overview, sellers, gender, stores] = await Promise.all([
    api(`/api/reports/overview${suffix}`),
    api(`/api/reports/sellers${suffix}`),
    api(`/api/reports/gender${suffix}`),
    api(`/api/reports/stores${suffix}`)
  ]);
  state.reportsOverview = overview;
  state.reportsSellers = sellers;
  state.reportsGender = gender;
  state.reportsStores = stores;
  renderReportsOverview();
  renderReportsTables();
  await loadCashbackReports();
}

async function restoreSession() {
  state.authLoading = true;
  loadSavedTheme(state.currentUser);
  syncAuthShellState();
  showLoginOverlay("__checking__");
  try {
    const response = await fetch("/api/auth/me", {
      method: "GET",
      credentials: "include",
      headers: { Accept: "application/json" }
    });
    if (response.status === 401) {
      state.authLoading = false;
      clearAuthSession();
      redirectToLogin();
      showLoginOverlay("");
      return false;
    }
    if (!response.ok) {
      throw new Error("Não foi possível verificar a sessão agora.");
    }
    const authPayload = await response.json();
    state.currentUser = normalizeAuthUserStoreContext(authPayload?.user || authPayload || null);
    if (state.currentUser) {
      localStorage.setItem("aerostore_auth_user", JSON.stringify(state.currentUser));
    }
    state.isAuthenticated = Boolean(state.currentUser);
    state.authLoading = false;
    loadSavedTheme(state.currentUser);
    if (isPasswordChangeRequired(state.currentUser)) {
      hideLoginOverlay();
      showPasswordChangeOverlay({ forced: true });
      return false;
    }
    hideLoginOverlay();
    applyRolePermissions();
    return true;
  } catch (error) {
    state.authLoading = false;
    clearAuthSession();
    redirectToLogin();
    showLoginOverlay("Faça login para acessar esta área do sistema.");
    return false;
  }
}
async function loginUser(event) {
  event.preventDefault();
  const email = document.getElementById("login-email").value.trim();
  const password = document.getElementById("login-password").value;
  const result = await api("/api/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password })
  });
  setAuthSession(result.token || "", result.user || null);
  if (result.must_change_password || isPasswordChangeRequired(result.user || null)) {
    hideLoginOverlay();
    showPasswordChangeOverlay({ forced: true });
    return;
  }
  applyRolePermissions();
  hideLoginOverlay();
  if (window.location.pathname === "/login") {
    window.history.replaceState({}, "", getDefaultRouteForCurrentUser());
  }
  await bootstrap();
}

