function canManageAiStrategicImport() {
  const role = getCurrentUserRole();
  return ["admin", "gestor"].includes(role)
    && hasPermission("can_view_aerointel")
    && hasPermission("can_manage_store_settings");
}

function ensureTop100CuratedImportState() {
  if (!state.top100CuratedImport || typeof state.top100CuratedImport !== "object") {
    state.top100CuratedImport = {
      loading: false,
      commitLoading: false,
      previewId: "",
      summary: null,
      items: [],
      filePath: "",
      updateExisting: false,
      createCatalogs: true,
      lastResult: null,
      error: ""
    };
  }
  return state.top100CuratedImport;
}

function parseTop100CuratedDelimitedValue(value = "") {
  return Array.from(new Set(
    String(value || "")
      .split(/[,\n;|]/)
      .map((item) => normalizeText(item))
      .filter(Boolean)
  ));
}

function reconcileTop100CuratedPreviewItem(item = {}) {
  const importState = ensureTop100CuratedImportState();
  const normalizedItem = {
    ...item,
    sku: normalizeText(item.sku || ""),
    nome_produto: normalizeText(item.nome_produto || ""),
    nome_comercial_sugerido: normalizeText(item.nome_comercial_sugerido || item.nome_produto || item.sku || ""),
    categoria: normalizeText(item.categoria || ""),
    genero_inferido: normalizeText(item.genero_inferido || ""),
    cor_detectada: normalizeText(item.cor_detectada || ""),
    tamanho_detectado: parseTop100CuratedDelimitedValue(item.tamanho_detectado || "").join(", "),
    marca: normalizeText(item.marca || ""),
    tags_sugeridas: parseTop100CuratedDelimitedValue(item.tags_sugeridas || "").join(", "),
    descricao_curta_sugerida: normalizeText(item.descricao_curta_sugerida || ""),
    argumento_venda_sugerido: normalizeText(item.argumento_venda_sugerido || ""),
    prioridade_sugerida: normalizeText(item.prioridade_sugerida || "media").toLowerCase() || "media",
    status_sugerido: normalizeText(item.status_sugerido || "ativo").toLowerCase() === "inativo" ? "inativo" : "ativo",
    use_in_ai: item.use_in_ai !== false,
    use_in_pos: Boolean(item.use_in_pos)
  };
  const warnings = [];
  let action = "criar";
  if (normalizedItem.existingProductId) {
    action = importState.updateExisting ? "atualizar" : "ignorar";
    if (!importState.updateExisting) {
      warnings.push("Produto ja existe no sistema e atualizar existentes esta desmarcado.");
    }
  }
  if (!normalizedItem.sku) {
    action = "ignorar";
    warnings.push("Produto sem SKU valido.");
  }
  if (!(toNumber(normalizedItem.preco_venda) > 0)) {
    action = "ignorar";
    warnings.push("Produto sem preco valido.");
  }
  if (!normalizedItem.categoria) {
    warnings.push(importState.createCatalogs ? "Categoria sera criada automaticamente ou ajustada para Sem categoria." : "Categoria precisa revisao antes do commit.");
  }
  if (!normalizedItem.genero_inferido) {
    warnings.push("Genero ainda nao definido.");
  }
  warnings.push(...toArray(item.warnings).map((warning) => normalizeText(warning)).filter(Boolean));
  normalizedItem.action = action;
  normalizedItem.warnings = Array.from(new Set(warnings));
  return normalizedItem;
}

function reconcileTop100CuratedPreviewItems() {
  const importState = ensureTop100CuratedImportState();
  importState.items = toArray(importState.items).map(reconcileTop100CuratedPreviewItem);
  renderAiStrategicProductsPanel();
}

function summarizeAiStrategicProducts(items = []) {
  const rows = toArray(items);
  return {
    total: rows.length,
    active: rows.filter((item) => item.status === "ativo").length,
    withoutPhoto: rows.filter((item) => !item.preview_url).length,
    top100Curado: rows.filter((item) => normalizeText(item.source || "").toLowerCase() === "top100_curado").length
  };
}

function buildAiStrategicProductCards(items = []) {
  const rows = toArray(items).slice(0, 8);
  if (!rows.length) {
    return `<div class="empty-state">Nenhum produto estrategico cadastrado ainda.</div>`;
  }
  return `
    <div class="ai-strategic-products-grid">
      ${rows.map((item) => `
        <article class="ai-strategic-product-card">
          <div class="ai-strategic-product-card-header">
            <div>
              <strong>${escapeHtml(item.display_name || item.commercial_name || item.name || item.sku || "Produto estrategico")}</strong>
              <span>${escapeHtml(item.sku || "Sem SKU")} • ${escapeHtml(item.category || "Sem categoria")}</span>
            </div>
            <span class="pill-badge ${item.status === "ativo" ? "badge-success-soft" : "badge-neutral-soft"}">${escapeHtml(item.status || "ativo")}</span>
          </div>
          <div class="ai-strategic-product-metrics">
            <span>${currency(item.price || 0)}</span>
            <span>Estoque ${escapeHtml(String(item.stock ?? item.estoque_total ?? 0))}</span>
            <span>${escapeHtml(item.brand || item.marca || "Sem marca")}</span>
          </div>
          <div class="ai-strategic-product-badges">
            ${item.use_in_ai ? `<span class="pill-badge badge-dark-soft">Vitrine IA</span>` : ""}
            ${item.use_in_pos ? `<span class="pill-badge badge-neutral-soft">PDV</span>` : ""}
            ${!item.preview_url ? `<span class="pill-badge badge-warning-soft">Sem foto</span>` : ""}
          </div>
        </article>
      `).join("")}
    </div>
  `;
}

function renderAiStrategicProductsPanel() {
  const listNode = document.getElementById("ai-strategic-products-list");
  const summaryNode = document.getElementById("top100-curated-summary");
  const warningNode = document.getElementById("top100-curated-warning");
  const selectedNode = document.getElementById("top100-curated-selected-count");
  const previewNode = document.getElementById("top100-curated-preview");
  if (!listNode || !summaryNode || !warningNode || !selectedNode || !previewNode) {
    return;
  }

  const strategicSummary = summarizeAiStrategicProducts(state.aiStrategicProducts);
  listNode.innerHTML = buildAiStrategicProductCards(state.aiStrategicProducts);

  const importState = ensureTop100CuratedImportState();
  const items = toArray(importState.items);
  const selectedCount = items.filter((item) => item.selected).length;
  const overLimit = selectedCount > 20;
  selectedNode.textContent = `${selectedCount} selecionados`;

  summaryNode.innerHTML = `
    <div class="ai-curated-summary-grid">
      <article class="ai-curated-stat-card"><span>Top 100</span><strong>${escapeHtml(String(importState.summary?.totalRows || 0))}</strong><small>Linhas encontradas no arquivo curado.</small></article>
      <article class="ai-curated-stat-card"><span>Recomendados</span><strong>${escapeHtml(String(importState.summary?.selectedRecommended || 0))}</strong><small>Primeiro lote sugerido.</small></article>
      <article class="ai-curated-stat-card"><span>Vitrine atual</span><strong>${escapeHtml(String(strategicSummary.total || 0))}</strong><small>${escapeHtml(String(strategicSummary.top100Curado || 0))} vindos do Top 100 curado.</small></article>
      <article class="ai-curated-stat-card"><span>Sem foto</span><strong>${escapeHtml(String(strategicSummary.withoutPhoto || 0))}</strong><small>Alertas atuais da vitrine.</small></article>
    </div>
    <div class="helper-text">Arquivo base: ${escapeHtml(getDisplayFileName(importState.filePath) || "vitrine_ia_top_100.csv")}</div>
  `;

  warningNode.className = `status-banner ${overLimit ? "warning" : importState.error ? "error" : "success"}`;
  warningNode.textContent = importState.error
    ? importState.error
    : overLimit
      ? `Para o primeiro lote, recomendamos importar ate 20 produtos. Voce selecionou ${selectedCount}.`
      : "Recomendado importar ate 20 produtos no primeiro lote.";

  if (!items.length) {
    previewNode.innerHTML = `
      <div class="empty-state">
        Carregue o Top 100 curado para revisar SKU, score, acao prevista e os textos antes do commit.
      </div>
    `;
    return;
  }

  previewNode.innerHTML = `
    <div class="ai-curated-preview-list">
      ${items.map((item) => `
        <article class="ai-curated-preview-card ${item.selected ? "is-selected" : ""}">
          <div class="ai-curated-preview-head">
            <label class="checkbox-field">
              <input type="checkbox" data-top100-curated-select="${escapeHtml(item.id)}" ${item.selected ? "checked" : ""}>
              <span>Selecionar</span>
            </label>
            <div class="ai-curated-preview-title">
              <strong>${escapeHtml(item.nome_comercial_sugerido || item.nome_produto || item.sku || "Produto sem nome")}</strong>
              <span>${escapeHtml(item.sku || "Sem SKU")} • ABC ${escapeHtml(item.abc_classificacao || "-")} • Score ${escapeHtml(String(item.score_total || 0))}</span>
            </div>
            <div class="ai-curated-preview-meta">
              <span class="pill-badge badge-dark-soft">${escapeHtml(item.action || "criar")}</span>
              <span class="pill-badge badge-neutral-soft">${escapeHtml(item.prioridade_sugerida || "media")}</span>
              ${item.existingProductId ? `<span class="pill-badge badge-warning-soft">Ja existe</span>` : `<span class="pill-badge badge-success-soft">Novo</span>`}
            </div>
          </div>
          <div class="ai-curated-preview-grid">
            <label>Nome comercial<input type="text" data-top100-curated-field="nome_comercial_sugerido" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(item.nome_comercial_sugerido || "")}"></label>
            <label>Categoria<input type="text" data-top100-curated-field="categoria" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(item.categoria || "")}"></label>
            <label>Genero
              <select data-top100-curated-field="genero_inferido" data-top100-curated-id="${escapeHtml(item.id)}">
                ${["masculino", "feminino", "infantil", "unissex", ""].map((option) => `<option value="${option}" ${normalizeText(item.genero_inferido).toLowerCase() === option ? "selected" : ""}>${option || "Indefinido"}</option>`).join("")}
              </select>
            </label>
            <label>Cor<input type="text" data-top100-curated-field="cor_detectada" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(item.cor_detectada || "")}"></label>
            <label>Tamanhos<input type="text" data-top100-curated-field="tamanho_detectado" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(item.tamanho_detectado || "")}"></label>
            <label>Preco<input type="text" data-top100-curated-field="preco_venda" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(String(item.preco_venda ?? ""))}"></label>
            <label>Prioridade
              <select data-top100-curated-field="prioridade_sugerida" data-top100-curated-id="${escapeHtml(item.id)}">
                ${["alta", "media", "baixa"].map((option) => `<option value="${option}" ${normalizeText(item.prioridade_sugerida).toLowerCase() === option ? "selected" : ""}>${option}</option>`).join("")}
              </select>
            </label>
            <label>Status
              <select data-top100-curated-field="status_sugerido" data-top100-curated-id="${escapeHtml(item.id)}">
                ${["ativo", "inativo"].map((option) => `<option value="${option}" ${normalizeText(item.status_sugerido).toLowerCase() === option ? "selected" : ""}>${option}</option>`).join("")}
              </select>
            </label>
            <label class="full">Tags<input type="text" data-top100-curated-field="tags_sugeridas" data-top100-curated-id="${escapeHtml(item.id)}" value="${escapeHtml(item.tags_sugeridas || "")}"></label>
            <label class="full">Descricao curta<textarea rows="2" data-top100-curated-field="descricao_curta_sugerida" data-top100-curated-id="${escapeHtml(item.id)}">${escapeHtml(item.descricao_curta_sugerida || "")}</textarea></label>
            <label class="full">Argumento de venda<textarea rows="2" data-top100-curated-field="argumento_venda_sugerido" data-top100-curated-id="${escapeHtml(item.id)}">${escapeHtml(item.argumento_venda_sugerido || "")}</textarea></label>
          </div>
          <div class="ai-curated-preview-actions">
            <label class="checkbox-field">
              <input type="checkbox" data-top100-curated-field="use_in_ai" data-top100-curated-id="${escapeHtml(item.id)}" ${item.use_in_ai ? "checked" : ""}>
              <span>Usar na Vitrine IA</span>
            </label>
            <label class="checkbox-field">
              <input type="checkbox" data-top100-curated-field="use_in_pos" data-top100-curated-id="${escapeHtml(item.id)}" ${item.use_in_pos ? "checked" : ""}>
              <span>Usar no PDV</span>
            </label>
          </div>
          <div class="ai-curated-preview-foot">
            <span><strong>Original:</strong> ${escapeHtml(item.nome_produto || "-")}</span>
            <span><strong>Preco:</strong> ${currency(item.preco_venda || 0)}</span>
            <span><strong>Estoque:</strong> ${escapeHtml(String(item.estoque ?? 0))}</span>
            <span><strong>Motivo:</strong> ${escapeHtml(item.motivo_recomendacao || "-")}</span>
          </div>
          ${item.warnings?.length ? `<div class="ai-curated-preview-warnings">${item.warnings.map((warning) => `<span class="pill-badge badge-warning-soft">${escapeHtml(warning)}</span>`).join("")}</div>` : ""}
        </article>
      `).join("")}
    </div>
  `;
}

async function loadAiStrategicProducts() {
  if (!canManageAiStrategicImport()) {
    state.aiStrategicProducts = [];
    return;
  }
  state.aiStrategicProducts = await api("/api/ia/products?includeInactive=1");
  renderAiStrategicProductsPanel();
}

async function loadTop100CuratedPreview() {
  const importState = ensureTop100CuratedImportState();
  importState.loading = true;
  importState.error = "";
  renderAiStrategicProductsPanel();
  try {
    const query = new URLSearchParams({
      updateExisting: importState.updateExisting ? "1" : "0",
      createCatalogs: importState.createCatalogs ? "1" : "0"
    });
    const response = await api(`/api/ia/vitrine-import/top100/preview?${query.toString()}`);
    importState.previewId = response.previewId || "";
    importState.summary = response.summary || null;
    importState.filePath = response.filePath || "";
    importState.items = toArray(response.preview).map(reconcileTop100CuratedPreviewItem);
    importState.lastResult = null;
    showFeedback("Previa do Top 100 curado carregada.");
  } catch (error) {
    importState.error = error.message || "Falha ao carregar a previa do Top 100 curado.";
    throw error;
  } finally {
    importState.loading = false;
    renderAiStrategicProductsPanel();
  }
}

function selectTop100CuratedFirstTwenty() {
  const importState = ensureTop100CuratedImportState();
  let count = 0;
  importState.items = toArray(importState.items).map((item) => {
    const selected = item.action !== "ignorar" && count < 20;
    if (selected) {
      count += 1;
    }
    return { ...item, selected };
  });
  renderAiStrategicProductsPanel();
  showFeedback("Primeiro lote recomendado com 20 produtos selecionados.");
}

function clearTop100CuratedSelection() {
  const importState = ensureTop100CuratedImportState();
  importState.items = toArray(importState.items).map((item) => ({ ...item, selected: false }));
  renderAiStrategicProductsPanel();
  showFeedback("Selecao do Top 100 curado limpa.");
}

function updateTop100CuratedItemField(itemId = "", field = "", value = "") {
  const importState = ensureTop100CuratedImportState();
  importState.items = toArray(importState.items).map((item) => {
    if (item.id !== itemId) {
      return item;
    }
    const next = {
      ...item,
      [field]: field === "use_in_ai" || field === "use_in_pos" || field === "selected" ? Boolean(value) : value
    };
    return reconcileTop100CuratedPreviewItem(next);
  });
  renderAiStrategicProductsPanel();
}

async function commitTop100CuratedSelection(forceLargeImport = false) {
  const importState = ensureTop100CuratedImportState();
  if (!importState.previewId) {
    showFeedback("Carregue a previa do Top 100 curado antes de importar.", "error");
    return;
  }
  const selectedItems = toArray(importState.items).filter((item) => item.selected);
  if (!selectedItems.length) {
    showFeedback("Selecione pelo menos um produto para importar.", "error");
    return;
  }
  if (selectedItems.length > 20 && !forceLargeImport) {
    const confirmed = window.confirm(`Voce selecionou ${selectedItems.length} produtos. Recomendamos ate 20 no primeiro lote. Deseja continuar mesmo assim?`);
    if (!confirmed) {
      return;
    }
  }
  importState.commitLoading = true;
  importState.error = "";
  renderAiStrategicProductsPanel();
  try {
    const response = await api("/api/ia/vitrine-import/top100/commit", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        previewId: importState.previewId,
        updateExisting: importState.updateExisting,
        createCatalogs: importState.createCatalogs,
        confirmLargeImport: selectedItems.length > 20,
        items: selectedItems
      })
    });
    importState.lastResult = response;
    showFeedback(`Importacao concluida: ${response.summary?.created || 0} criados, ${response.summary?.updated || 0} atualizados e ${response.summary?.skipped || 0} ignorados.`);
    await loadAiStrategicProducts();
    await loadTop100CuratedPreview();
  } catch (error) {
    importState.error = error.message || "Falha ao importar os produtos selecionados.";
    throw error;
  } finally {
    importState.commitLoading = false;
    renderAiStrategicProductsPanel();
  }
}

async function loadCashbackContactByPhone(phone) {
  const normalizedPhone = normalizePhone(phone);
  const data = await api(`/api/cashbacks/phone/${encodeURIComponent(normalizedPhone)}`);
  state.cashbackContact = data.contact;
  state.cashbackSummary = data.summary;
  state.cashbackRecords = data.cashbacks;
  state.cashbackEvents = data.events;
  renderCashbackCustomerCard();
  renderCashbackSummary();
  renderCashbackRecords();
  renderCashbackEvents();
  setCashbackContactSelectOptions([data.contact], false);
  document.getElementById("cashback-contact-id").value = String(data.contact.id);
  updateCashbackCustomerGender();
  if (document.getElementById("cashback-wizard-phone")) {
    document.getElementById("cashback-wizard-phone").value = formatPhoneBR(data.contact.phone || normalizedPhone);
  }
  if (document.getElementById("cashback-wizard-name")) {
    document.getElementById("cashback-wizard-name").value = data.contact.name || "";
  }
  document.getElementById("cashback-consult-phone").value = `${data.contact.name} - ${formatPhoneBR(data.contact.phone || normalizedPhone)}`;
  document.getElementById("cashback-consult-contact-id").value = String(data.contact.id);
  if (!data.cashbacks.length) {
    showFeedback("Cliente encontrado, mas sem cashback cadastrado.");
  }
  hideCashbackConsultSuggestions();
}

async function lookupCashbackPhone(force = false) {
  const phoneInput = document.getElementById("cashback-wizard-phone");
  const normalizedPhone = normalizePhone(phoneInput?.value || "");
  if (!normalizedPhone) {
    return;
  }
  try {
    await loadCashbackContactByPhone(normalizedPhone);
    document.getElementById("cashback-customer-hint").textContent = "Cliente encontrado. Agora informe o valor da compra.";
  } catch (error) {
    if (force) {
      showFeedback("Cliente não encontrado. Informe o nome para cadastro rápido.", "error");
    }
    state.cashbackContact = null;
    state.cashbackSummary = null;
    state.cashbackRecords = [];
    state.cashbackEvents = [];
    document.getElementById("cashback-contact-id").value = "";
    document.getElementById("cashback-customer-gender").value = "";
    document.getElementById("cashback-customer-hint").textContent = "Cliente não encontrado. Informe o nome para cadastro rápido.";
    renderCashbackCustomerCard();
    renderCashbackSummary();
    renderCashbackRecords();
    renderCashbackEvents();
  }
}

