function getContactPayload() {
  return {
    name: document.getElementById("contact-name").value.trim(),
    phone: normalizePhone(document.getElementById("contact-phone").value.trim()),
    gender: document.getElementById("contact-gender").value,
    store: document.getElementById("contact-store").value,
    sellerId: document.getElementById("contact-seller").value || null,
    status: document.getElementById("contact-status").value
  };
}

async function saveContact(event) {
  event.preventDefault();
  const id = document.getElementById("contact-id").value;
  const path = id ? `/api/contacts/${id}` : "/api/contacts";
  const method = id ? "PUT" : "POST";
  await api(path, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(getContactPayload())
  });
  fillContactForm();
  await Promise.all([loadContacts(getContactFilters("filter")), loadDashboard(), loadReports()]);
  showFeedback(id ? "Contato atualizado com sucesso." : "Contato salvo com sucesso.");
}

function renderContactImportPreview() {
  const wrapper = document.getElementById("contact-import-preview");
  const confirmButton = document.getElementById("confirm-import-button");
  const saleLabel = document.getElementById("contact-import-preview-sale-label");
  const cashbackLabel = document.getElementById("contact-import-preview-cashback-label");
  if (!state.contactImportPreview) {
    wrapper.classList.add("hidden");
    confirmButton.disabled = true;
    saleLabel.textContent = "Venda";
  cashbackLabel.textContent = "Bônus gerado";
    document.getElementById("contact-import-preview-stats").innerHTML = "";
    document.getElementById("contact-import-preview-table").innerHTML = "";
    document.getElementById("contact-import-preview-meta").textContent = "0 linhas";
    return;
  }

  const { summary, rows, importType } = state.contactImportPreview;
  wrapper.classList.remove("hidden");
  confirmButton.disabled = !summary.ready;
  saleLabel.textContent = importType === "bonus_perdido" ? "Valor da venda" : "Venda";
  cashbackLabel.textContent = importType === "bonus_perdido" ? "Bônus perdido" : "Bônus gerado";
  document.getElementById("contact-import-preview-meta").textContent = `${summary.total || 0} linhas analisadas`;
  document.getElementById("contact-import-preview-stats").innerHTML = [
    ["Prontas para importar", summary.ready || 0],
    ["Atualizações", summary.updates || 0],
    ["Duplicadas", summary.duplicates || 0],
    ["Ignoradas", summary.ignored || 0]
  ]
    .map(([label, value]) => `<div class="stat-card"><span>${label}</span><strong>${value}</strong></div>`)
    .join("");

  document.getElementById("contact-import-preview-table").innerHTML = rows.length
    ? rows.map((row) => {
      const badgeClass = row.invalid ? "ignored" : row.duplicate ? "duplicate" : row.action === "atualizar contato" ? "update" : "ready";
      const badgeLabel = row.invalid ? "Ignorada" : row.duplicate ? "Duplicada" : row.action === "atualizar contato" ? "Atualizar" : "Criar";
      return `
        <tr>
          <td>${row.line}</td>
          <td>${row.name || "-"}</td>
          <td>${formatPhoneBR(row.phone || "") || "-"}</td>
          <td>${currency(row.purchaseValue || 0)}</td>
          <td>${currency(row.cashbackValue || 0)}</td>
          <td>${row.sellerName || "-"}</td>
          <td>${formatDateBR(row.importDate || "") || "-"}</td>
          <td><span class="preview-badge ${badgeClass}">${badgeLabel}</span></td>
          <td>${row.note || "-"}</td>
        </tr>
      `;
    }).join("")
    : '<tr><td colspan="9">Nenhuma linha encontrada para pr?-visualiza?o.</td></tr>';
  enhanceTableScrolls();
}

function isLostBonusBatch(batch) {
  return String(batch?.source || "").toLowerCase().includes("bônus perdido") || String(batch?.source || "").toLowerCase().includes("bonus perdido");
}

function getCurrentImportBatchFilters() {
  return {
    status: document.getElementById("import-batch-filter-status")?.value || "",
    sellerName: document.getElementById("import-batch-filter-seller")?.value.trim() || "",
    dateFrom: document.getElementById("import-batch-filter-date-from")?.value || "",
    dateTo: document.getElementById("import-batch-filter-date-to")?.value || "",
    minCashback: document.getElementById("import-batch-filter-cashback")?.value || "",
    onlyNew: document.getElementById("import-batch-filter-new")?.value || ""
  };
}

function renderImportBatches() {
  const table = document.getElementById("import-batches-table");
  if (!table) {
    return;
  }
  table.innerHTML = state.importBatches.length
    ? state.importBatches.map((batch) => `
        <tr>
          <td>${formatDateBR(String(batch.created_at || "").slice(0, 10))}</td>
          <td>${batch.filename || "-"}</td>
          <td>${batch.total_rows || 0}</td>
          <td>${batch.contacts_created || 0}</td>
          <td>${batch.contacts_updated || 0}</td>
          <td>${batch.events_created || 0}</td>
          <td>${currency(batch.total_sales_value || 0)}</td>
          <td>${currency(batch.total_cashback_value || 0)}</td>
          <td>${batch.imported_by || "-"}</td>
          <td>${batch.status || "-"}</td>
          <td>
            <div class="table-actions">
              <button class="ghost-button" type="button" data-open-import-batch="${batch.id}">Abrir lote</button>
              <button class="ghost-button" type="button" data-open-import-errors="${batch.id}">Ver erros</button>
              <button class="ghost-button" type="button" data-create-import-campaign="${batch.id}" data-import-campaign-mode="all">Criar campanha</button>
              <button class="ghost-button" type="button" data-export-import-batch="${batch.id}">Exportar lote</button>
              <button class="secondary-button" type="button" data-undo-import-batch="${batch.id}">Desfazer</button>
            </div>
          </td>
        </tr>
      `).join("")
    : '<tr><td colspan="11">Nenhum lote de importação encontrado.</td></tr>';
  enhanceTableScrolls();
}

function renderImportBatchDetail() {
  const statsGrid = document.getElementById("import-batch-stats-grid");
  const table = document.getElementById("import-batch-items-table");
  const saleLabel = document.getElementById("import-batch-sale-label");
  const cashbackLabel = document.getElementById("import-batch-cashback-label");
  const dateLabel = document.getElementById("import-batch-date-label");
  if (!state.currentImportBatch) {
    statsGrid.innerHTML = "";
    saleLabel.textContent = "Venda";
  cashbackLabel.textContent = "Bônus gerado";
    dateLabel.textContent = "Data";
    table.innerHTML = '<tr><td colspan="10">Abra um lote para visualizar os dados importados.</td></tr>';
    enhanceTableScrolls();
    return;
  }

  const lostBatch = isLostBonusBatch(state.currentImportBatch.batch);
  const stats = state.currentImportBatch.stats || {};
  const averageLostTicket = Number(stats.imported_items || 0) > 0
    ? Number((Number(stats.total_cashback_value || 0) / Number(stats.imported_items || 1)).toFixed(2))
    : 0;
  statsGrid.innerHTML = [
    ["Total de linhas", stats.total_items || 0],
    ["Linhas importadas", stats.imported_items || 0],
    ["Linhas ignoradas", stats.ignored_items || 0],
    ["Clientes únicos", stats.unique_clients || 0],
    [lostBatch ? "Total de bônus perdido" : "Cashback total", currency(stats.total_cashback_value || 0)],
    [lostBatch ? "Maior bônus perdido" : "Maior cashback", currency(stats.highest_cashback || 0)],
    [lostBatch ? "Data inicial" : "Venda total", lostBatch ? (formatDateBR(stats.first_date || "") || "-") : currency(stats.total_sales_value || 0)],
    [lostBatch ? "Data final" : "Maior compra", lostBatch ? (formatDateBR(stats.last_date || "") || "-") : currency(stats.highest_sale || 0)],
    [lostBatch ? "Ticket médio perdido" : "Ticket médio", currency(lostBatch ? averageLostTicket : (stats.average_ticket || 0))]
  ].map(([label, value]) => `<div class="stat-card"><span>${label}</span><strong>${value}</strong></div>`).join("");

  saleLabel.textContent = lostBatch ? "Valor da venda" : "Venda";
  cashbackLabel.textContent = lostBatch ? "Valor perdido" : "Bônus gerado";
  dateLabel.textContent = lostBatch ? "Data em que perdeu" : "Data";

  const items = state.currentImportBatch.items || [];
  table.innerHTML = items.length
    ? items.map((item) => `
        <tr>
          <td>${item.customer_name || "-"}</td>
          <td>${formatPhoneBR(item.phone || "") || "-"}</td>
          <td>${currency(item.sale_value || 0)}</td>
          <td>${currency(item.cashback_value || 0)}</td>
          <td>${formatDateBR(item.sale_date || "") || "-"}</td>
          <td>${item.seller_name || "-"}</td>
          <td>${item.ticket || "-"}</td>
          <td>${item.nf || "-"}</td>
          <td>${item.status || "-"}</td>
          <td>${item.action || "-"}</td>
        </tr>
      `).join("")
    : '<tr><td colspan="10">Nenhum item encontrado para este lote.</td></tr>';
  enhanceTableScrolls();
}

async function loadImportBatches() {
  state.importBatches = await api("/api/import-batches");
  const audienceImportBatch = document.getElementById("audience-import-batch");
  if (audienceImportBatch) {
    const currentValue = audienceImportBatch.value || "";
    audienceImportBatch.innerHTML = ['<option value="">Todos</option>']
      .concat(state.importBatches.map((batch) => `<option value="${batch.id}">Lote ${batch.id} - ${batch.filename}</option>`))
      .join("");
    audienceImportBatch.value = currentValue;
  }
  renderImportBatches();
}

async function loadImportBatchDetail(batchId, filters = getCurrentImportBatchFilters()) {
  const query = new URLSearchParams();
  Object.entries(filters || {}).forEach(([key, value]) => {
    if (value !== "" && value !== null && value !== undefined) {
      query.set(key, value);
    }
  });
  state.currentImportBatch = await api(`/api/import-batches/${batchId}${query.toString() ? `?${query.toString()}` : ""}`);
  renderImportBatchDetail();
  setActiveSection("imports");
}

