async function useCashback(recordId) {
  const record = state.cashbackRecords.find((item) => item.id === Number(recordId));
  if (!record) {
    return;
  }
  const usedValue = promptText(`Quanto desejá usar do bônus de ${record.customer_name}?`, `${record.available_balance}`);
  if (usedValue === null) {
    return;
  }
  const purchaseValue = promptText("Informe o valor da compra atual:", `${record.minimum_purchase || 0}`);
  if (purchaseValue === null) {
    return;
  }
  const seller = promptText("Informe o vendedor responsável:", record.seller || "");
  if (seller === null) {
    return;
  }

  await api(`/api/cashbacks/${record.id}/use`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      usedValue: Number(usedValue),
      purchaseValue: Number(purchaseValue),
      seller
    })
  });
  await refreshCashbackAfterAction(record.customer_phone);
  showFeedback("B?nus usado com sucesso.");
}

async function cancelCashback(recordId) {
  const record = state.cashbackRecords.find((item) => item.id === Number(recordId));
  if (!record) {
    return;
  }
  const reason = promptText(`Motivo do cancelamento:\n${state.settings.cancelReasons.join("\n")}`, state.settings.cancelReasons[0]);
  if (reason === null) {
    return;
  }
  const seller = promptText("Informe o vendedor responsável:", record.seller || "");
  if (seller === null) {
    return;
  }

  await api(`/api/cashbacks/${record.id}/cancel`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ reason, seller })
  });
  await refreshCashbackAfterAction(record.customer_phone);
  showFeedback("B?nus cancelado com sucesso.");
}

async function reactivateCashback(recordId) {
  const record = state.cashbackRecords.find((item) => item.id === Number(recordId));
  if (!record) {
    return;
  }
  const confirmed = window.confirm(`Você desejá reativar o bônus do contato ${record.customer_name}?`);
  if (!confirmed) {
    return;
  }
  const pinPayload = await api(`/api/cashbacks/${record.id}/pin`, { method: "POST" });
  window.alert(`PIN gerado para reativa?o: ${pinPayload.pin}`);
  const pin = promptText("Informe o PIN de 4 dígitos:", "");
  if (pin === null) {
    return;
  }
  const seller = promptText("Informe o nome do vendedor responsável:", record.seller || "");
  if (seller === null) {
    return;
  }

  await api(`/api/cashbacks/${record.id}/reactivate`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      generatedPin: pinPayload.pin,
      pin,
      seller
    })
  });
  await refreshCashbackAfterAction(record.customer_phone);
  showFeedback("B?nus reativado com sucesso.");
}

