function cashbackWhatsappType(record) {
  if (record.status === "vencido") {
    return "perdido";
  }
  if (record.status === "disponivel" && record.expires_at && record.expires_at <= addDays(today(), 7)) {
    return "vencendo";
  }
  if (record.reactivated_at) {
    return "reativado";
  }
  return "gerado";
}

async function openCashbackWhatsapp(recordId) {
  const record = state.cashbackRecords.find((item) => item.id === Number(recordId))
    || state.currentCashbackAssistant?.record;
  if (!record) {
    return;
  }
  const isRecoverySegment = state.cashbackAssistantMode?.type === "segment"
    && state.currentCashbackAssistant?.record
    && Number(state.currentCashbackAssistant.record.contact_id || 0) === Number(record.contact_id || 0)
    && state.currentCashbackAssistant.record.segment_key;
  const payload = isRecoverySegment
    ? await api(`/api/cashback/recovery-segments/${state.cashbackAssistantMode.key}/whatsapp`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contactId: record.contact_id,
        seller: record.seller_name || record.seller || ""
      })
    })
    : await api(`/api/cashbacks/${record.id}/whatsapp`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        type: cashbackWhatsappType(record),
        seller: record.seller || ""
      })
    });
  window.open(payload.url, "_blank");
  await loadCashbackEvents(state.cashbackContact?.id || "");
  showFeedback("WhatsApp Web aberto para o cashback.");
}

async function loadCashbackEvents(contactId = "") {
  const query = contactId ? `?contactId=${contactId}` : "";
  state.cashbackEvents = await api(`/api/cashback/events${query}`);
  renderCashbackEvents();
}

async function loadNextCashbackAssistant(reset = false) {
  if (reset) {
    state.cashbackAssistantOffset = 0;
  }
  const filter = document.getElementById("cashback-assistant-filter").value;
  state.currentCashbackAssistant = state.cashbackAssistantMode?.type === "segment"
    ? await api(`/api/cashback/recovery-segments/${state.cashbackAssistantMode.key}/next?offset=${state.cashbackAssistantOffset}`)
    : await api(`/api/cashback/assistant/next?filter=${encodeURIComponent(filter)}&offset=${state.cashbackAssistantOffset}`);
  renderCashbackAssistantCard();
  showFeedback("Cliente de cashback preparado.");
}

async function createRecoveryCampaign(segmentKey) {
  const campaign = await api(`/api/cashback/recovery-segments/${segmentKey}/campaign`, {
    method: "POST",
    headers: { "Content-Type": "application/json" }
  });
  await Promise.all([loadCampaigns(), loadCampaignExecutionReport(), loadReports()]);
  showFeedback(`Campanha criada com ${campaign.selectedContactIds?.length || 0} cliente(s).`);
}

async function openRecoveryAssistant(segmentKey) {
  state.cashbackAssistantMode = { type: "segment", key: segmentKey };
  state.cashbackAssistantOffset = 0;
  await loadNextCashbackAssistant(true);
}

async function refreshCashbackAfterAction(phone) {
  await Promise.all([
    loadDashboard(),
    loadCashbackDashboard(),
    loadCashbackRecoverySegments(),
    loadContacts(getContactFilters("filter")),
    loadReports()
  ]);
  if (phone) {
    await loadCashbackContactByPhone(phone);
  }
}

async function generateVariation() {
  const base = document.getElementById("ai-base").value.trim();
  if (!base) {
    showFeedback("Informe uma mensagem base para gerar varia?o.", "error");
    return;
  }
  const result = await api("/api/ai/variation", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      base,
      style: document.getElementById("ai-style").value
    })
  });
  document.getElementById("ai-result").textContent = result.variation;
  showFeedback("Varia?o de mensagem gerada.");
}

