function handleDocumentChange(event) {
  const pdvCashTicketCheck = event.target.closest("[data-pdv-cash-ticket-check]");
  if (pdvCashTicketCheck) {
    updatePdvCashCloseTicketCheck(pdvCashTicketCheck.dataset.pdvCashTicketCheck || "", {
      render: false,
      checked: Boolean(pdvCashTicketCheck.checked)
    });
    syncPdvCashCloseTicketCardsState();
    syncPdvCashCloseModalValidationState();
    return;
  }

  const pdvCashCategorySelect = event.target.closest("[data-pdv-cash-category]");
  if (pdvCashCategorySelect) {
    updatePdvCashCloseCategory(pdvCashCategorySelect.value || "", { render: false });
    syncPdvCashCloseModalValidationState();
    return;
  }

  const activeStoreSelect = event.target.closest("[data-active-store-select]");
  if (activeStoreSelect) {
    changeActiveStore(activeStoreSelect.value).catch((error) => handleUiError("Erro ao trocar a loja ativa", error));
    return;
  }

  const pdvCashOpenStoreField = event.target.closest('[data-pdv-cash-open-field="loja"]');
  if (pdvCashOpenStoreField) {
    updatePdvCashOpenModalField("loja", pdvCashOpenStoreField.value || "");
    return;
  }

  const usersAdminRoleSelect = event.target.closest('[data-users-admin-form] select[name="role"]');
  if (usersAdminRoleSelect) {
    const form = usersAdminRoleSelect.closest("[data-users-admin-form]");
    const payload = readUsersAdminForm(form);
    const meta = getUsersAdminMeta();
    const profile = meta.profiles.find((item) => item.key === payload.role);
    state.usersAdmin.draft = {
      ...payload,
      permissions: profile?.default_permissions || payload.permissions
    };
    renderUsersAdminFront();
    return;
  }

  const usersAdminFilter = event.target.closest("[data-users-admin-filter]");
  if (usersAdminFilter) {
    const key = usersAdminFilter.dataset.usersAdminFilter || "";
    if (key === "role" || key === "status") {
      state.usersAdmin[key] = normalizeText(usersAdminFilter.value || "");
      if (key === "status") {
        loadUsersAdmin().catch((error) => handleUiError("Erro ao filtrar usuarios", error));
      } else {
        renderUsersAdminFront();
      }
    }
    return;
  }

  const pdvStockPageSize = event.target.closest("[data-pdv-stock-page-size]");
  if (pdvStockPageSize) {
    const nextPageSize = Number(pdvStockPageSize.value || 25);
    state.pdvStock.pagination = {
      page: 1,
      pageSize: PDV_STOCK_PAGE_SIZE_OPTIONS.includes(nextPageSize) ? nextPageSize : 25
    };
    loadPdvStockFront({ preserveSelection: false }).catch((error) => handleUiError("Erro ao paginar o estoque", error));
    return;
  }

  const pdvExchangeReason = event.target.closest("[data-pdv-exchange-reason]");
  if (pdvExchangeReason) {
    if (state.pdvExchanges.draft) {
      state.pdvExchanges.draft.reason = normalizeText(pdvExchangeReason.value || "");
    }
    renderPdvExchangesFront();
    return;
  }

  const pdvExchangeCondition = event.target.closest("[data-pdv-exchange-condition]");
  if (pdvExchangeCondition) {
    if (state.pdvExchanges.draft) {
      state.pdvExchanges.draft.returned_condition = normalizeText(pdvExchangeCondition.value || "");
    }
    renderPdvExchangesFront();
    return;
  }

  const pdvCockpitPeriod = event.target.closest("#pdv-cockpit-period");
  if (pdvCockpitPeriod) {
    state.pdvCockpit.filters.period = normalizeText(pdvCockpitPeriod.value || "30d").toLowerCase() || "30d";
    if (state.pdvCockpit.filters.period !== "custom") {
      state.pdvCockpit.filters.start_date = "";
      state.pdvCockpit.filters.end_date = "";
    }
    renderPdvReportsFront(document.getElementById("pdv-reports-content"));
    return;
  }

  const pdvCockpitCurveFilter = event.target.closest("#pdv-cockpit-curve-filter");
  if (pdvCockpitCurveFilter) {
    state.pdvCockpit.curveFilter = normalizeLookup(pdvCockpitCurveFilter.value || "");
    renderPdvReportsFront(document.getElementById("pdv-reports-content"));
    return;
  }

  const pdvCockpitCurveSortBy = event.target.closest("#pdv-cockpit-curve-sort-by");
  if (pdvCockpitCurveSortBy) {
    state.pdvCockpit.curveSortBy = normalizeText(pdvCockpitCurveSortBy.value || "total_revenue");
    renderPdvReportsFront(document.getElementById("pdv-reports-content"));
    return;
  }

  const pdvCockpitCurveSortDir = event.target.closest("#pdv-cockpit-curve-sort-dir");
  if (pdvCockpitCurveSortDir) {
    state.pdvCockpit.curveSortDir = normalizeText(pdvCockpitCurveSortDir.value || "desc");
    renderPdvReportsFront(document.getElementById("pdv-reports-content"));
    return;
  }

  const pdvCockpitStore = event.target.closest("#pdv-cockpit-store");
  if (pdvCockpitStore) {
    state.pdvCockpit.filters.store_id = String(pdvCockpitStore.value || "");
    return;
  }

  const pdvCockpitVendor = event.target.closest("#pdv-cockpit-vendor");
  if (pdvCockpitVendor) {
    state.pdvCockpit.filters.vendor_id = String(pdvCockpitVendor.value || "");
    return;
  }

  const top100CuratedToggle = event.target.closest("[data-top100-curated-select]");
  if (top100CuratedToggle?.dataset.top100CuratedSelect) {
    updateTop100CuratedItemField(
      top100CuratedToggle.dataset.top100CuratedSelect,
      "selected",
      Boolean(top100CuratedToggle.checked)
    );
    return;
  }

  const top100CuratedOption = event.target.closest("#top100-update-existing, #top100-create-catalogs");
  if (top100CuratedOption) {
    const importState = ensureTop100CuratedImportState();
    importState.updateExisting = Boolean(document.getElementById("top100-update-existing")?.checked);
    importState.createCatalogs = Boolean(document.getElementById("top100-create-catalogs")?.checked ?? true);
    reconcileTop100CuratedPreviewItems();
    return;
  }

  const top100CuratedField = event.target.closest("[data-top100-curated-field]");
  if (top100CuratedField?.dataset.top100CuratedId) {
    const field = top100CuratedField.dataset.top100CuratedField || "";
    const value = top100CuratedField.type === "checkbox" ? Boolean(top100CuratedField.checked) : top100CuratedField.value;
    updateTop100CuratedItemField(top100CuratedField.dataset.top100CuratedId, field, value);
    return;
  }

  const aerointelHighlightToggle = event.target.closest("[data-aerointel-highlight]");
  if (aerointelHighlightToggle?.dataset.aerointelHighlight) {
    ensureAerointelConversationState();
    const key = normalizeText(aerointelHighlightToggle.dataset.aerointelHighlight || "").toLowerCase();
    if (key) {
      state.aerointel.conversationsHighlights[key] = Boolean(aerointelHighlightToggle.checked);
      renderAeroIntelFront();
    }
    return;
  }

  const aerointelConversationPeriodField = event.target.closest('#aerointel-conversation-form select[name="period"]');
  if (aerointelConversationPeriodField) {
    ensureAerointelConversationState();
    state.aerointel.conversationsFilters.period = normalizeText(aerointelConversationPeriodField.value || "90d").toLowerCase() || "90d";
    renderAeroIntelFront();
    return;
  }

  const paymentAmountInput = event.target.closest("[data-pdv-payment-amount]");
  if (paymentAmountInput) {
    const perfToken = startAeroStorePerfMeasure("pdv.sale.payment_input_update", {
      method: normalizeText(paymentAmountInput.dataset.pdvPaymentAmount || "")
    });
    setPdvSalePaymentAmount(paymentAmountInput.dataset.pdvPaymentAmount, paymentAmountInput.value);
    updatePdvPaymentCardVisual(paymentAmountInput);
    endAeroStorePerfMeasure(perfToken);
    return;
  }

  const cashbackInput = event.target.closest("[data-pdv-sale-cashback-input]");
  if (cashbackInput) {
    setPdvSaleCashbackInput(cashbackInput.value);
    return;
  }

  const exchangeCreditInput = event.target.closest("[data-pdv-sale-exchange-credit-input]");
  if (exchangeCreditInput) {
    state.pdvSale.exchangeCreditInput = exchangeCreditInput.value;
    return;
  }

  const discountModeInput = event.target.closest("[data-pdv-sale-discount-mode]");
  if (discountModeInput) {
    state.pdvSale.discountDraft.mode = normalizeText(discountModeInput.value || "percent").toLowerCase() === "value" ? "value" : "percent";
    state.pdvSale.discountDraft.value = "";
    resetPdvSaleDiscountAuthorization();
    renderPdvSaleOfficialFront(document.getElementById("pdv-sale-content"));
    return;
  }

  const itemDiscountModeInput = event.target.closest("[data-pdv-sale-item-discount-mode]");
  if (itemDiscountModeInput) {
    const itemId = normalizeText(itemDiscountModeInput.dataset.pdvSaleItemDiscountMode || "");
    if (!itemId) return;
    state.pdvSale.itemDiscountDrafts = {
      ...(state.pdvSale.itemDiscountDrafts || {}),
      [itemId]: {
        ...(state.pdvSale.itemDiscountDrafts?.[itemId] || {}),
        mode: normalizeText(itemDiscountModeInput.value || "amount").toLowerCase() === "percent" ? "percent" : "amount",
        value: "",
        reason: normalizeText(state.pdvSale.itemDiscountDrafts?.[itemId]?.reason || "")
      }
    };
    renderPdvSaleOfficialFront(document.getElementById("pdv-sale-content"));
    return;
  }

  const discountAuthorizerInput = event.target.closest("[data-pdv-sale-discount-authorizer]");
  if (discountAuthorizerInput) {
    state.pdvSale.discountAuthorization.authorizerId = normalizeText(discountAuthorizerInput.value || "");
    state.pdvSale.discountAuthorization.error = "";
    return;
  }

  const permutaAuthorizerInput = event.target.closest("[data-pdv-sale-permuta-authorizer]");
  if (permutaAuthorizerInput) {
    state.pdvSale.permutaAuthorization.authorizerId = normalizeText(permutaAuthorizerInput.value || "");
    state.pdvSale.permutaAuthorization.error = "";
    return;
  }

  const paymentInstallmentsInput = event.target.closest("[data-pdv-payment-installments]");
  if (paymentInstallmentsInput) {
    const method = paymentInstallmentsInput.dataset.pdvPaymentInstallments;
    if (!method) {
      return;
    }
    const current = state.pdvSale.paymentDraft?.[method] || { amount: 0, installments: 1 };
    state.pdvSale.paymentDraft[method] = {
      amount: toNumber(current.amount),
      installments: getInstallmentCount(paymentInstallmentsInput.value || 1),
      installment_amount: getInstallmentAmount(current.amount, paymentInstallmentsInput.value || 1)
    };
    paymentInstallmentsInput.value = String(getInstallmentCount(paymentInstallmentsInput.value || 1));
    return;
  }

  const cashAuthorizerRoleInput = event.target.closest("[data-pdv-authorizer-role]");
  if (cashAuthorizerRoleInput) {
    state.pdvCash.authorizerDraft.role = normalizeText(cashAuthorizerRoleInput.value || "AUTORIZADOR");
    return;
  }

  const whatsappCrmCampaignMediaInput = event.target.closest("[data-whatsapp-crm-campaign-media]");
  if (whatsappCrmCampaignMediaInput) {
    refreshWhatsAppCrmCampaignMediaPreview(whatsappCrmCampaignMediaInput.files?.[0] || null).catch((error) => handleUiError("Erro ao montar o preview da midia", error));
    return;
  }

  const whatsappCrmCampaignSendType = event.target.closest('select[name="campaignSendType"]');
  if (whatsappCrmCampaignSendType) {
    ensureWhatsappCrmCampaignDraft();
    state.whatsappCrm.campaignDraft.sendType = normalizeText(whatsappCrmCampaignSendType.value || "text");
    if (state.whatsappCrm.campaignDraft.sendType === "text") {
      state.whatsappCrm.campaignDraft.caption = "";
      state.whatsappCrm.campaignDraft.mediaName = "";
      state.whatsappCrm.campaignDraft.mediaPreviewUrl = "";
      state.whatsappCrm.campaignDraft.mediaPreviewType = "";
      state.whatsappCrm.campaignDraft.mediaChanged = false;
    }
    renderWhatsAppRouteFront();
    return;
  }

  const whatsappCrmCampaignStore = event.target.closest('select[name="campaignStore"]');
  if (whatsappCrmCampaignStore) {
    ensureWhatsappCrmCampaignDraft();
    state.whatsappCrm.campaignDraft.store = normalizeText(whatsappCrmCampaignStore.value || "").toLowerCase();
    loadWhatsAppCrmCampaignAudienceEstimate({ render: true }).catch((error) => handleUiError("Erro ao validar o publico da campanha", error));
    return;
  }

  const whatsappCrmCampaignMode = event.target.closest('select[name="campaignMessageMode"]');
  if (whatsappCrmCampaignMode) {
    ensureWhatsappCrmCampaignDraft();
    state.whatsappCrm.campaignDraft.messageMode = normalizeText(whatsappCrmCampaignMode.value || "manual").toLowerCase() || "manual";
    renderWhatsAppRouteFront();
    return;
  }

  const whatsappCrmCampaignAudienceScope = event.target.closest('select[name="campaignAudienceScope"]');
  if (whatsappCrmCampaignAudienceScope) {
    ensureWhatsappCrmCampaignDraft();
    state.whatsappCrm.campaignDraft.audienceScope = normalizeText(whatsappCrmCampaignAudienceScope.value || "none").toLowerCase() || "none";
    if (state.whatsappCrm.campaignDraft.audienceScope === "store_whatsapp_valid") {
      state.whatsappCrm.campaignDraft.filters = {
        ...(state.whatsappCrm.campaignDraft.filters || {}),
        hasWhatsapp: "1"
      };
    }
    loadWhatsAppCrmCampaignAudienceEstimate({ render: true }).catch((error) => handleUiError("Erro ao validar o publico da campanha", error));
    return;
  }

  const whatsappCrmCampaignAudienceFilterField = event.target.closest('select[name="campaignAudienceGender"], select[name="campaignAudienceSellerId"], select[name="campaignAudienceTopSize"], select[name="campaignAudienceBottomSize"], select[name="campaignAudienceShoeSize"], select[name="campaignAudienceHasWhatsapp"]');
  if (whatsappCrmCampaignAudienceFilterField) {
    const formElement = whatsappCrmCampaignAudienceFilterField.closest('[data-whatsapp-crm-campaign-form="true"]');
    syncWhatsAppCrmCampaignDraftFromForm(formElement);
    loadWhatsAppCrmCampaignAudienceEstimate({ render: true }).catch((error) => handleUiError("Erro ao validar os filtros do publico", error));
    return;
  }

  const whatsappCrmAssistantField = event.target.closest("[data-whatsapp-crm-assistant-input]");
  if (whatsappCrmAssistantField) {
    ensureWhatsappCrmAssistantDraft();
    const field = whatsappCrmAssistantField.dataset.whatsappCrmAssistantInput || "";
    const value = String(whatsappCrmAssistantField.value || "").trim();
    state.whatsappCrm.assistantDraft[field] = field === "store" ? normalizeText(value).toLowerCase() : value;
    if (field === "store") {
      state.whatsappCrm.assistantDraft.sellerId = "";
      renderWhatsAppRouteFront();
      return;
    }
    if (field === "campaignId" || field === "tag" || field === "status" || field === "gender" || field === "sellerId" || field === "cashbackActive") {
      state.whatsappCrm.assistantPreview = null;
    }
    return;
  }
}

function handleDocumentInput(event) {
  const pdvCashCloseCountedInput = event.target.closest("[data-pdv-cash-counted-input]");
  if (pdvCashCloseCountedInput) {
    const previousMode = getPdvCashCloseDynamicMode(state.pdvCash.closeModal || {});
    const selectionStart = pdvCashCloseCountedInput.selectionStart;
    const selectionEnd = pdvCashCloseCountedInput.selectionEnd;
    updatePdvCashCloseCountedAmount(pdvCashCloseCountedInput.value || "", { render: false });
    const nextMode = getPdvCashCloseDynamicMode(state.pdvCash.closeModal || {});
    if (previousMode !== nextMode || !document.querySelector("[data-pdv-cash-difference-display]")) {
      renderPdvCashRegisterPreservingCloseField("[data-pdv-cash-counted-input]", selectionStart, selectionEnd);
    } else {
      syncPdvCashCloseLiveState();
    }
    return;
  }

  const pdvCashObservationInput = event.target.closest("[data-pdv-cash-observation]");
  if (pdvCashObservationInput) {
    updatePdvCashCloseObservation(pdvCashObservationInput.value || "", { render: false });
    syncPdvCashCloseModalValidationState();
    return;
  }

  const pdvCashJustificationInput = event.target.closest("[data-pdv-cash-justification]");
  if (pdvCashJustificationInput) {
    updatePdvCashCloseJustification(pdvCashJustificationInput.value || "", { render: false });
    syncPdvCashCloseModalValidationState();
    return;
  }

  const pdvCashOpenField = event.target.closest("[data-pdv-cash-open-field]");
  if (pdvCashOpenField) {
    updatePdvCashOpenModalField(pdvCashOpenField.dataset.pdvCashOpenField || "", pdvCashOpenField.value || "", { render: false });
    syncPdvCashOpenModalFormState(pdvCashOpenField);
    return;
  }

  const pdvCashMovementReasonInput = event.target.closest('[data-pdv-cash-movement-form] input[name="reason"]');
  if (pdvCashMovementReasonInput) {
    state.pdvCash.movementModal = {
      ...(state.pdvCash.movementModal || {}),
      reason: normalizeText(pdvCashMovementReasonInput.value || "")
    };
    state.pdvCash.movementError = "";
    return;
  }

  const usersAdminQuery = event.target.closest('[data-users-admin-filter="query"]');
  if (usersAdminQuery) {
    state.usersAdmin.query = normalizeText(usersAdminQuery.value || "");
    clearTimeout(state.usersAdmin.searchTimer);
    state.usersAdmin.searchTimer = setTimeout(() => {
      loadUsersAdmin().catch((error) => handleUiError("Erro ao buscar usuarios", error));
    }, 250);
    return;
  }

  const pdvCockpitCurveSearch = event.target.closest("#pdv-cockpit-curve-search");
  if (pdvCockpitCurveSearch) {
    state.pdvCockpit.curveSearch = String(pdvCockpitCurveSearch.value || "");
    clearTimeout(state.pdvCockpit.curveSearchDebounce);
    state.pdvCockpit.curveSearchDebounce = setTimeout(() => {
      if (!isPdvCockpitRoute()) {
        return;
      }
      renderPdvReportsFront(document.getElementById("pdv-reports-content"));
    }, 180);
    return;
  }

  const pdvCockpitProductSearch = event.target.closest("#pdv-cockpit-product-search");
  if (pdvCockpitProductSearch) {
    state.pdvCockpit.filters.product_search = String(pdvCockpitProductSearch.value || "");
    clearTimeout(state.pdvCockpit.productSearchDebounce);
    state.pdvCockpit.productSearchDebounce = setTimeout(() => {
      if (!isPdvCockpitRoute()) {
        return;
      }
      loadPdvCockpitData({ resetCurve: true }).catch((error) => handleUiError("Erro ao buscar produto no Cockpit", error));
    }, 450);
    return;
  }

  const pdvCockpitBrand = event.target.closest("#pdv-cockpit-brand");
  if (pdvCockpitBrand) {
    state.pdvCockpit.filters.brand = String(pdvCockpitBrand.value || "");
    return;
  }

  const pdvCockpitCategory = event.target.closest("#pdv-cockpit-category");
  if (pdvCockpitCategory) {
    state.pdvCockpit.filters.category = String(pdvCockpitCategory.value || "");
    return;
  }

  const pdvCockpitStartDate = event.target.closest("#pdv-cockpit-start-date");
  if (pdvCockpitStartDate) {
    state.pdvCockpit.filters.start_date = String(pdvCockpitStartDate.value || "");
    return;
  }

  const pdvCockpitEndDate = event.target.closest("#pdv-cockpit-end-date");
  if (pdvCockpitEndDate) {
    state.pdvCockpit.filters.end_date = String(pdvCockpitEndDate.value || "");
    return;
  }

  const cashbackInput = event.target.closest("[data-pdv-sale-cashback-input]");
  if (cashbackInput) {
    state.pdvSale.cashbackInput = String(cashbackInput.value || "");
    return;
  }

  const pdvSaleCustomerSearchInput = event.target.closest("#pdv-sale-customer-search");
  if (pdvSaleCustomerSearchInput) {
    const nextQuery = String(pdvSaleCustomerSearchInput.value || "");
    if (nextQuery !== String(state.pdvSale.customerQuery || "")) {
      state.pdvSale.customerQuery = nextQuery;
      state.pdvSale.customerSearchError = "";
      if (state.pdvSale.customerSearching) {
        state.pdvSale.customerSearchRequestId = Number(state.pdvSale.customerSearchRequestId || 0) + 1;
        state.pdvSale.customerSearching = false;
      }
      schedulePdvSaleCustomerSearch();
    }
    return;
  }

  const discountValueInput = event.target.closest("[data-pdv-sale-discount-value]");
  if (discountValueInput) {
    state.pdvSale.discountDraft.value = String(discountValueInput.value || "");
    state.pdvSale.generalDiscountBlock = null;
    resetPdvSaleDiscountAuthorization();
    return;
  }

  const discountReasonInput = event.target.closest("[data-pdv-sale-discount-note]");
  if (discountReasonInput) {
    state.pdvSale.discountDraft.reason = String(discountReasonInput.value || "");
    return;
  }

  const itemDiscountValueInput = event.target.closest("[data-pdv-sale-item-discount-value]");
  if (itemDiscountValueInput) {
    const itemId = normalizeText(itemDiscountValueInput.dataset.pdvSaleItemDiscountValue || "");
    if (!itemId) return;
    state.pdvSale.itemDiscountDrafts = {
      ...(state.pdvSale.itemDiscountDrafts || {}),
      [itemId]: {
        ...(state.pdvSale.itemDiscountDrafts?.[itemId] || {}),
        value: String(itemDiscountValueInput.value || "")
      }
    };
    resetPdvSaleDiscountAuthorization();
    return;
  }

  const itemDiscountReasonInput = event.target.closest("[data-pdv-sale-item-discount-reason]");
  if (itemDiscountReasonInput) {
    const itemId = normalizeText(itemDiscountReasonInput.dataset.pdvSaleItemDiscountReason || "");
    if (!itemId) return;
    state.pdvSale.itemDiscountDrafts = {
      ...(state.pdvSale.itemDiscountDrafts || {}),
      [itemId]: {
        ...(state.pdvSale.itemDiscountDrafts?.[itemId] || {}),
        reason: String(itemDiscountReasonInput.value || "")
      }
    };
    return;
  }

  const discountAuthorizationCodeInput = event.target.closest("[data-pdv-sale-discount-code]");
  if (discountAuthorizationCodeInput) {
    state.pdvSale.discountAuthorization.code = String(discountAuthorizationCodeInput.value || "").replace(/\D/g, "").slice(0, 6);
    state.pdvSale.discountAuthorization.error = "";
    return;
  }

  const permutaAuthorizationCodeInput = event.target.closest("[data-pdv-sale-permuta-code]");
  if (permutaAuthorizationCodeInput) {
    state.pdvSale.permutaAuthorization.code = String(permutaAuthorizationCodeInput.value || "").replace(/\D/g, "").slice(0, 6);
    state.pdvSale.permutaAuthorization.error = "";
    return;
  }

  const pdvExchangeNotesInput = event.target.closest("[data-pdv-exchange-notes]");
  if (pdvExchangeNotesInput && state.pdvExchanges.draft) {
    state.pdvExchanges.draft.reason_notes = String(pdvExchangeNotesInput.value || "");
    return;
  }

  const postSaleWhatsappPhoneInput = event.target.closest("[data-pdv-sale-whatsapp-phone]");
  if (postSaleWhatsappPhoneInput) {
    state.pdvSale.postSaleManualPhone = String(postSaleWhatsappPhoneInput.value || "");
    if (state.pdvSale.postSaleWhatsAppStatus === "error") {
      state.pdvSale.postSaleWhatsAppStatus = "";
    }
    return;
  }

  const cashAuthorizerNameInput = event.target.closest("[data-pdv-authorizer-name]");
  if (cashAuthorizerNameInput) {
    state.pdvCash.authorizerDraft.name = String(cashAuthorizerNameInput.value || "");
    return;
  }

  const cashAuthorizerNotesInput = event.target.closest("[data-pdv-authorizer-notes]");
  if (cashAuthorizerNotesInput) {
    state.pdvCash.authorizerDraft.notes = String(cashAuthorizerNotesInput.value || "");
    return;
  }

  const cashAuthorizerSetupCodeInput = event.target.closest("[data-pdv-authorizer-setup-code]");
  if (cashAuthorizerSetupCodeInput) {
    state.pdvCash.authorizerSetupCode = String(cashAuthorizerSetupCodeInput.value || "").replace(/\D/g, "").slice(0, 6);
    return;
  }

  const audienceSearchField = event.target.closest('input[name="campaignAudienceSearchQuery"]');
  if (audienceSearchField) {
    state.whatsappCrm.campaignAudienceSearchQuery = String(audienceSearchField.value || "").trim();
    state.whatsappCrm.campaignAudienceSearchError = "";
    return;
  }

  const assistantField = event.target.closest("[data-whatsapp-crm-assistant-input]");
  if (assistantField) {
    ensureWhatsappCrmAssistantDraft();
    const field = assistantField.dataset.whatsappCrmAssistantInput || "";
    const value = field === "base" ? String(assistantField.value || "") : String(assistantField.value || "").trim();
    state.whatsappCrm.assistantDraft[field] = field === "store" ? normalizeText(value).toLowerCase() : value;
    if (field === "base") {
      state.whatsappCrm.assistantDraft.source = "literal";
      state.whatsappCrm.assistantDraft.result = "";
      const previewNode = document.querySelector(".whatsapp-crm-literal-preview");
      if (previewNode) {
        previewNode.textContent = String(value || "").trim() || "Use um template, escreva uma base manual ou simule o proximo contato para ver o preview aqui.";
      }
    }
    return;
  }

  const previewField = event.target.closest("[data-whatsapp-crm-preview-input]");
  if (!previewField) {
    return;
  }
  ensureWhatsappCrmCampaignDraft();
  if (previewField.name === "campaignMessage") {
    state.whatsappCrm.campaignDraft.message = String(previewField.value || "").trim();
    state.whatsappCrm.campaignDraft.messageMode = "manual";
    state.whatsappCrm.campaignDraft.templateSource = "literal";
    const previewNode = document.querySelector(".whatsapp-crm-literal-preview");
    if (previewNode) {
      previewNode.textContent = state.whatsappCrm.campaignDraft.message || "Digite a mensagem da campanha para ver o preview exato aqui.";
    }
  }
  if (previewField.name === "campaignCaption") {
    state.whatsappCrm.campaignDraft.caption = String(previewField.value || "").trim();
    const captionNode = document.querySelector(".whatsapp-crm-preview-caption");
    if (captionNode) {
      captionNode.textContent = state.whatsappCrm.campaignDraft.caption || "";
    }
  }
}

function handleDocumentFocusout(event) {
  const pdvCashCloseCountedInput = event.target.closest?.("[data-pdv-cash-counted-input]");
  if (pdvCashCloseCountedInput) {
    formatPdvCashCloseCountedInputField(pdvCashCloseCountedInput);
    return;
  }

  const cashbackInput = event.target.closest?.("[data-pdv-sale-cashback-input]");
  if (cashbackInput) {
    formatPdvSaleCashbackInputField(cashbackInput);
    return;
  }

  const discountValueInput = event.target.closest?.("[data-pdv-sale-discount-value]");
  if (discountValueInput) {
    if ((state.pdvSale.discountDraft?.mode || "percent") === "value") {
      const parsed = parseMoneyAmount(discountValueInput.value || 0);
      state.pdvSale.discountDraft.value = parsed > 0 ? formatMoneyAmountInput(parsed) : "";
      renderPdvSaleOfficialFront(document.getElementById("pdv-sale-content"));
    }
    return;
  }

  const itemDiscountValueInput = event.target.closest?.("[data-pdv-sale-item-discount-value]");
  if (itemDiscountValueInput) {
    const itemId = normalizeText(itemDiscountValueInput.dataset.pdvSaleItemDiscountValue || "");
    const draft = state.pdvSale.itemDiscountDrafts?.[itemId] || {};
    if (itemId && normalizeText(draft.mode || "amount").toLowerCase() !== "percent") {
      const parsed = parseMoneyAmount(itemDiscountValueInput.value || 0);
      state.pdvSale.itemDiscountDrafts = {
        ...(state.pdvSale.itemDiscountDrafts || {}),
        [itemId]: {
          ...draft,
          value: parsed > 0 ? formatMoneyAmountInput(parsed) : ""
        }
      };
      renderPdvSaleOfficialFront(document.getElementById("pdv-sale-content"));
    }
    return;
  }

  const paymentAmountInput = event.target.closest?.("[data-pdv-payment-amount]");
  if (paymentAmountInput) {
    const perfToken = startAeroStorePerfMeasure("pdv.sale.payment_field_commit", {
      method: normalizeText(paymentAmountInput.dataset.pdvPaymentAmount || "")
    });
    formatPdvPaymentAmountField(paymentAmountInput);
    endAeroStorePerfMeasure(perfToken);
    return;
  }

  const paymentInstallmentsInput = event.target.closest?.("[data-pdv-payment-installments]");
  if (paymentInstallmentsInput) {
    const method = normalizeText(paymentInstallmentsInput.dataset.pdvPaymentInstallments || "");
    if (!method) return;
    const current = getPdvPaymentDraftEntry(method);
    const installments = getInstallmentCount(paymentInstallmentsInput.value || 1);
    paymentInstallmentsInput.value = String(installments);
    setPdvSalePaymentAmount(method, current.amount, installments);
    syncPdvPaymentDraftField(method);
  }
}

function handleDocumentKeydown(event) {
  const pdvProductsQueryInput = event.target.closest?.("[data-pdv-products-query-input]");
  if (pdvProductsQueryInput && event.key === "Enter" && !event.isComposing) {
    event.preventDefault();
    if (event.repeat) return;
    const form = pdvProductsQueryInput.closest("[data-pdv-products-search-form]");
    if (form) {
      runPdvProductsSearchFromForm(form, { preserveSelection: false }).catch((error) => handleUiError("Erro ao buscar produtos operacionais", error));
    }
    return;
  }

  const pdvProductSearchInput = event.target.closest?.('input[name="pdv_query_search_product_v2"]');
  if (pdvProductSearchInput && event.key === "Enter" && !event.isComposing) {
    event.preventDefault();
    if (event.repeat) return;
    state.pdvSale.productQuery = normalizeText(pdvProductSearchInput.value || "");
    searchPdvSaleProducts().catch((error) => handleUiError("Erro ao buscar produtos da venda", error));
    return;
  }
  const successSale = state.pdvSale.lastCompletedSale;
  const isPdvSaleRoute = window.location.pathname.startsWith("/pdv/venda");
  const hasPostSaleActions = Boolean(document.querySelector("[data-pdv-sale-new-session]"));
  const isTypingTarget = ["INPUT", "TEXTAREA", "SELECT"].includes(event.target?.tagName)
    || Boolean(event.target?.isContentEditable);
  if (successSale && isPdvSaleRoute && hasPostSaleActions && !event.ctrlKey && !event.metaKey && !event.altKey) {
    if ((event.key === "Enter" || event.key === "F2") && !isTypingTarget) {
      event.preventDefault();
      startNewPdvSaleSession().catch((error) => handleUiError("Erro ao iniciar uma nova venda", error));
      return;
    }
    if ((event.key === "p" || event.key === "P") && !isTypingTarget) {
      event.preventDefault();
      printPdvSaleReceipt(successSale.sale_id || "");
      return;
    }
  }

  const cashbackInput = event.target.closest?.("[data-pdv-sale-cashback-input]");
  if (cashbackInput && event.key === "Tab") {
    formatPdvSaleCashbackInputField(cashbackInput);
    return;
  }

  const paymentAmountInput = event.target.closest?.("[data-pdv-payment-amount]");
  if (paymentAmountInput && event.key === "Tab") {
    formatPdvPaymentAmountField(paymentAmountInput);
    return;
  }

  const paymentInstallmentsInput = event.target.closest?.("[data-pdv-payment-installments]");
  if (paymentInstallmentsInput && event.key === "Tab") {
    const method = normalizeText(paymentInstallmentsInput.dataset.pdvPaymentInstallments || "");
    if (!method) return;
    const current = getPdvPaymentDraftEntry(method);
    const installments = getInstallmentCount(paymentInstallmentsInput.value || 1);
    paymentInstallmentsInput.value = String(installments);
    setPdvSalePaymentAmount(method, current.amount, installments);
  }
}

async function bootstrap() {
  applyRolePermissions();
  const activeRouteSection = document.body.dataset.routeSection || getInitialSection();
  const fastFirstPaint = OFFICIAL_PDV_SECTIONS.has(activeRouteSection);
  if (activeRouteSection === "cashback") {
    renderCashbackSummary();
    renderCashbackCustomerCard();
    renderCashbackAssistantCard();
    renderCashbackWizardSummary();
    setTimeout(() => {
      bootstrapBackgroundWork(null, { renderActiveRoute: false }).catch((error) => {
        console.warn("[AEROSTORE CRM] Bootstrap cashback em segundo plano com pendencias", error);
      });
    }, 400);
    return;
  }
  const settingsPromise = loadSettings();
  settingsPromise.catch(() => {});
  if (fastFirstPaint) {
    const activePage = document.querySelector(".page.active");
    if (!activePage || !normalizeText(activePage.textContent || "")) {
      renderOfficialRouteSection(activeRouteSection);
    }
    setTimeout(() => {
      bootstrapBackgroundWork(settingsPromise, { renderActiveRoute: false }).catch((error) => {
        console.warn("[AEROSTORE CRM] Bootstrap em segundo plano com pendencias", error);
      });
    }, 800);
    return;
  }
  await settingsPromise;
  applyCashbackReportPreset(state.cashbackReports.filters.preset || "today", { resetPage: false });
  const bootstrapTasks = [
    ["configuracao da loja", () => canViewRealStoreSettings() ? loadStoreSettingsCatalog() : Promise.resolve()],
    ["vendedores", () => canViewSettingsTeamPanel() ? loadSellers() : Promise.resolve()],
    ["contatos", () => loadContacts()],
    ["batches de importação", () => loadImportBatches()],
    ["públicos salvos", () => loadSavedAudiences()],
    ["campanhas", () => loadCampaigns()],
    ["execução de campanhas", () => loadCampaignExecutionReport()],
    ["templates de IA", () => loadAiTemplates()],
    ["produtos estratégicos", () => canManageAiStrategicImport() ? loadAiStrategicProducts() : Promise.resolve()],
    ["dashboard", () => loadDashboard()],
    ["cashback", () => loadCashbackDashboard()],
    ["recuperação de cashback", () => loadCashbackRecoverySegments()],
    ["eventos de cashback", () => loadCashbackEvents()],
    ["relatórios", () => loadReports()],
    ["perda de cashback", () => loadLostCashbackReport()],
    ["status do WhatsApp", () => loadWhatsAppStatus()]
  ];
  const bootstrapResults = await Promise.allSettled(bootstrapTasks.map(([, task]) => task()));
  const failedTasks = bootstrapResults
    .map((result, index) => ({ result, label: bootstrapTasks[index][0] }))
    .filter(({ result }) => result.status === "rejected");
  document.getElementById("cashback-expires-at").value = formatDateBR(addDays(today(), state.settings.defaultValidityDays));
  updateCashbackCustomerGender();
  renderCashbackSummary();
  renderCashbackCustomerCard();
  renderCashbackAssistantCard();
  renderCashbackWizardSummary();
  renderContactImportPreview();
  renderAudienceResults();
  renderOfficialRouteSection(document.body.dataset.routeSection || getInitialSection());
  enhanceTableScrolls();
  if (failedTasks.length) {
    console.warn("[AEROSTORE CRM] Bootstrap parcial", failedTasks.map((item) => item.label));
    showFeedback(`Sistema carregado com ajustes pendentes em ${failedTasks.map((item) => item.label).join(", ")}.`, "warning");
    return;
  }
  showFeedback("Sistema carregado com sucesso.");
}

async function bootstrapBackgroundWork(settingsPromise = null, { renderActiveRoute = false } = {}) {
  const failedTasks = [];
  try {
    if (settingsPromise) {
      await settingsPromise;
    } else {
      await loadSettings();
    }
    applyCashbackReportPreset(state.cashbackReports.filters.preset || "today", { resetPage: false });
  } catch (error) {
    failedTasks.push({ label: "configuracoes", error });
  }
  const bootstrapTasks = [
    ["configuracao da loja", () => canViewRealStoreSettings() ? loadStoreSettingsCatalog() : Promise.resolve()],
    ["vendedores", () => canViewSettingsTeamPanel() ? loadSellers() : Promise.resolve()],
    ["contatos", () => loadContacts()],
    ["batches de importacao", () => loadImportBatches()],
    ["publicos salvos", () => loadSavedAudiences()],
    ["campanhas", () => loadCampaigns()],
    ["execucao de campanhas", () => loadCampaignExecutionReport()],
    ["templates de IA", () => loadAiTemplates()],
    ["produtos estrategicos", () => canManageAiStrategicImport() ? loadAiStrategicProducts() : Promise.resolve()],
    ["dashboard", () => loadDashboard()],
    ["cashback", () => loadCashbackDashboard()],
    ["recuperacao de cashback", () => loadCashbackRecoverySegments()],
    ["eventos de cashback", () => loadCashbackEvents()],
    ["relatorios", () => loadReports()],
    ["perda de cashback", () => loadLostCashbackReport()],
    ["status do WhatsApp", () => loadWhatsAppStatus()]
  ];
  const bootstrapResults = await Promise.allSettled(bootstrapTasks.map(([, task]) => task()));
  failedTasks.push(...bootstrapResults
    .map((result, index) => ({ result, label: bootstrapTasks[index][0] }))
    .filter(({ result }) => result.status === "rejected"));
  const expiresAtField = document.getElementById("cashback-expires-at");
  if (expiresAtField) {
    expiresAtField.value = formatDateBR(addDays(today(), state.settings.defaultValidityDays));
  }
  updateCashbackCustomerGender();
  renderCashbackSummary();
  renderCashbackCustomerCard();
  renderCashbackAssistantCard();
  renderCashbackWizardSummary();
  renderContactImportPreview();
  renderAudienceResults();
  if (renderActiveRoute) {
    renderOfficialRouteSection(document.body.dataset.routeSection || getInitialSection());
  }
  enhanceTableScrolls();
  if (failedTasks.length) {
    console.warn("[AEROSTORE CRM] Bootstrap parcial", failedTasks.map((item) => item.label));
  }
}

