/* ---- Sidebar Toggle (ChatGPT-inspired) ---- */
const SIDEBAR_COLLAPSED_KEY = "aerostore.sidebar.collapsed";
const SIDEBAR_COLLAPSED_LEGACY_KEY = "aerostore_sidebar_collapsed";

function isSidebarCollapsed() {
  try {
    return localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === "1" || localStorage.getItem(SIDEBAR_COLLAPSED_LEGACY_KEY) === "1";
  } catch (_) {
    return false;
  }
}

function setSidebarCollapsed(collapsed) {
  const isCollapsed = Boolean(collapsed);
  document.body.classList.toggle("sidebar-collapsed", isCollapsed);

  const collapseBtn = document.getElementById("sidebar-toggle-btn");
  const expandBtn = document.getElementById("sidebar-expand-btn");

  if (collapseBtn) {
    collapseBtn.setAttribute("aria-label", isCollapsed ? "Expandir barra lateral" : "Recolher barra lateral");
    collapseBtn.setAttribute("title", isCollapsed ? "Expandir barra lateral" : "Recolher barra lateral");
  }
  if (expandBtn) {
    expandBtn.setAttribute("aria-label", isCollapsed ? "Expandir barra lateral" : "Recolher barra lateral");
    expandBtn.setAttribute("title", isCollapsed ? "Expandir barra lateral" : "Recolher barra lateral");
  }

  try {
    if (isCollapsed) {
      localStorage.setItem(SIDEBAR_COLLAPSED_KEY, "1");
    } else {
      localStorage.removeItem(SIDEBAR_COLLAPSED_KEY);
    }
    localStorage.removeItem(SIDEBAR_COLLAPSED_LEGACY_KEY);
  } catch (_) {
    /* localStorage may be unavailable */
  }
}

function toggleSidebar() {
  setSidebarCollapsed(!document.body.classList.contains("sidebar-collapsed"));
}

let _sidebarToggleBound = false;

function initSidebarToggle() {
  // Restore persisted state
  setSidebarCollapsed(isSidebarCollapsed());

  // Bind listeners once (idempotent)
  if (_sidebarToggleBound) {
    return;
  }
  _sidebarToggleBound = true;

  const collapseBtn = document.getElementById("sidebar-toggle-btn");
  const expandBtn = document.getElementById("sidebar-expand-btn");

  if (collapseBtn) {
    collapseBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      toggleSidebar();
    });
  }

  if (expandBtn) {
    expandBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      toggleSidebar();
    });
  }
}

function initApp() {
  sectionTitle = document.getElementById("section-title");
  feedback = document.getElementById("feedback");
  loadSavedTheme();
  ensureLoginOverlayAuthGuard();
  initSidebarToggle();
  bindEvents();
  ensureMojibakeObserver();
  normalizeVisibleMojibake(document.body);
  syncAuthShellState();
  showLoginOverlay("__checking__");
  window.addEventListener("hashchange", () => {
    if (state.authLoading) {
      return;
    }
    const nextSection = getInitialSection();
    if (!state.currentUser && nextSection === "access-denied") {
      redirectToLogin();
      showLoginOverlay("Faça login para acessar esta área do sistema.");
      return;
    }
    if (document.querySelector(".page.active")?.id !== nextSection) {
      setActiveSection(nextSection);
    }
  });
  restoreSession().then((isAuthenticated) => {
    if (!isAuthenticated) {
      return;
    }
    if (normalizePathname(window.location.pathname || "/") === "/login") {
      window.history.replaceState({}, "", getDefaultRouteForCurrentUser());
    }
    const nextSection = getInitialSection();
    if (nextSection === "access-denied") {
      renderAccessDeniedState();
    }
    setActiveSection(nextSection);
    bootstrap().catch((error) => handleUiError("Erro ao carregar sistema", error));
  });
}

async function loadWhatsAppStatus() {
  if (!state.isAuthenticated && !state.currentUser) {
    return;
  }
  try {
    const response = await api('/api/whatsapp/status');
    state.whatsappStatus = response.status;
    state.whatsappConnectedNumber = response.connectedNumber;
    state.whatsappLastConnectedAt = response.lastConnectedAt;
    state.whatsappLastError = response.lastError;
    state.whatsappHasQr = response.hasQr;
    updateWhatsAppUI(response);
  } catch (error) {
    state.whatsappStatus = 'desconectado';
    state.whatsappConnectedNumber = null;
    state.whatsappLastConnectedAt = null;
    state.whatsappLastError = null;
    state.whatsappHasQr = false;
    updateWhatsAppUI({ status: 'desconectado' });
    console.warn('Status do WhatsApp indisponível neste momento.', error?.message || error);
  }
}

function updateWhatsAppUI(data) {
  const statusIcon = document.getElementById('whatsapp-status-icon');
  const statusText = document.getElementById('whatsapp-status-text');
  const qrSection = document.getElementById('whatsapp-qr-section');
  const qrImage = document.getElementById('whatsapp-qr-code');
  const waitingQr = data.status === 'aguardando qr' || data.status === 'aguardando_qr';
  const qrPending = data.status === 'qr_pendente';
  const onWhatsappCrmRoute = document.body.dataset.routeSection === "whatsapp-crm" || document.body.dataset.section === "whatsapp-crm";

  if (statusIcon && statusText) {
    if (data.status === 'conectado') {
      statusIcon.textContent = '🟢';
      statusText.textContent = `Conectado${data.connectedNumber ? ` (${data.connectedNumber})` : ''}`;
      stopWhatsAppPolling();
    } else if (waitingQr) {
      statusIcon.textContent = '🟡';
      statusText.textContent = 'Aguardando leitura do QR Code';
      if (!onWhatsappCrmRoute) {
        startWhatsAppPolling();
        loadWhatsAppQr();
      } else {
        stopWhatsAppPolling();
      }
    } else if (qrPending) {
      statusIcon.textContent = '🟡';
      statusText.textContent = 'QR protegido. Clique em Abrir QR para conectar.';
      stopWhatsAppPolling();
    } else if (data.status === 'erro') {
      statusIcon.textContent = '🔴';
      statusText.textContent = `Erro: ${data.lastError || 'Desconhecido'}`;
      stopWhatsAppPolling();
    } else {
      statusIcon.textContent = '🔴';
      statusText.textContent = 'Desconectado';
      stopWhatsAppPolling();
    }
  }

  if (qrSection && qrImage) {
    if (waitingQr && state.whatsappHasQr && !onWhatsappCrmRoute) {
      loadWhatsAppQr();
    } else {
      qrSection.style.display = 'none';
    }
  }
  if (document.body.dataset.routeSection === "whatsapp-crm" || document.body.dataset.section === "whatsapp-crm") {
    state.whatsappCrm.statusData = {
      ...(state.whatsappCrm.statusData || {}),
      ...data
    };
    renderWhatsAppRouteFront();
  }
  renderSettingsWorkspace();
}
async function loadWhatsAppQr() {
  try {
    const response = await api('/api/whatsapp/qr');
    state.whatsappCrm.qrData = response;
    if (response.status === 'aguardando qr' && response.qrBase64) {
      const qrImage = document.getElementById('whatsapp-qr-code');
      const qrSection = document.getElementById('whatsapp-qr-section');
      if (qrImage && qrSection) {
        qrImage.src = response.qrBase64;
        qrSection.style.display = 'block';
      }
    }
    if (document.body.dataset.routeSection === "whatsapp-crm" || document.body.dataset.section === "whatsapp-crm") {
      renderWhatsAppRouteFront();
    }
  } catch (error) {
    console.error('Erro ao carregar QR do WhatsApp:', error);
  }
}

function startWhatsAppPolling() {
  stopWhatsAppPolling();
  whatsappStatusInterval = setInterval(async () => {
    await loadWhatsAppStatus();
  }, 5000);
}

function stopWhatsAppPolling() {
  if (whatsappStatusInterval) {
    clearInterval(whatsappStatusInterval);
    whatsappStatusInterval = null;
  }
}

async function resetWhatsAppSession() {
  if (!confirm('Isso vai desconectar o WhatsApp atual e apagar a sessão salva. Deseja continuar?')) {
    return;
  }

  if (state.whatsappCrm.loading) {
    return;
  }
  state.whatsappCrm.loading = true;
  renderWhatsAppRouteFront();
  try {
    const response = await api('/api/whatsapp/reset-session', { method: 'POST' });
    showFeedback(response.message || 'Sessão WhatsApp resetada.');
    if (getCurrentSection() === "whatsapp-crm" || window.location.pathname === "/whatsapp-crm") {
      await loadWhatsAppCrmFront({ refreshQr: false, refreshLogs: true });
    } else {
      await loadWhatsAppStatus();
    }
  } catch (error) {
    if (error.message && error.message.includes('EBUSY')) {
      showFeedback('Não foi possível limpar a sessão agora. Feche processos do Chrome/WhatsApp e tente novamente.', 'error');
    } else {
      handleUiError('Erro ao resetar sessão WhatsApp', error);
    }
  } finally {
    state.whatsappCrm.loading = false;
    renderWhatsAppRouteFront();
  }
}
async function startAutomaticBulk(campaignId) {
  if (state.automaticBulkActive) {
    showFeedback('Disparo automático já está em andamento.', 'error');
    return;
  }

  try {
    const campaign = state.campaigns.find(c => c.id === campaignId);
    if (!campaign) {
      showFeedback('Campanha não encontrada.', 'error');
      return;
    }

    const contacts = await api(`/api/campaigns/${campaignId}/contacts`);
    if (!contacts.length) {
      showFeedback('Campanha não possui contatos.', 'error');
      return;
    }

    state.automaticBulkActive = true;
    state.automaticBulkPaused = false;
    updateAutomaticBulkUI();

    const progressDiv = document.getElementById('automatic-progress');
    progressDiv.innerHTML = '<p>Iniciando disparo automático...</p>';

    for (let i = 0; i < contacts.length; i++) {
      if (!state.automaticBulkActive || state.automaticBulkPaused) {
        break;
      }

      const contact = contacts[i];
      progressDiv.innerHTML = `<p>Enviando para ${contact.name}... aguardando delay</p>`;

      try {
        // Verificar se a campanha tem mídia
        const endpoint = (campaign.send_type && campaign.send_type !== 'text')
          ? '/api/whatsapp/send-media'
          : '/api/whatsapp/send-bulk';

        const payload = {
          contactId: contact.id,
          campaignId: campaignId
        };

        if (campaign.send_type && campaign.send_type !== 'text') {
          // Para mídia, incluir os dados específicos
          payload.sendType = campaign.send_type;
          payload.mediaId = campaign.media_id;
          payload.caption = campaign.caption;
          payload.message = campaign.template;
        } else {
          // Para texto apenas
          payload.message = campaign.template;
        }

        await api(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });

        progressDiv.innerHTML = `<p>✅ Enviado para ${contact.name} (${i + 1}/${contacts.length})</p>`;

        // Aguardar delay se não for o último
        if (i < contacts.length - 1) {
          const delay = Math.floor(Math.random() * (40000 - 15000 + 1)) + 15000;
          progressDiv.innerHTML = `<p>⏳ Aguardando ${Math.round(delay / 1000)}s para o próximo...</p>`;
          await new Promise(resolve => setTimeout(resolve, delay));
        }

      } catch (error) {
        console.error('Erro ao enviar para', contact.name, ':', error);
        progressDiv.innerHTML = `<p>❌ Erro ao enviar para ${contact.name}: ${error.message}</p>`;
        // Continuar para o próximo mesmo com erro
      }
    }

    state.automaticBulkActive = false;
    updateAutomaticBulkUI();
    progressDiv.innerHTML = '<p>Disparo automático concluído!</p>';

    // Recarregar dados
    await Promise.all([loadDashboard(), loadCampaignExecutionReport(), loadCampaigns(), loadReports()]);
    showFeedback('Disparo automático concluído.');

  } catch (error) {
    state.automaticBulkActive = false;
    updateAutomaticBulkUI();
    handleUiError('Erro no disparo automático', error);
  }
}

function pauseAutomaticBulk() {
  state.automaticBulkPaused = !state.automaticBulkPaused;
  updateAutomaticBulkUI();
  showFeedback(state.automaticBulkPaused ? 'Disparo pausado.' : 'Disparo retomado.');
}

function updateAutomaticBulkUI() {
  const startButton = document.getElementById('start-automatic-bulk');
  const pauseButton = document.getElementById('pause-automatic-bulk');

  if (state.automaticBulkActive) {
    startButton.disabled = true;
    pauseButton.style.display = 'inline-block';
    pauseButton.textContent = state.automaticBulkPaused ? '▶️ Retomar Disparo' : '⏸️ Pausar Disparo';
  } else {
    startButton.disabled = false;
    pauseButton.style.display = 'none';
  }
}

function updateCampaignCaptionVisibility() {
  const sendType = document.getElementById("campaign-send-type").value;
  const captionContainer = document.getElementById("campaign-caption-container");
  const mediaFile = document.getElementById("campaign-media-file");

  if (sendType === 'image_with_caption' || sendType === 'video_with_caption') {
    captionContainer.style.display = 'block';
  } else {
    captionContainer.style.display = 'none';
    document.getElementById("campaign-caption").value = '';
  }

  // Mostrar/esconder campo de mídia baseado no tipo
  if (sendType === 'text') {
    mediaFile.style.display = 'none';
    mediaFile.value = '';
    document.getElementById("campaign-media-preview").style.display = 'none';
  } else {
    mediaFile.style.display = 'block';
  }
}

function updateCampaignMediaPreview() {
  const fileInput = document.getElementById("campaign-media-file");
  const previewContainer = document.getElementById("campaign-media-preview");
  const previewContent = document.getElementById("campaign-media-preview-content");

  if (fileInput.files && fileInput.files[0]) {
    const file = fileInput.files[0];
    const reader = new FileReader();

    reader.onload = function(e) {
      previewContent.innerHTML = '';

      if (file.type.startsWith('image/')) {
        const img = document.createElement('img');
        img.src = e.target.result;
        img.style.maxWidth = '200px';
        img.style.maxHeight = '200px';
        img.style.border = '1px solid #ddd';
        img.style.borderRadius = '4px';
        previewContent.appendChild(img);
      } else if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.src = e.target.result;
        video.style.maxWidth = '200px';
        video.style.maxHeight = '200px';
        video.style.border = '1px solid #ddd';
        video.style.borderRadius = '4px';
        video.controls = true;
        previewContent.appendChild(video);
      }

      previewContainer.style.display = 'block';
    };

    reader.readAsDataURL(file);
  } else {
    previewContainer.style.display = 'none';
  }
}

function updateIndividualSendCaptionVisibility() {
  const sendType = document.getElementById("individual-send-type").value;
  const captionContainer = document.getElementById("individual-send-caption-container");
  const mediaFile = document.getElementById("individual-send-media");

  if (sendType === 'image_with_caption' || sendType === 'video_with_caption') {
    captionContainer.style.display = 'block';
  } else {
    captionContainer.style.display = 'none';
    document.getElementById("individual-send-caption").value = '';
  }

  // Mostrar/esconder campo de mídia baseado no tipo
  if (sendType === 'text') {
    mediaFile.style.display = 'none';
    mediaFile.value = '';
  } else {
    mediaFile.style.display = 'block';
  }
}

function openIndividualSendModal(contact) {
  document.getElementById("individual-send-contact-id").value = contact.id;
  document.getElementById("individual-send-contact-name").textContent = contact.name;
  document.getElementById("individual-send-message").value = `Oi ${contact.name}, aqui é a equipe AEROSTORE. Posso te mostrar as novidades?`;
  document.getElementById("individual-send-type").value = 'text';
  document.getElementById("individual-send-media").value = '';
  document.getElementById("individual-send-caption").value = '';
  updateIndividualSendCaptionVisibility();
  document.getElementById("individual-send-modal").style.display = 'flex';
}

async function sendIndividualMessage(event) {
  event.preventDefault();

  const contactId = document.getElementById("individual-send-contact-id").value;
  const sendType = document.getElementById("individual-send-type").value;
  const message = document.getElementById("individual-send-message").value.trim();
  const mediaFile = document.getElementById("individual-send-media").files[0];
  const caption = document.getElementById("individual-send-caption").value.trim();

  if (!message) {
    showFeedback("Mensagem é obrigatória.", "error");
    return;
  }

  if (sendType !== 'text' && !mediaFile) {
    showFeedback("Mídia é obrigatória para este tipo de envio.", "error");
    return;
  }

  if ((sendType === 'image_with_caption' || sendType === 'video_with_caption') && !caption.trim()) {
    showFeedback("Legenda é obrigatória para este tipo de envio.", "error");
    return;
  }

  try {
    let mediaId = null;

    if (sendType !== 'text' && mediaFile) {
      const formData = new FormData();
      formData.append('media', mediaFile);

      const uploadResponse = await fetch('/api/uploads/media', {
        method: 'POST',
        body: formData,
        credentials: 'include'
      });

      if (!uploadResponse.ok) {
        const errorData = await uploadResponse.json();
        throw new Error(errorData.details || errorData.error || 'Erro desconhecido no upload');
      }

      const uploadResult = await uploadResponse.json();
      mediaId = uploadResult.mediaId;
    }

    const endpoint = sendType !== 'text' ? '/api/whatsapp/send-media' : '/api/whatsapp/send-bulk';
    const payload = {
      contactId: Number(contactId),
      message
    };

    if (sendType !== 'text') {
      payload.sendType = sendType;
      payload.mediaId = mediaId;
      payload.caption = caption;
    }

    await api(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    document.getElementById("individual-send-modal").style.display = 'none';
    showFeedback("Mensagem enviada com sucesso!");

  } catch (error) {
    const errorMsg = error.message || 'Erro desconhecido';
    console.error('Erro ao enviar mensagem individual:', error);
    showFeedback("Erro ao enviar mensagem: " + errorMsg, "error");
  }
}

document.addEventListener("DOMContentLoaded", initApp);
